import { GoogleGenAI, Type } from "@google/genai";
import { Question, Language } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });

export const fetchQuestions = async (language: Language, count: number = 5): Promise<Question[]> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate ${count} objective type questions on Indian History (covering Ancient, Medieval, and Modern periods) in ${language} language. Each question should have 4 options, a correct answer index (0-3), and a short explanation. Make them high quality and historically accurate.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              text: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              },
              correctAnswer: { type: Type.INTEGER },
              explanation: { type: Type.STRING },
              era: { type: Type.STRING }
            },
            required: ["id", "text", "options", "correctAnswer", "explanation", "era"]
          }
        }
      }
    });

    const questions: Question[] = JSON.parse(response.text || "[]");
    return questions;
  } catch (error) {
    console.error("Error fetching questions:", error);
    return [];
  }
};

import React, { useState, useEffect, useCallback } from 'react';
