    setLoading(true);
    setAppState('QUIZ');
    const questions = await fetchQuestions(language, 10);
    setQuiz({
      questions,
      currentIndex: 0,
      score: 0,
      isComplete: false
    });
    setLoading(false);
  };

  const handleAnswer = (index: number) => {
    if (selectedAnswer !== null) return;
    setSelectedAnswer(index);
    setShowExplanation(true);
    if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
      setQuiz(prev => ({ ...prev, score: prev.score + 1 }));
    }
  };

