                <div className="w-12 h-12 border-4 border-orange-600 border-t-transparent rounded-full animate-spin"></div>
                <p className="text-lg font-medium text-orange-800">इतिहास के पन्ने पलट रहे हैं...</p>
              </div>
            ) : quiz.questions.length > 0 ? (
              <div className="space-y-6">
                <div className="flex justify-between items-center text-sm font-semibold text-orange-800">
                  <span>प्रश्न {quiz.currentIndex + 1} / {quiz.questions.length}</span>
