            <p className="text-xl md:text-2xl text-orange-800 font-medium mb-12 italic">
              "{INTRO_SUB}"
            </p>
            <div className="space-y-4">
              <button 
                onClick={startQuiz}
                className="w-full py-4 px-8 bg-orange-600 hover:bg-orange-700 text-white font-bold text-xl rounded-2xl shadow-lg transform hover:scale-105 transition-all duration-200"
              >
                {t.start}
              </button>
            </div>
          </div>
        )}

        {appState === 'QUIZ' && (
          <div className="w-full">
            {loading ? (
              <div className="flex flex-col items-center space-y-4">
                <div className="w-12 h-12 border-4 border-orange-600 border-t-transparent rounded-full animate-spin"></div>
                <p className="text-lg font-medium text-orange-800">इतिहास के पन्ने पलट रहे हैं...</p>
              </div>
            ) : quiz.questions.length > 0 ? (
              <div className="space-y-6">
                <div className="flex justify-between items-center text-sm font-semibold text-orange-800">
                  <span>प्रश्न {quiz.currentIndex + 1} / {quiz.questions.length}</span>
                  <span className="bg-orange-100 px-3 py-1 rounded-full uppercase tracking-wider">{quiz.questions[quiz.currentIndex].era}</span>
                </div>

                <h2 className="text-2xl font-bold text-gray-900 leading-tight">
                  {quiz.questions[quiz.currentIndex].text}
                </h2>

                <div className="grid grid-cols-1 gap-3">
                  {quiz.questions[quiz.currentIndex].options.map((option, idx) => (
                    <button
                      key={idx}
                      onClick={() => handleAnswer(idx)}
                      disabled={selectedAnswer !== null}
                      className={`p-4 text-left rounded-xl border-2 transition-all duration-200 ${
                        selectedAnswer === null 
                          ? 'border-orange-100 hover:border-orange-400 hover:bg-orange-50' 
                          : idx === quiz.questions[quiz.currentIndex].correctAnswer
                            ? 'border-green-500 bg-green-50 text-green-900'
                            : selectedAnswer === idx
                              ? 'border-red-500 bg-red-50 text-red-900'
                              : 'border-gray-100 opacity-50'
                      }`}
                    >
                      <span className="font-bold mr-3">{String.fromCharCode(65 + idx)}.</span>
                      {option}
                    </button>
                  ))}
                </div>

                {showExplanation && (
                  <div className="p-4 bg-blue-50 border-l-4 border-blue-500 rounded-r-xl animate-fade-in">
                    <h4 className="font-bold text-blue-900 mb-1">व्याख्या (Explanation)</h4>
                    <p className="text-blue-800">{quiz.questions[quiz.currentIndex].explanation}</p>
                    <button
                      onClick={nextQuestion}
                      className="mt-4 w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl transition"
                    >
                      {quiz.currentIndex + 1 < quiz.questions.length ? t.next : t.finish}
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="text-center p-8 bg-red-50 rounded-2xl">
                <p className="text-red-800">प्रश्नों को लोड करने में त्रुटि हुई। कृपया पुन: प्रयास करें।</p>
                <button onClick={() => setAppState('LANDING')} className="mt-4 px-6 py-2 bg-orange-600 text-white rounded-lg">वापस जाएं</button>
              </div>
            )}
          </div>
        )}

        {appState === 'RESULT' && (
          <div className="text-center space-y-8 animate-fade-in">
            <div className="relative inline-block">
              <svg className="w-48 h-48">
                <circle cx="96" cy="96" r="88" fill="none" stroke="#fed7aa" strokeWidth="12" />
                <circle 
                  cx="96" cy="96" r="88" fill="none" stroke="#ea580c" strokeWidth="12" 
                  strokeDasharray={`${(quiz.score / quiz.questions.length) * 552.92} 552.92`}
                  strokeLinecap="round"
                  transform="rotate(-90 96 96)"
                />
              </svg>
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="text-4xl font-black text-orange-600">{Math.round((quiz.score / quiz.questions.length) * 100)}%</span>
