              </div>
            </div>

            <div className="space-y-2">
              <h3 className="text-3xl font-bold">{quiz.score === quiz.questions.length ? "अद्भुत!" : "अच्छा प्रयास!"}</h3>
              <p className="text-gray-600">आपने {quiz.questions.length} में से {quiz.score} सही उत्तर दिए।</p>
            </div>

            <div className="flex flex-col sm:flex-row gap-4">
              <button 
                onClick={() => setAppState('LANDING')}
                className="flex-1 py-4 bg-orange-600 text-white font-bold rounded-2xl shadow-lg hover:bg-orange-700 transition"
              >
                {t.restart}
              </button>
              <button 
                 onClick={async () => {
                    setLoading(true);
                    setAppState('QUIZ');
                    const newQs = await fetchQuestions(language, 10);
                    setQuiz({ questions: newQs, currentIndex: 0, score: 0, isComplete: false });
                    setLoading(false);
                 }}
                className="flex-1 py-4 border-2 border-orange-600 text-orange-600 font-bold rounded-2xl hover:bg-orange-50 transition"
              >
                अगले 10 प्रश्न
              </button>
            </div>
          </div>
        )}

        {appState === 'SETTINGS' && (
          <div className="w-full bg-white p-8 rounded-3xl shadow-xl space-y-6">
            <div className="flex items-center justify-between">
              <h2 className="text-2xl font-bold">{t.selectLang}</h2>
              <button onClick={() => setAppState('LANDING')} className="text-gray-400 hover:text-gray-600">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            <div className="grid grid-cols-2 gap-3">
              {LANGUAGES.map((lang) => (
                <button
                  key={lang.code}
                  onClick={() => {
                    setLanguage(lang.code);
                    setAppState('LANDING');
                  }}
                  className={`p-4 rounded-xl border-2 transition-all ${
                    language === lang.code 
                      ? 'border-orange-600 bg-orange-50 font-bold text-orange-700' 
                      : 'border-gray-100 hover:border-orange-200'
                  }`}
                >
                  {lang.name}
                </button>
              ))}
            </div>
          </div>
        )}
      </main>

      <footer className="w-full p-6 text-center text-gray-400 text-sm">
        &copy; {new Date().getFullYear()} {APP_NAME}. भारत का स्वर्णिम इतिहास।
      </footer>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { Question, Language } from "../types";

// Always use the direct process.env.API_KEY when initializing the GoogleGenAI client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const fetchQuestions = async (language: Language, count: number = 5): Promise<Question[]> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate ${count} objective type questions on Indian History (covering Ancient, Medieval, and Modern periods) in ${language} language. Each question should have 4 options, a correct answer index (0-3), and a short explanation. Make them high quality and historically accurate.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              text: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              },
              correctAnswer: { type: Type.INTEGER },
              explanation: { type: Type.STRING },
              era: { type: Type.STRING }
            },
            required: ["id", "text", "options", "correctAnswer", "explanation", "era"]
          }
        }
      }
    });

    // The GenerateContentResponse object features a text property (not a method)
    const questions: Question[] = JSON.parse(response.text || "[]");
    return questions;
  } catch (error) {
    console.error("Error fetching questions:", error);
    return [];
  }
};

