export default App;

export enum Language {
  HINDI = 'HINDI',
  ENGLISH = 'ENGLISH',
  SANSKRIT = 'SANSKRIT',
  TAMIL = 'TAMIL',
  TELUGU = 'TELUGU',
  MARATHI = 'MARATHI',
  BENGALI = 'BENGALI',
  GUJARATI = 'GUJARATI'
}

export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD'
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
  era: 'Ancient' | 'Medieval' | 'Modern';
}

export type AppState = 'LANDING' | 'DIFFICULTY_SELECT' | 'QUIZ' | 'SETTINGS' | 'RESULT';

export interface QuizState {
  questions: Question[];
  currentIndex: number;
  score: number;
  isComplete: boolean;
  difficulty: Difficulty;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Question, Language, Difficulty } from "../types";

// Always use the direct process.env.API_KEY when initializing the GoogleGenAI client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getDifficultyInstruction = (difficulty: Difficulty) => {
  switch (difficulty) {
    case Difficulty.EASY:
      return "The questions should be basic, focusing on famous events, figures, and widely known facts.";
    case Difficulty.MEDIUM:
      return "The questions should be of intermediate level, requiring good academic knowledge of Indian history.";
    case Difficulty.HARD:
      return "The questions should be challenging, focusing on obscure details, deep historical analysis, and specific dates or minor dynasties.";
    default:
      return "";
  }
};

export const fetchQuestions = async (language: Language, difficulty: Difficulty, count: number): Promise<Question[]> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Generate ${count} objective type questions on Indian History (covering Ancient, Medieval, and Modern periods) in ${language} language. ${getDifficultyInstruction(difficulty)} Each question should have 4 options, a correct answer index (0-3), and a short explanation. Make them high quality and historically accurate.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              text: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: { type: Type.STRING }
              },
              correctAnswer: { type: Type.INTEGER },
              explanation: { type: Type.STRING },
              era: { type: Type.STRING }
            },
            required: ["id", "text", "options", "correctAnswer", "explanation", "era"]
          }
        }
      }
    });

    // The GenerateContentResponse object features a text property (not a method)
    const questions: Question[] = JSON.parse(response.text || "[]");
    return questions;
  } catch (error) {
    console.error("Error fetching questions:", error);
    return [];
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Language, Question, QuizState, Difficulty } from './types';
import { fetchQuestions } from './services/geminiService';
import { AUTHOR_NAME, APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState>({
    questions: [],
    currentIndex: 0,
    score: 0,
    isComplete: false,
    difficulty: Difficulty.MEDIUM
  });
  const [loading, setLoading] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);

  const audioCtxRef = useRef<AudioContext | null>(null);

  const t = TRANSLATIONS[language];

  const getAudioContext = () => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioCtxRef.current;
  };

  const playSound = (type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    const ctx = getAudioContext();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.connect(gain);
    gain.connect(ctx.destination);

    const now = ctx.currentTime;

    if (type === 'correct') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(523.25, now); // C5
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1); // A5
      gain.gain.setValueAtTime(0.1, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'incorrect') {
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(220, now); // A3
      osc.frequency.linearRampToValueAtTime(110, now + 0.2); // A2
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'nav') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(800, now);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
      osc.start(now);
      osc.stop(now + 0.1);
    }
  };

  const startQuiz = async (difficulty: Difficulty) => {
    playSound('nav');
    setLoading(true);
    setAppState('QUIZ');
    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    const questions = await fetchQuestions(language, difficulty, config.count);
    setQuiz({
      questions,
      currentIndex: 0,
      score: 0,
      isComplete: false,
      difficulty
    });
    setLoading(false);
  };

  const handleAnswer = (index: number) => {
    if (selectedAnswer !== null) return;
    setSelectedAnswer(index);
    setShowExplanation(true);
    if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
      playSound('correct');
      setQuiz(prev => ({ ...prev, score: prev.score + 1 }));
    } else {
      playSound('incorrect');
    }
  };

  const nextQuestion = () => {
    playSound('nav');
    setSelectedAnswer(null);
    setShowExplanation(false);
    if (quiz.currentIndex + 1 < quiz.questions.length) {
      setQuiz(prev => ({ ...prev, currentIndex: prev.currentIndex + 1 }));
    } else {
      setAppState('RESULT');
    }
  };

  const togglePrimaryLanguage = () => {
    playSound('nav');
    setLanguage(prev => prev === Language.HINDI ? Language.ENGLISH : Language.HINDI);
  };

  const handleNav = (state: AppState) => {
    playSound('nav');
    setAppState(state);
  };

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800">
      {/* Header */}
      <header className="w-full p-4 flex justify-between items-center bg-orange-600 text-white shadow-md">
        <span className="font-bold text-lg cursor-pointer" onClick={() => handleNav('LANDING')}>{AUTHOR_NAME}</span>
        <div className="flex gap-2">
          <button 
            onClick={togglePrimaryLanguage}
            className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded text-sm transition font-medium"
          >
            {language === Language.HINDI ? 'English' : 'हिन्दी'}
          </button>
          <button 
            onClick={() => handleNav('SETTINGS')}
            className="p-1 hover:bg-white/10 rounded-full transition"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
          </button>
        </div>
      </header>

      <main className="flex-1 w-full max-w-2xl px-4 py-8 flex flex-col items-center justify-center">
        {appState === 'LANDING' && (
          <div className="text-center animate-fade-in">
            <h1 className="text-6xl md:text-8xl font-black text-orange-600 mb-2 hindi-font tracking-tighter drop-shadow-sm">
              {INTRO_MAIN}
            </h1>
            <p className="text-xl md:text-2xl text-orange-800 font-medium mb-12 italic">
              "{INTRO_SUB}"
            </p>
            <div className="space-y-4">
              <button 
                onClick={() => handleNav('DIFFICULTY_SELECT')}
                className="w-full py-4 px-8 bg-orange-600 hover:bg-orange-700 text-white font-bold text-xl rounded-2xl shadow-lg transform hover:scale-105 transition-all duration-200"
              >
                {t.start}
              </button>
            </div>
          </div>
        )}

        {appState === 'DIFFICULTY_SELECT' && (
          <div className="w-full max-w-md space-y-6 animate-fade-in">
            <div className="text-center mb-8">
              <h2 className="text-3xl font-bold text-orange-900">{t.selectDifficulty}</h2>
            </div>
            <div className="grid grid-cols-1 gap-4">
              {DIFFICULTIES.map((diff) => (
                <button
                  key={diff.code}
                  onClick={() => startQuiz(diff.code)}
                  className="group relative overflow-hidden p-6 bg-white border-2 border-orange-100 hover:border-orange-500 rounded-2xl shadow-sm hover:shadow-md transition-all duration-300 text-left"
                >
                  <div className="flex justify-between items-center">
                    <div>
                      <h3 className="text-xl font-bold text-gray-900 group-hover:text-orange-600 transition-colors">
                        {t[diff.code]}
                      </h3>
                    </div>
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 text-orange-400 group-hover:translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                    </svg>
                  </div>
                </button>
              ))}
            </div>
            <button 
              onClick={() => handleNav('LANDING')}
              className="w-full py-3 text-gray-500 font-medium hover:text-orange-600 transition"
            >
              वपस जाएं (Back)
            </button>
          </div>
        )}

        {appState === 'QUIZ' && (
          <div className="w-full">
            {loading ? (
              <div className="flex flex-col items-center space-y-4">
                <div className="w-12 h-12 border-4 border-orange-600 border-t-transparent rounded-full animate-spin"></div>
                <p className="text-lg font-medium text-orange-800">इतिहास के पन्ने पलट रहे हैं...</p>
              </div>
            ) : quiz.questions.length > 0 ? (
              <div className="space-y-6">
                <div className="flex justify-between items-center text-sm font-semibold text-orange-800">
                  <div className="flex flex-col">
                    <span>प्रश्न {quiz.currentIndex + 1} / {quiz.questions.length}</span>
                    <span className="text-[10px] text-orange-400 uppercase tracking-widest">{t[quiz.difficulty]}</span>
                  </div>
                  <span className="bg-orange-100 px-3 py-1 rounded-full uppercase tracking-wider">{quiz.questions[quiz.currentIndex].era}</span>
                </div>

                <h2 className="text-2xl font-bold text-gray-900 leading-tight">
                  {quiz.questions[quiz.currentIndex].text}
                </h2>

                <div className="grid grid-cols-1 gap-3">
                  {quiz.questions[quiz.currentIndex].options.map((option, idx) => (
                    <button
                      key={idx}
                      onClick={() => handleAnswer(idx)}
                      disabled={selectedAnswer !== null}
                      className={`p-4 text-left rounded-xl border-2 transition-all duration-200 ${
