            <div className="flex flex-col sm:flex-row gap-5 w-full max-w-lg mx-auto">
              <button 
                onClick={() => handleNav('LANDING')}
                className="flex-1 py-5 bg-white border-4 border-orange-600 text-orange-600 font-black rounded-3xl shadow-xl hover:bg-orange-50 transition transform hover:scale-105"
              >
                मुख्य पृष्ठ (HOME)
              </button>
              <button 
                 onClick={() => startQuiz(quiz.difficulty)}
                className="flex-1 py-5 bg-orange-600 text-white font-black rounded-3xl shadow-xl hover:bg-orange-700 transition transform hover:scale-105"
              >
                पुनः प्रयास (RETRY)
              </button>
            </div>
          </div>
        )}

        {appState === 'SETTINGS' && (
          <div className="w-full bg-white p-10 rounded-[3rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.3)] space-y-10 border-4 border-orange-50">
            <div className="flex items-center justify-between border-b-2 border-orange-100 pb-6">
              <h2 className="text-4xl font-black text-gray-900 tracking-tighter">{t.settings}</h2>
              <button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            <section className="space-y-6">
              <h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider">
                <span className="bg-orange-100 p-2 rounded-xl">🔊</span>
                {t.soundEffects}
              </h3>
              <div className="flex gap-4">
                <button 
                  onClick={() => { setSoundEnabled(true); playSound('nav'); }}
                  className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${soundEnabled ? 'bg-orange-600 text-white shadow-orange-200' : 'bg-gray-100 text-gray-400 grayscale'}`}
                >
                  {t.on}
                </button>
                <button 
                  onClick={() => setSoundEnabled(false)}
                  className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${!soundEnabled ? 'bg-orange-600 text-white shadow-orange-200' : 'bg-gray-100 text-gray-400 grayscale'}`}
                >
                  {t.off}
                </button>
              </div>
            </section>

            <section className="space-y-6">
              <h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider">
                 <span className="bg-orange-100 p-2 rounded-xl">🌐</span>
                {t.selectLang}
              </h3>
              <div className="grid grid-cols-2 gap-4">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => {
                      setLanguage(lang.code);
                      playSound('nav');
                    }}
                    className={`p-4 rounded-2xl border-4 transition-all text-lg font-black ${
                      language === lang.code 
                        ? 'border-orange-600 bg-orange-50 text-orange-600 shadow-inner' 
                        : 'border-gray-50 hover:border-orange-200 bg-gray-50/50 text-gray-400'
                    }`}
                  >
                    {lang.name}
                  </button>
                ))}
              </div>
            </section>
          </div>
        )}
      </main>

      <footer className="w-full p-8 text-center">
        <div className="max-w-xs mx-auto h-px bg-orange-100 mb-6"></div>
        <p className="text-gray-400 text-sm font-bold uppercase tracking-[0.4em]">
           &copy; {new Date().getFullYear()} {APP_NAME}
        </p>
        <p className="text-orange-900/30 text-[10px] mt-2 font-black tracking-widest">BHARAT VARSHA HISTORY PROJECT</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Language, Question, QuizState, Difficulty } from './types';
import { fetchQuestions } from './services/geminiService';
import { AUTHOR_NAME, APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES } from './constants';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState>({
    questions: [],
    currentIndex: 0,
    score: 0,
    isComplete: false,
    difficulty: Difficulty.MEDIUM,
    timeRemaining: 0,
    totalQuestions: 0
  });
  const [loading, setLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);

  const t = TRANSLATIONS[language];

  // Timer Effect
  useEffect(() => {
    if (appState === 'QUIZ' && quiz.timeRemaining > 0 && !loading) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [appState, loading]);

  const handleTimeUp = () => {
    playSound('incorrect');
    setAppState('RESULT');
  };

  const getAudioContext = () => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioCtxRef.current;
  };

  const playSound = (type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    const ctx = getAudioContext();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.connect(gain);
    gain.connect(ctx.destination);

    const now = ctx.currentTime;

    if (type === 'correct') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(523.25, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0.1, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'incorrect') {
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(220, now);
      osc.frequency.linearRampToValueAtTime(110, now + 0.2);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'nav') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(800, now);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
      osc.start(now);
      osc.stop(now + 0.1);
    }
  };

  const formatTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${h > 0 ? h + ':' : ''}${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  // Background sync function to fetch the remaining questions in chunks
  const backgroundSync = async (difficulty: Difficulty, target: number, currentLang: Language) => {
    if (syncRef.current) return;
    syncRef.current = true;
    setIsSyncing(true);

    let currentCount = 10; // Assuming we start with 10
    const BATCH_SIZE = 15; // Smaller chunks for better reliability

    while (currentCount < target && appState === 'QUIZ') {
      const remaining = target - currentCount;
      const fetchCount = Math.min(BATCH_SIZE, remaining);

      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, fetchCount);
        if (moreQuestions.length === 0) break; // Stop if API fails

        setQuiz(prev => ({
          ...prev,
          questions: [...prev.questions, ...moreQuestions]
        }));
        currentCount += moreQuestions.length;
      } catch (err) {
        console.error("Sync error:", err);
        break;
      }
      // Small delay to prevent hitting API limits too fast
      await new Promise(r => setTimeout(r, 2000));
    }

    setIsSyncing(false);
    syncRef.current = false;
  };

  const startQuiz = async (difficulty: Difficulty) => {
    playSound('nav');
    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true);
    setAppState('QUIZ');
    syncRef.current = false; // Reset sync flag

    // Initial fetch of 10 questions for snappy start
    const initialQuestions = await fetchQuestions(language, difficulty, 10);

    setQuiz({
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      isComplete: false,
      difficulty,
      timeRemaining: config.time,
      totalQuestions: config.count
    });
    setLoading(false);

    // Start background syncing the rest of the questions
    backgroundSync(difficulty, config.count, language);
  };

  const handleAnswer = (index: number) => {
    if (selectedAnswer !== null) return;
    setSelectedAnswer(index);
    setShowExplanation(true);
    if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
      playSound('correct');
      setQuiz(prev => ({ ...prev, score: prev.score + 1 }));
    } else {
      playSound('incorrect');
    }
  };

  const nextQuestion = () => {
    playSound('nav');
    setSelectedAnswer(null);
    setShowExplanation(false);

    if (quiz.currentIndex + 1 < quiz.totalQuestions) {
      // If user caught up to the buffer, show loader
      if (quiz.currentIndex + 1 >= quiz.questions.length) {
        setLoading(true);
        // The background sync should ideally have fetched more, 
        // but if not, we wait briefly or trigger a specific fetch.
        // We'll just let the sync handle it and check back.
        const checkBuffer = setInterval(() => {
          setQuiz(prev => {
            if (prev.currentIndex + 1 < prev.questions.length) {
              clearInterval(checkBuffer);
              setLoading(false);
              return { ...prev, currentIndex: prev.currentIndex + 1 };
            }
            return prev;
          });
        }, 500);
      } else {
        setQuiz(prev => ({ ...prev, currentIndex: prev.currentIndex + 1 }));
      }
    } else {
      setAppState('RESULT');
    }
  };

  const togglePrimaryLanguage = () => {
    playSound('nav');
    setLanguage(prev => prev === Language.HINDI ? Language.ENGLISH : Language.HINDI);
  };

  const handleNav = (state: AppState) => {
    playSound('nav');
    setAppState(state);
    if (state !== 'QUIZ') {
      syncRef.current = false;
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800">
      {/* Header */}
      <header className="w-full p-4 flex justify-between items-center bg-orange-600 text-white shadow-md z-10 sticky top-0">
        <span className="font-bold text-lg cursor-pointer flex items-center gap-2" onClick={() => handleNav('LANDING')}>
          <span className="bg-white text-orange-600 w-8 h-8 rounded-full flex items-center justify-center font-black">इ</span>
          {AUTHOR_NAME}
        </span>

        {appState === 'QUIZ' && (
          <div className="flex items-center gap-3 bg-white/20 px-3 py-1.5 rounded-full font-mono font-bold text-sm">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <span className={quiz.timeRemaining < 60 ? 'text-yellow-300 animate-pulse' : ''}>
              {formatTime(quiz.timeRemaining)}
            </span>
          </div>
        )}

        <div className="flex gap-2">
          <button 
            onClick={togglePrimaryLanguage}
            className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded text-sm transition font-medium hidden sm:block"
          >
            {language === Language.HINDI ? 'English' : 'हिन्दी'}
          </button>
          <button 
            onClick={() => handleNav('SETTINGS')}
            className="p-1 hover:bg-white/10 rounded-full transition"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
          </button>
        </div>
      </header>

      <main className="flex-1 w-full max-w-2xl px-4 py-8 flex flex-col items-center justify-center">
        {appState === 'LANDING' && (
          <div className="text-center animate-fade-in py-10">
            <h1 className="text-6xl md:text-9xl font-black text-orange-600 mb-2 hindi-font tracking-tighter drop-shadow-xl select-none">
              {INTRO_MAIN}
            </h1>
            <p className="text-xl md:text-3xl text-orange-800 font-bold mb-12 italic opacity-80">
              "{INTRO_SUB}"
            </p>
            <div className="space-y-4 max-w-sm mx-auto">
              <button 
                onClick={() => handleNav('DIFFICULTY_SELECT')}
                className="w-full py-5 px-8 bg-orange-600 hover:bg-orange-700 text-white font-black text-2xl rounded-3xl shadow-2xl transform hover:scale-105 active:scale-95 transition-all duration-200 uppercase tracking-widest"
              >
                {t.start}
              </button>
              <p className="text-sm text-orange-400 font-medium">भारतीय इतिहास की एक महायात्रा</p>
            </div>
          </div>
        )}

        {appState === 'DIFFICULTY_SELECT' && (
          <div className="w-full max-w-md space-y-6 animate-fade-in">
            <div className="text-center mb-10">
              <h2 className="text-4xl font-black text-orange-900 drop-shadow-sm">{t.selectDifficulty}</h2>
              <p className="text-orange-700/60 mt-2">अपनी क्षमतानुसार चुनौती चुनें</p>
            </div>
            <div className="grid grid-cols-1 gap-5">
              {DIFFICULTIES.map((diff) => (
                <button
                  key={diff.code}
                  onClick={() => startQuiz(diff.code)}
                  className="group relative overflow-hidden p-6 bg-white border-4 border-orange-50 hover:border-orange-500 rounded-3xl shadow-lg hover:shadow-2xl transition-all duration-300 text-left"
                >
                  <div className="flex justify-between items-center relative z-10">
                    <div>
                      <h3 className="text-2xl font-black text-gray-900 group-hover:text-orange-600 transition-colors">
                        {t[diff.code]}
                      </h3>
                      <div className="flex gap-4 mt-2 text-sm font-bold text-gray-400 uppercase tracking-tighter">
                        <span className="flex items-center gap-1">
                          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M9 2a1 1 0 000 2h2a1 1 0 100-2H9z"/><path fillRule="evenodd" d="M4 5a2 2 0 012-2 3 3 0 003 3h2a3 3 0 003-3 2 2 0 012 2v11a2 2 0 01-2 2H6a2 2 0 01-2-2V5zm3 4a1 1 0 000 2h.01a1 1 0 100-2H7zm3 0a1 1 0 000 2h3a1 1 0 100-2h-3zm-3 4a1 1 0 100 2h.01a1 1 0 100-2H7zm3 0a1 1 0 100 2h3a1 1 0 100-2h-3z" clipRule="evenodd"/></svg>
                          {diff.count} {t.questions}
                        </span>
                        <span className="flex items-center gap-1">
                          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z" clipRule="evenodd"/></svg>
                          {diff.time / 60} {t.minutes}
                        </span>
                      </div>
                    </div>
                    <div className="bg-orange-50 p-3 rounded-2xl group-hover:bg-orange-100 transition-colors">
                       <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-orange-600 group-hover:translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" />
                      </svg>
                    </div>
                  </div>
                </button>
              ))}
            </div>
            <button 
              onClick={() => handleNav('LANDING')}
              className="w-full py-4 text-gray-400 font-bold hover:text-orange-600 transition tracking-widest text-sm"
            >
              वपस जाएं (BACK TO HOME)
            </button>
          </div>
        )}

        {appState === 'QUIZ' && (
          <div className="w-full pb-20">
            {loading ? (
              <div className="flex flex-col items-center justify-center min-h-[400px] space-y-6">
                <div className="relative">
                  <div className="w-20 h-20 border-8 border-orange-100 rounded-full"></div>
                  <div className="w-20 h-20 border-8 border-orange-600 border-t-transparent rounded-full animate-spin absolute top-0"></div>
                </div>
                <div className="text-center">
                  <p className="text-2xl font-black text-orange-900 animate-pulse">
                    {quiz.questions.length < quiz.totalQuestions && quiz.currentIndex >= quiz.questions.length - 1 
                      ? "अगले प्रश्नों को संजोया जा रहा है..." 
                      : "इतिहास के पन्ने खुल रहे हैं..."}
                  </p>
                  <p className="text-orange-700/60 font-medium italic">
                    {isSyncing ? "पृष्ठभूमि में ज्ञान संचय जारी है..." : "कृपया प्रतीक्षा करें"}
                  </p>
                </div>
              </div>
            ) : quiz.questions.length > 0 && quiz.questions[quiz.currentIndex] ? (
              <div className="space-y-8">
                {/* Progress Bar */}
                <div className="w-full bg-orange-100 h-3 rounded-full overflow-hidden shadow-inner border border-orange-200">
                  <div 
                    className="bg-orange-600 h-full transition-all duration-500 ease-out"
                    style={{ width: `${((quiz.currentIndex + 1) / quiz.totalQuestions) * 100}%` }}
                  ></div>
                </div>

                <div className="flex justify-between items-center text-sm font-black text-orange-900">
                  <div className="flex flex-col">
                    <span className="uppercase tracking-widest text-xs opacity-50">{t[quiz.difficulty]}</span>
                    <span className="text-lg">प्रसंग {quiz.currentIndex + 1} / {quiz.totalQuestions}</span>
                  </div>
                  <div className="flex flex-col items-end gap-1">
                    <div className="bg-orange-600 text-white px-4 py-1.5 rounded-2xl shadow-md uppercase tracking-tighter">
                      {quiz.questions[quiz.currentIndex].era}
                    </div>
                    {isSyncing && (
                       <span className="text-[9px] text-orange-400 font-black animate-pulse uppercase tracking-widest">
                         LOADING {quiz.questions.length}/{quiz.totalQuestions}
                       </span>
                    )}
                  </div>
                </div>

                <h2 className="text-3xl md:text-4xl font-black text-gray-900 leading-tight hindi-font">
                  {quiz.questions[quiz.currentIndex].text}
                </h2>

                <div className="grid grid-cols-1 gap-4">
                  {quiz.questions[quiz.currentIndex].options.map((option, idx) => (
                    <button
                      key={idx}
                      onClick={() => handleAnswer(idx)}
                      disabled={selectedAnswer !== null}
                      className={`group p-5 text-left rounded-3xl border-4 transition-all duration-200 flex items-center ${
                        selectedAnswer === null 
                          ? 'border-orange-50 bg-white hover:border-orange-600 hover:shadow-xl' 
                          : idx === quiz.questions[quiz.currentIndex].correctAnswer
                            ? 'border-green-600 bg-green-50 text-green-900 ring-8 ring-green-100'
                            : selectedAnswer === idx
                              ? 'border-red-600 bg-red-50 text-red-900 ring-8 ring-red-100'
                              : 'border-gray-100 opacity-40 grayscale'
                      }`}
                    >
                      <span className={`w-10 h-10 rounded-full flex items-center justify-center font-black mr-4 text-lg border-2 transition-colors ${
                        selectedAnswer === null 
                          ? 'bg-orange-50 border-orange-200 text-orange-600 group-hover:bg-orange-600 group-hover:text-white'
                          : idx === quiz.questions[quiz.currentIndex].correctAnswer
                            ? 'bg-green-600 border-green-600 text-white'
                            : selectedAnswer === idx
                              ? 'bg-red-600 border-red-600 text-white'
                              : 'bg-gray-200 text-gray-400'
                      }`}>
                        {String.fromCharCode(65 + idx)}
                      </span>
                      <span className="text-xl font-bold">{option}</span>
                    </button>
                  ))}
                </div>

                {showExplanation && (
                  <div className="p-8 bg-blue-50 border-4 border-blue-600 rounded-[2.5rem] animate-fade-in shadow-xl relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-4 opacity-10">
                       <svg className="w-20 h-20" fill="currentColor" viewBox="0 0 20 20"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM15.657 5.757a1 1 0 00-1.414-1.414l-.707.707a1 1 0 001.414 1.414l.707-.707zM18 10a1 1 0 01-1 1h-1a1 1 0 110-2h1a1 1 0 011 1zM5.05 6.464A1 1 0 106.464 5.05l-.707-.707a1 1 0 00-1.414 1.414l.707.707zM5 10a1 1 0 01-1 1H3a1 1 0 110-2h1a1 1 0 011 1zM8 16v-1a1 1 0 112 0v1a1 1 0 11-2 0zM13.536 14.243a1 1 0 011.414 1.414l-.707.707a1 1 0 01-1.414-1.414l.707-.707zM16 18a1 1 0 100-2h-1a1 1 0 100 2h1z" /></svg>
                    </div>
                    <h4 className="font-black text-blue-900 mb-2 uppercase tracking-tighter flex items-center gap-2">
                       इतिहास का सार (In-Depth Explanation)
                    </h4>
                    <p className="text-blue-800 text-lg leading-relaxed font-medium">{quiz.questions[quiz.currentIndex].explanation}</p>
                    <button
                      onClick={nextQuestion}
                      className="mt-8 w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-5 rounded-3xl transition shadow-2xl transform active:scale-95 text-xl uppercase tracking-widest"
                    >
                      {quiz.currentIndex + 1 < quiz.totalQuestions ? t.next : t.finish}
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="text-center p-12 bg-red-50 rounded-[3rem] border-4 border-red-200">
                <p className="text-2xl font-black text-red-800">प्रश्नों को लोड करने में त्रुटि हुई।</p>
                <button onClick={() => handleNav('LANDING')} className="px-10 py-4 bg-orange-600 text-white font-black rounded-3xl shadow-xl mt-6">पुनः प्रयास करें</button>
              </div>
            )}
          </div>
        )}

        {appState === 'RESULT' && (
          <div className="text-center space-y-10 animate-fade-in w-full py-10">
            <div className="relative inline-block">
              <svg className="w-64 h-64 drop-shadow-2xl relative">
                <circle cx="128" cy="128" r="110" fill="none" stroke="#fed7aa" strokeWidth="18" />
                <circle 
                  cx="128" cy="128" r="110" fill="none" stroke="#ea580c" strokeWidth="18" 
                  strokeDasharray={`${(quiz.score / quiz.totalQuestions) * 691.15} 691.15`}
                  strokeLinecap="round"
                  transform="rotate(-90 128 128)"
                  className="transition-all duration-1000 ease-out"
                />
              </svg>
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="text-6xl font-black text-orange-600">{Math.round((quiz.score / quiz.totalQuestions) * 100)}%</span>
                <span className="text-xs font-black text-gray-500 uppercase tracking-[0.3em] mt-1">{t.score}</span>
              </div>
            </div>

            <div className="space-y-4">
              <h3 className="text-5xl font-black text-gray-900 tracking-tighter">
                {quiz.score === quiz.totalQuestions ? "विजेता! (Legendary)" : quiz.score > quiz.totalQuestions / 2 ? "विजयी भव!" : "प्रयास जारी रखें!"}
              </h3>
              <p className="text-2xl text-orange-800 font-bold bg-orange-100 px-6 py-3 rounded-full inline-block">
                आपने {t[quiz.difficulty]} स्तर पर {quiz.totalQuestions} में से {quiz.score} सही उत्तर दिए।
              </p>
            </div>

            <div className="flex flex-col sm:flex-row gap-5 w-full max-w-lg mx-auto">
              <button 
                onClick={() => handleNav('LANDING')}
                className="flex-1 py-5 bg-white border-4 border-orange-600 text-orange-600 font-black rounded-3xl shadow-xl hover:bg-orange-50 transition transform hover:scale-105"
              >
                मुख्य पृष्ठ (HOME)
              </button>
              <button 
                 onClick={() => startQuiz(quiz.difficulty)}
                className="flex-1 py-5 bg-orange-600 text-white font-black rounded-3xl shadow-xl hover:bg-orange-700 transition transform hover:scale-105"
              >
                पुनः प्रयास (RETRY)
              </button>
            </div>
          </div>
        )}

        {appState === 'SETTINGS' && (
          <div className="w-full bg-white p-10 rounded-[3rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.3)] space-y-10 border-4 border-orange-50">
            <div className="flex items-center justify-between border-b-2 border-orange-100 pb-6">
              <h2 className="text-4xl font-black text-gray-900 tracking-tighter">{t.settings}</h2>
              <button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            <section className="space-y-6">
              <h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider">
                <span className="bg-orange-100 p-2 rounded-xl">🔊</span>
                {t.soundEffects}
              </h3>
              <div className="flex gap-4">
                <button 
                  onClick={() => { setSoundEnabled(true); playSound('nav'); }}
                  className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${soundEnabled ? 'bg-orange-600 text-white shadow-orange-200' : 'bg-gray-100 text-gray-400 grayscale'}`}
                >
                  {t.on}
                </button>
                <button 
                  onClick={() => setSoundEnabled(false)}
                  className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${!soundEnabled ? 'bg-orange-600 text-white shadow-orange-200' : 'bg-gray-100 text-gray-400 grayscale'}`}
                >
                  {t.off}
                </button>
              </div>
            </section>

            <section className="space-y-6">
              <h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider">
                 <span className="bg-orange-100 p-2 rounded-xl">🌐</span>
                {t.selectLang}
              </h3>
              <div className="grid grid-cols-2 gap-4">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => {
                      setLanguage(lang.code);
                      playSound('nav');
                    }}
                    className={`p-4 rounded-2xl border-4 transition-all text-lg font-black ${
                      language === lang.code 
                        ? 'border-orange-600 bg-orange-50 text-orange-600 shadow-inner' 
                        : 'border-gray-50 hover:border-orange-200 bg-gray-50/50 text-gray-400'
                    }`}
                  >
                    {lang.name}
                  </button>
                ))}
              </div>
            </section>
          </div>
        )}
      </main>

      <footer className="w-full p-8 text-center">
        <div className="max-w-xs mx-auto h-px bg-orange-100 mb-6"></div>
        <p className="text-gray-400 text-sm font-bold uppercase tracking-[0.4em]">
           &copy; {new Date().getFullYear()} {APP_NAME}
        </p>
        <p className="text-orange-900/30 text-[10px] mt-2 font-black tracking-widest">BHARAT VARSHA HISTORY PROJECT</p>
      </footer>
    </div>
  );
};

export default App;

export enum Language {
  HINDI = 'HINDI',
  ENGLISH = 'ENGLISH',
  SANSKRIT = 'SANSKRIT',
  TAMIL = 'TAMIL',
  TELUGU = 'TELUGU',
  MARATHI = 'MARATHI',
  BENGALI = 'BENGALI',
  GUJARATI = 'GUJARATI'
}

export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD'
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
  era: 'Ancient' | 'Medieval' | 'Modern';
}

export type AppState = 'LANDING' | 'DIFFICULTY_SELECT' | 'QUIZ' | 'SETTINGS' | 'RESULT' | 'BOOKMARKS';

export interface QuizState {
  questions: Question[];
  currentIndex: number;
  score: number;
  isComplete: boolean;
  difficulty: Difficulty;
  timeRemaining: number;
  totalQuestions: number;
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Language, Question, QuizState, Difficulty } from './types';
import { fetchQuestions } from './services/geminiService';
import { AUTHOR_NAME, APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES } from './constants';

const BOOKMARKS_KEY = 'history_bookmarks';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState>({
    questions: [],
    currentIndex: 0,
    score: 0,
    isComplete: false,
    difficulty: Difficulty.MEDIUM,
    timeRemaining: 0,
    totalQuestions: 0
  });
  const [bookmarks, setBookmarks] = useState<Question[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);

  const t = TRANSLATIONS[language];

  // Load bookmarks on init
  useEffect(() => {
    const saved = localStorage.getItem(BOOKMARKS_KEY);
    if (saved) {
      try {
        setBookmarks(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to parse bookmarks", e);
      }
    }
  }, []);

  // Save bookmarks on change
  useEffect(() => {
    localStorage.setItem(BOOKMARKS_KEY, JSON.stringify(bookmarks));
  }, [bookmarks]);

  // Timer Effect
  useEffect(() => {
    if (appState === 'QUIZ' && quiz.timeRemaining > 0 && !loading) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [appState, loading]);

  const handleTimeUp = () => {
    playSound('incorrect');
    setAppState('RESULT');
  };

  const getAudioContext = () => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioCtxRef.current;
  };

  const playSound = (type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    const ctx = getAudioContext();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.connect(gain);
    gain.connect(ctx.destination);

    const now = ctx.currentTime;

    if (type === 'correct') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(523.25, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0.1, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'incorrect') {
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(220, now);
      osc.frequency.linearRampToValueAtTime(110, now + 0.2);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'nav') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(800, now);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
      osc.start(now);
      osc.stop(now + 0.1);
    }
  };

  const formatTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${h > 0 ? h + ':' : ''}${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const backgroundSync = async (difficulty: Difficulty, target: number, currentLang: Language) => {
    if (syncRef.current) return;
    syncRef.current = true;
    setIsSyncing(true);

    let currentCount = 10;
    const BATCH_SIZE = 15;

    while (currentCount < target && syncRef.current) {
      const remaining = target - currentCount;
      const fetchCount = Math.min(BATCH_SIZE, remaining);

      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, fetchCount);
        if (moreQuestions.length === 0) break;

        setQuiz(prev => ({
          ...prev,
          questions: [...prev.questions, ...moreQuestions]
        }));
        currentCount += moreQuestions.length;
      } catch (err) {
        console.error("Sync error:", err);
        break;
      }
      await new Promise(r => setTimeout(r, 2000));
    }

    setIsSyncing(false);
    syncRef.current = false;
  };

  const startQuiz = async (difficulty: Difficulty) => {
    playSound('nav');
    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true);
    setAppState('QUIZ');
    syncRef.current = true;

    const initialQuestions = await fetchQuestions(language, difficulty, 10);

    setQuiz({
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      isComplete: false,
      difficulty,
      timeRemaining: config.time,
      totalQuestions: config.count
    });
    setLoading(false);

    backgroundSync(difficulty, config.count, language);
  };

  const handleAnswer = (index: number) => {
    if (selectedAnswer !== null) return;
    setSelectedAnswer(index);
    setShowExplanation(true);
    if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
      playSound('correct');
      setQuiz(prev => ({ ...prev, score: prev.score + 1 }));
    } else {
      playSound('incorrect');
    }
  };

  const nextQuestion = () => {
    playSound('nav');
    setSelectedAnswer(null);
    setShowExplanation(false);

    if (quiz.currentIndex + 1 < quiz.totalQuestions) {
      if (quiz.currentIndex + 1 >= quiz.questions.length) {
        setLoading(true);
        const checkBuffer = setInterval(() => {
          setQuiz(prev => {
            if (prev.currentIndex + 1 < prev.questions.length) {
              clearInterval(checkBuffer);
              setLoading(false);
              return { ...prev, currentIndex: prev.currentIndex + 1 };
            }
            return prev;
          });
        }, 500);
      } else {
        setQuiz(prev => ({ ...prev, currentIndex: prev.currentIndex + 1 }));
      }
    } else {
      setAppState('RESULT');
    }
  };

  const togglePrimaryLanguage = () => {
    playSound('nav');
    setLanguage(prev => prev === Language.HINDI ? Language.ENGLISH : Language.HINDI);
  };

  const handleNav = (state: AppState) => {
    playSound('nav');
    setAppState(state);
    if (state !== 'QUIZ') {
      syncRef.current = false;
    }
  };

  const toggleBookmark = (q: Question) => {
    playSound('nav');
    setBookmarks(prev => {
      const exists = prev.find(b => b.id === q.id);
      if (exists) {
        return prev.filter(b => b.id !== q.id);
      } else {
        return [...prev, q];
      }
    });
  };

  const isBookmarked = (id: string) => bookmarks.some(b => b.id === id);

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800">
      {/* Header */}
      <header className="w-full p-4 flex justify-between items-center bg-orange-600 text-white shadow-md z-20 sticky top-0">
        <span className="font-bold text-lg cursor-pointer flex items-center gap-2" onClick={() => handleNav('LANDING')}>
          <span className="bg-white text-orange-600 w-8 h-8 rounded-full flex items-center justify-center font-black">इ</span>
          {AUTHOR_NAME}
        </span>

        {appState === 'QUIZ' && (
          <div className="flex items-center gap-3 bg-white/20 px-3 py-1.5 rounded-full font-mono font-bold text-sm">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <span className={quiz.timeRemaining < 60 ? 'text-yellow-300 animate-pulse' : ''}>
              {formatTime(quiz.timeRemaining)}
            </span>
          </div>
        )}

        <div className="flex gap-2">
          <button 
            onClick={() => handleNav('BOOKMARKS')}
            className="bg-white/20 hover:bg-white/30 p-1.5 rounded-full transition relative"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24">
              <path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/>
            </svg>
            {bookmarks.length > 0 && (
               <span className="absolute -top-1 -right-1 bg-white text-orange-600 text-[10px] w-4 h-4 rounded-full flex items-center justify-center font-black shadow-sm">
                 {bookmarks.length}
               </span>
            )}
          </button>
          <button 
            onClick={() => handleNav('SETTINGS')}
            className="p-1.5 hover:bg-white/10 rounded-full transition"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
          </button>
        </div>
      </header>

      <main className="flex-1 w-full max-w-2xl px-4 py-8 flex flex-col items-center justify-center">
        {appState === 'LANDING' && (
          <div className="text-center animate-fade-in py-10">
            <h1 className="text-6xl md:text-9xl font-black text-orange-600 mb-2 hindi-font tracking-tighter drop-shadow-xl select-none">
              {INTRO_MAIN}
            </h1>
            <p className="text-xl md:text-3xl text-orange-800 font-bold mb-12 italic opacity-80">
              "{INTRO_SUB}"
            </p>
            <div className="space-y-4 max-w-sm mx-auto">
              <button 
                onClick={() => handleNav('DIFFICULTY_SELECT')}
                className="w-full py-5 px-8 bg-orange-600 hover:bg-orange-700 text-white font-black text-2xl rounded-3xl shadow-2xl transform hover:scale-105 active:scale-95 transition-all duration-200 uppercase tracking-widest"
              >
                {t.start}
              </button>

              <button 
                onClick={() => handleNav('BOOKMARKS')}
                className="w-full py-3 px-8 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition-all flex items-center justify-center gap-2"
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-orange-600" fill="currentColor" viewBox="0 0 24 24">
                  <path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/>
                </svg>
                {t.bookmarks} ({bookmarks.length})
              </button>

              <p className="text-sm text-orange-400 font-medium">भारतीय इतिहास की एक महायात्रा</p>
            </div>
          </div>
        )}

        {appState === 'BOOKMARKS' && (
          <div className="w-full space-y-6 animate-fade-in pb-10">
            <div className="flex items-center justify-between">
              <h2 className="text-3xl font-black text-orange-900">{t.savedQuestions}</h2>
              <button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            {bookmarks.length === 0 ? (
              <div className="text-center p-20 bg-white border-4 border-dashed border-orange-100 rounded-[3rem]">
                <p className="text-xl text-gray-400 font-medium">{t.noBookmarks}</p>
              </div>
            ) : (
              <div className="space-y-4">
                {bookmarks.map((q) => (
                  <div key={q.id} className="bg-white p-6 rounded-3xl shadow-lg border-2 border-orange-50 relative group">
                    <button 
                      onClick={() => toggleBookmark(q)}
                      className="absolute top-4 right-4 text-orange-600 hover:scale-110 transition-transform"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24">
                        <path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/>
                      </svg>
                    </button>
                    <div className="mb-2">
                       <span className="text-[10px] bg-orange-100 text-orange-600 px-2 py-0.5 rounded-full font-black uppercase tracking-widest">{q.era}</span>
                    </div>
                    <h3 className="text-lg font-bold text-gray-900 pr-8">{q.text}</h3>
                    <div className="mt-4 p-4 bg-orange-50 rounded-xl">
                      <p className="text-sm font-bold text-orange-900 uppercase tracking-tighter mb-1">सही उत्तर (Correct): {q.options[q.correctAnswer]}</p>
                      <p className="text-xs text-orange-800 leading-relaxed italic">{q.explanation}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {appState === 'DIFFICULTY_SELECT' && (
          <div className="w-full max-w-md space-y-6 animate-fade-in">
            <div className="text-center mb-10">
              <h2 className="text-4xl font-black text-orange-900 drop-shadow-sm">{t.selectDifficulty}</h2>
              <p className="text-orange-700/60 mt-2">अपनी क्षमतानुसार चुनौती चुनें</p>
            </div>
            <div className="grid grid-cols-1 gap-5">
              {DIFFICULTIES.map((diff) => (
                <button
                  key={diff.code}
                  onClick={() => startQuiz(diff.code)}
                  className="group relative overflow-hidden p-6 bg-white border-4 border-orange-50 hover:border-orange-500 rounded-3xl shadow-lg hover:shadow-2xl transition-all duration-300 text-left"
                >
                  <div className="flex justify-between items-center relative z-10">
                    <div>
                      <h3 className="text-2xl font-black text-gray-900 group-hover:text-orange-600 transition-colors">
                        {t[diff.code]}
                      </h3>
                      <div className="flex gap-4 mt-2 text-sm font-bold text-gray-400 uppercase tracking-tighter">
                        <span className="flex items-center gap-1">
                          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M9 2a1 1 0 000 2h2a1 1 0 100-2H9z"/><path fillRule="evenodd" d="M4 5a2 2 0 012-2 3 3 0 003 3h2a3 3 0 003-3 2 2 0 012 2v11a2 2 0 01-2 2H6a2 2 0 01-2-2V5zm3 4a1 1 0 000 2h.01a1 1 0 100-2H7zm3 0a1 1 0 000 2h3a1 1 0 100-2h-3zm-3 4a1 1 0 100 2h.01a1 1 0 100-2H7zm3 0a1 1 0 100 2h3a1 1 0 100-2h-3z" clipRule="evenodd"/></svg>
                          {diff.count} {t.questions}
                        </span>
                        <span className="flex items-center gap-1">
                          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z" clipRule="evenodd"/></svg>
                          {diff.time / 60} {t.minutes}
                        </span>
                      </div>
                    </div>
                    <div className="bg-orange-50 p-3 rounded-2xl group-hover:bg-orange-100 transition-colors">
                       <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-orange-600 group-hover:translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" />
                      </svg>
                    </div>
                  </div>
                </button>
              ))}
            </div>
            <button 
              onClick={() => handleNav('LANDING')}
              className="w-full py-4 text-gray-400 font-bold hover:text-orange-600 transition tracking-widest text-sm"
            >
              वपस जाएं (BACK TO HOME)
            </button>
          </div>
        )}

        {appState === 'QUIZ' && (
          <div className="w-full pb-20">
            {loading ? (
              <div className="flex flex-col items-center justify-center min-h-[400px] space-y-6">
                <div className="relative">
                  <div className="w-20 h-20 border-8 border-orange-100 rounded-full"></div>
                  <div className="w-20 h-20 border-8 border-orange-600 border-t-transparent rounded-full animate-spin absolute top-0"></div>
                </div>
                <div className="text-center">
                  <p className="text-2xl font-black text-orange-900 animate-pulse">
                    {quiz.questions.length < quiz.totalQuestions && quiz.currentIndex >= quiz.questions.length - 1 
                      ? "अगले प्रश्नों को संजोया जा रहा है..." 
                      : "इतिहास के पन्ने खुल रहे हैं..."}
                  </p>
                  <p className="text-orange-700/60 font-medium italic">
                    {isSyncing ? "पृष्ठभूमि में ज्ञान संचय जारी है..." : "कृपया प्रतीक्षा करें"}
                  </p>
                </div>
              </div>
            ) : quiz.questions.length > 0 && quiz.questions[quiz.currentIndex] ? (
              <div className="space-y-8">
                {/* Progress Bar */}
                <div className="w-full bg-orange-100 h-3 rounded-full overflow-hidden shadow-inner border border-orange-200">
                  <div 
                    className="bg-orange-600 h-full transition-all duration-500 ease-out"
                    style={{ width: `${((quiz.currentIndex + 1) / quiz.totalQuestions) * 100}%` }}
                  ></div>
                </div>

                <div className="flex justify-between items-center text-sm font-black text-orange-900">
                  <div className="flex flex-col">
                    <span className="uppercase tracking-widest text-xs opacity-50">{t[quiz.difficulty]}</span>
                    <span className="text-lg">प्रसंग {quiz.currentIndex + 1} / {quiz.totalQuestions}</span>
                  </div>
                  <div className="flex items-center gap-3">
                    <button 
                      onClick={() => toggleBookmark(quiz.questions[quiz.currentIndex])}
                      className={`p-2 rounded-full transition-colors border-2 ${isBookmarked(quiz.questions[quiz.currentIndex].id) ? 'bg-orange-600 border-orange-600 text-white' : 'bg-white border-orange-200 text-orange-600 hover:bg-orange-50'}`}
                      title={isBookmarked(quiz.questions[quiz.currentIndex].id) ? "Remove Bookmark" : "Bookmark Question"}
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24">
                        <path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/>
                      </svg>
                    </button>
                    <div className="flex flex-col items-end gap-1">
                      <div className="bg-orange-600 text-white px-4 py-1.5 rounded-2xl shadow-md uppercase tracking-tighter">
                        {quiz.questions[quiz.currentIndex].era}
                      </div>
                      {isSyncing && (
                         <span className="text-[9px] text-orange-400 font-black animate-pulse uppercase tracking-widest">
                           SYNCING {quiz.questions.length}/{quiz.totalQuestions}
                         </span>
                      )}
                    </div>
                  </div>
                </div>

                <h2 className="text-3xl md:text-4xl font-black text-gray-900 leading-tight hindi-font">
                  {quiz.questions[quiz.currentIndex].text}
                </h2>

                <div className="grid grid-cols-1 gap-4">
                  {quiz.questions[quiz.currentIndex].options.map((option, idx) => (
                    <button
                      key={idx}
                      onClick={() => handleAnswer(idx)}
                      disabled={selectedAnswer !== null}
                      className={`group p-5 text-left rounded-3xl border-4 transition-all duration-200 flex items-center ${
                        selectedAnswer === null 
                          ? 'border-orange-50 bg-white hover:border-orange-600 hover:shadow-xl' 
                          : idx === quiz.questions[quiz.currentIndex].correctAnswer
                            ? 'border-green-600 bg-green-50 text-green-900 ring-8 ring-green-100'
                            : selectedAnswer === idx
                              ? 'border-red-600 bg-red-50 text-red-900 ring-8 ring-red-100'
                              : 'border-gray-100 opacity-40 grayscale'
                      }`}
                    >
                      <span className={`w-10 h-10 rounded-full flex items-center justify-center font-black mr-4 text-lg border-2 transition-colors ${
                        selectedAnswer === null 
                          ? 'bg-orange-50 border-orange-200 text-orange-600 group-hover:bg-orange-600 group-hover:text-white'
                          : idx === quiz.questions[quiz.currentIndex].correctAnswer
                            ? 'bg-green-600 border-green-600 text-white'
                            : selectedAnswer === idx
                              ? 'bg-red-600 border-red-600 text-white'
                              : 'bg-gray-200 text-gray-400'
                      }`}>
                        {String.fromCharCode(65 + idx)}
                      </span>
                      <span className="text-xl font-bold">{option}</span>
                    </button>
                  ))}
                </div>

                {showExplanation && (
                  <div className="p-8 bg-blue-50 border-4 border-blue-600 rounded-[2.5rem] animate-fade-in shadow-xl relative overflow-hidden">
                    <h4 className="font-black text-blue-900 mb-2 uppercase tracking-tighter flex items-center gap-2">
                       इतिहास का सार (In-Depth Explanation)
                    </h4>
                    <p className="text-blue-800 text-lg leading-relaxed font-medium">{quiz.questions[quiz.currentIndex].explanation}</p>
                    <button
                      onClick={nextQuestion}
                      className="mt-8 w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-5 rounded-3xl transition shadow-2xl transform active:scale-95 text-xl uppercase tracking-widest"
                    >
                      {quiz.currentIndex + 1 < quiz.totalQuestions ? t.next : t.finish}
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="text-center p-12 bg-red-50 rounded-[3rem] border-4 border-red-200">
                <p className="text-2xl font-black text-red-800">प्रश्नों को लोड करने में त्रुटि हुई।</p>
                <button onClick={() => handleNav('LANDING')} className="px-10 py-4 bg-orange-600 text-white font-black rounded-3xl shadow-xl mt-6">पुनः प्रयास करें</button>
              </div>
            )}
          </div>
        )}

        {appState === 'RESULT' && (
          <div className="text-center space-y-10 animate-fade-in w-full py-10">
            <div className="relative inline-block">
              <svg className="w-64 h-64 drop-shadow-2xl relative">
                <circle cx="128" cy="128" r="110" fill="none" stroke="#fed7aa" strokeWidth="18" />
                <circle 
                  cx="128" cy="128" r="110" fill="none" stroke="#ea580c" strokeWidth="18" 
                  strokeDasharray={`${(quiz.score / quiz.totalQuestions) * 691.15} 691.15`}
                  strokeLinecap="round"
                  transform="rotate(-90 128 128)"
                  className="transition-all duration-1000 ease-out"
                />
              </svg>
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="text-6xl font-black text-orange-600">{Math.round((quiz.score / quiz.totalQuestions) * 100)}%</span>
                <span className="text-xs font-black text-gray-500 uppercase tracking-[0.3em] mt-1">{t.score}</span>
              </div>
            </div>

            <div className="space-y-4">
              <h3 className="text-5xl font-black text-gray-900 tracking-tighter">
                {quiz.score === quiz.totalQuestions ? "विजेता! (Legendary)" : quiz.score > quiz.totalQuestions / 2 ? "विजयी भव!" : "प्रयास जारी रखें!"}
              </h3>
              <p className="text-2xl text-orange-800 font-bold bg-orange-100 px-6 py-3 rounded-full inline-block">
                आपने {t[quiz.difficulty]} स्तर पर {quiz.totalQuestions} में से {quiz.score} सही उत्तर दिए।
              </p>
            </div>

            <div className="flex flex-col sm:flex-row gap-5 w-full max-w-lg mx-auto">
              <button 
                onClick={() => handleNav('LANDING')}
                className="flex-1 py-5 bg-white border-4 border-orange-600 text-orange-600 font-black rounded-3xl shadow-xl hover:bg-orange-50 transition transform hover:scale-105"
              >
                मुख्य पृष्ठ (HOME)
              </button>
              <button 
                 onClick={() => startQuiz(quiz.difficulty)}
                className="flex-1 py-5 bg-orange-600 text-white font-black rounded-3xl shadow-xl hover:bg-orange-700 transition transform hover:scale-105"
              >
                पुनः प्रयास (RETRY)
              </button>
            </div>
          </div>
        )}

        {appState === 'SETTINGS' && (
          <div className="w-full bg-white p-10 rounded-[3rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.3)] space-y-10 border-4 border-orange-50">
            <div className="flex items-center justify-between border-b-2 border-orange-100 pb-6">
              <h2 className="text-4xl font-black text-gray-900 tracking-tighter">{t.settings}</h2>
              <button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            <section className="space-y-6">
              <h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider">
                <span className="bg-orange-100 p-2 rounded-xl">🔊</span>
                {t.soundEffects}
              </h3>
              <div className="flex gap-4">
                <button 
                  onClick={() => { setSoundEnabled(true); playSound('nav'); }}
                  className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${soundEnabled ? 'bg-orange-600 text-white shadow-orange-200' : 'bg-gray-100 text-gray-400 grayscale'}`}
                >
                  {t.on}
                </button>
                <button 
                  onClick={() => setSoundEnabled(false)}
                  className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${!soundEnabled ? 'bg-orange-600 text-white shadow-orange-200' : 'bg-gray-100 text-gray-400 grayscale'}`}
                >
                  {t.off}
                </button>
              </div>
            </section>

            <section className="space-y-6">
              <h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider">
                 <span className="bg-orange-100 p-2 rounded-xl">🌐</span>
                {t.selectLang}
              </h3>
              <div className="grid grid-cols-2 gap-4">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => {
                      setLanguage(lang.code);
                      playSound('nav');
                    }}
                    className={`p-4 rounded-2xl border-4 transition-all text-lg font-black ${
                      language === lang.code 
                        ? 'border-orange-600 bg-orange-50 text-orange-600 shadow-inner' 
                        : 'border-gray-50 hover:border-orange-200 bg-gray-50/50 text-gray-400'
                    }`}
                  >
                    {lang.name}
                  </button>
                ))}
              </div>
            </section>
          </div>
        )}
      </main>

      <footer className="w-full p-8 text-center">
        <div className="max-w-xs mx-auto h-px bg-orange-100 mb-6"></div>
        <p className="text-gray-400 text-sm font-bold uppercase tracking-[0.4em]">
           &copy; {new Date().getFullYear()} {APP_NAME}
        </p>
        <p className="text-orange-900/30 text-[10px] mt-2 font-black tracking-widest">BHARAT VARSHA HISTORY PROJECT</p>
      </footer>
    </div>
  );
};

export default App;

export enum Language {
  HINDI = 'HINDI',
  ENGLISH = 'ENGLISH',
  SANSKRIT = 'SANSKRIT',
  TAMIL = 'TAMIL',
  TELUGU = 'TELUGU',
  MARATHI = 'MARATHI',
  BENGALI = 'BENGALI',
  GUJARATI = 'GUJARATI'
}

export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD'
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
  era: 'Ancient' | 'Medieval' | 'Modern';
}

export interface HistoryEntry {
  id: string;
  difficulty: Difficulty;
  score: number;
  total: number;
  date: string;
}

export type AppState = 'LANDING' | 'DIFFICULTY_SELECT' | 'QUIZ' | 'SETTINGS' | 'RESULT' | 'BOOKMARKS' | 'HISTORY';

export interface QuizState {
  questions: Question[];
  currentIndex: number;
  score: number;
  isComplete: boolean;
  difficulty: Difficulty;
  timeRemaining: number;
  totalQuestions: number;
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Language, Question, QuizState, Difficulty, HistoryEntry } from './types';
import { fetchQuestions } from './services/geminiService';
import { AUTHOR_NAME, APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES } from './constants';

const BOOKMARKS_KEY = 'history_bookmarks';
const HISTORY_KEY = 'quiz_history_data';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState>({
    questions: [],
    currentIndex: 0,
    score: 0,
    isComplete: false,
    difficulty: Difficulty.MEDIUM,
    timeRemaining: 0,
    totalQuestions: 0
  });
  const [bookmarks, setBookmarks] = useState<Question[]>([]);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);

  const t = TRANSLATIONS[language];

  // Load persistence on init
  useEffect(() => {
    const savedBookmarks = localStorage.getItem(BOOKMARKS_KEY);
    if (savedBookmarks) {
      try {
        setBookmarks(JSON.parse(savedBookmarks));
      } catch (e) {
        console.error("Failed to parse bookmarks", e);
      }
    }

    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) {
      try {
        setHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error("Failed to parse history", e);
      }
    }
  }, []);

  // Save persistence on change
  useEffect(() => {
    localStorage.setItem(BOOKMARKS_KEY, JSON.stringify(bookmarks));
  }, [bookmarks]);

  useEffect(() => {
    localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
  }, [history]);

  // Timer Effect
  useEffect(() => {
    if (appState === 'QUIZ' && quiz.timeRemaining > 0 && !loading) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [appState, loading]);

  const handleTimeUp = () => {
    playSound('incorrect');
    saveToHistory(quiz.score, quiz.currentIndex + 1); // Save partial progress if time runs out
    setAppState('RESULT');
  };

  const getAudioContext = () => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioCtxRef.current;
  };

  const playSound = (type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    const ctx = getAudioContext();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.connect(gain);
    gain.connect(ctx.destination);

    const now = ctx.currentTime;

    if (type === 'correct') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(523.25, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0.1, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'incorrect') {
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(220, now);
      osc.frequency.linearRampToValueAtTime(110, now + 0.2);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'nav') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(800, now);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
      osc.start(now);
      osc.stop(now + 0.1);
    }
  };

  const formatTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${h > 0 ? h + ':' : ''}${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const backgroundSync = async (difficulty: Difficulty, target: number, currentLang: Language) => {
    if (syncRef.current) return;
    syncRef.current = true;
    setIsSyncing(true);

    let currentCount = 10;
    const BATCH_SIZE = 15;

    while (currentCount < target && syncRef.current) {
      const remaining = target - currentCount;
      const fetchCount = Math.min(BATCH_SIZE, remaining);

      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, fetchCount);
        if (moreQuestions.length === 0) break;

        setQuiz(prev => ({
          ...prev,
          questions: [...prev.questions, ...moreQuestions]
        }));
        currentCount += moreQuestions.length;
      } catch (err) {
        console.error("Sync error:", err);
        break;
      }
      await new Promise(r => setTimeout(r, 2000));
    }

    setIsSyncing(false);
    syncRef.current = false;
  };

  const startQuiz = async (difficulty: Difficulty) => {
    playSound('nav');
    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true);
    setAppState('QUIZ');
    syncRef.current = true;

    const initialQuestions = await fetchQuestions(language, difficulty, 10);

    setQuiz({
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      isComplete: false,
      difficulty,
      timeRemaining: config.time,
      totalQuestions: config.count
    });
    setLoading(false);

    backgroundSync(difficulty, config.count, language);
  };

  const saveToHistory = (score: number, totalPlayed: number) => {
    const newEntry: HistoryEntry = {
      id: Date.now().toString(),
      difficulty: quiz.difficulty,
      score,
      total: totalPlayed,
      date: new Date().toLocaleDateString(undefined, {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      })
    };
    setHistory(prev => [newEntry, ...prev].slice(0, 50)); // Keep last 50 entries
  };

  const handleAnswer = (index: number) => {
    if (selectedAnswer !== null) return;
    setSelectedAnswer(index);
    setShowExplanation(true);
    if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
      playSound('correct');
      setQuiz(prev => ({ ...prev, score: prev.score + 1 }));
    } else {
      playSound('incorrect');
    }
  };

  const nextQuestion = () => {
    playSound('nav');
    setSelectedAnswer(null);
    setShowExplanation(false);

    if (quiz.currentIndex + 1 < quiz.totalQuestions) {
      if (quiz.currentIndex + 1 >= quiz.questions.length) {
        setLoading(true);
        const checkBuffer = setInterval(() => {
          setQuiz(prev => {
            if (prev.currentIndex + 1 < prev.questions.length) {
              clearInterval(checkBuffer);
              setLoading(false);
              return { ...prev, currentIndex: prev.currentIndex + 1 };
            }
            return prev;
          });
        }, 500);
      } else {
        setQuiz(prev => ({ ...prev, currentIndex: prev.currentIndex + 1 }));
      }
    } else {
      saveToHistory(quiz.score, quiz.totalQuestions);
      setAppState('RESULT');
    }
  };

  const togglePrimaryLanguage = () => {
    playSound('nav');
    setLanguage(prev => prev === Language.HINDI ? Language.ENGLISH : Language.HINDI);
  };

  const handleNav = (state: AppState) => {
    playSound('nav');
    setAppState(state);
    if (state !== 'QUIZ') {
      syncRef.current = false;
    }
  };

  const toggleBookmark = (q: Question) => {
    playSound('nav');
    setBookmarks(prev => {
      const exists = prev.find(b => b.id === q.id);
      if (exists) {
        return prev.filter(b => b.id !== q.id);
      } else {
        return [...prev, q];
      }
    });
  };

  const clearHistory = () => {
    playSound('nav');
    if (window.confirm(t.clearHistory + '?')) {
      setHistory([]);
    }
  };

  const isBookmarked = (id: string) => bookmarks.some(b => b.id === id);

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800">
      {/* Header */}
      <header className="w-full p-4 flex justify-between items-center bg-orange-600 text-white shadow-md z-30 sticky top-0">
        <span className="font-bold text-lg cursor-pointer flex items-center gap-2" onClick={() => handleNav('LANDING')}>
          <span className="bg-white text-orange-600 w-8 h-8 rounded-full flex items-center justify-center font-black">इ</span>
          <span className="hidden xs:inline">{AUTHOR_NAME}</span>
        </span>

        {appState === 'QUIZ' && (
          <div className="flex items-center gap-2 sm:gap-3 bg-white/20 px-2 sm:px-3 py-1.5 rounded-full font-mono font-bold text-xs sm:text-sm">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <span className={quiz.timeRemaining < 60 ? 'text-yellow-300 animate-pulse' : ''}>
              {formatTime(quiz.timeRemaining)}
            </span>
          </div>
        )}

        <div className="flex gap-1.5 sm:gap-2">
          <button 
            onClick={() => handleNav('HISTORY')}
            className="bg-white/20 hover:bg-white/30 p-1.5 rounded-full transition"
            title={t.history}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          </button>
          <button 
            onClick={() => handleNav('BOOKMARKS')}
            className="bg-white/20 hover:bg-white/30 p-1.5 rounded-full transition relative"
            title={t.bookmarks}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24">
              <path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/>
            </svg>
            {bookmarks.length > 0 && (
               <span className="absolute -top-1 -right-1 bg-white text-orange-600 text-[10px] w-4 h-4 rounded-full flex items-center justify-center font-black shadow-sm">
                 {bookmarks.length}
               </span>
            )}
          </button>
          <button 
            onClick={() => handleNav('SETTINGS')}
            className="p-1.5 hover:bg-white/10 rounded-full transition"
            title={t.settings}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
          </button>
        </div>
      </header>

      <main className="flex-1 w-full max-w-2xl px-4 py-8 flex flex-col items-center justify-center">
        {appState === 'LANDING' && (
          <div className="text-center animate-fade-in py-10">
            <h1 className="text-6xl md:text-9xl font-black text-orange-600 mb-2 hindi-font tracking-tighter drop-shadow-xl select-none">
              {INTRO_MAIN}
            </h1>
            <p className="text-xl md:text-3xl text-orange-800 font-bold mb-12 italic opacity-80">
              "{INTRO_SUB}"
            </p>
            <div className="space-y-4 max-w-sm mx-auto">
              <button 
                onClick={() => handleNav('DIFFICULTY_SELECT')}
                className="w-full py-5 px-8 bg-orange-600 hover:bg-orange-700 text-white font-black text-2xl rounded-3xl shadow-2xl transform hover:scale-105 active:scale-95 transition-all duration-200 uppercase tracking-widest"
              >
                {t.start}
              </button>

              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => handleNav('BOOKMARKS')}
                  className="w-full py-3 px-2 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition-all flex items-center justify-center gap-2 text-sm"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-orange-600" fill="currentColor" viewBox="0 0 24 24">
                    <path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/>
                  </svg>
                  {t.bookmarks}
                </button>
                <button 
                  onClick={() => handleNav('HISTORY')}
                  className="w-full py-3 px-2 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition-all flex items-center justify-center gap-2 text-sm"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-orange-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                  {t.history}
                </button>
              </div>

              <p className="text-sm text-orange-400 font-medium">भारतीय इतिहास की एक महायात्रा</p>
            </div>
          </div>
        )}

        {appState === 'HISTORY' && (
          <div className="w-full space-y-6 animate-fade-in pb-10">
            <div className="flex items-center justify-between">
              <h2 className="text-3xl font-black text-orange-900">{t.history}</h2>
              <div className="flex items-center gap-2">
                {history.length > 0 && (
                  <button 
                    onClick={clearHistory}
                    className="p-2 text-red-500 hover:bg-red-50 rounded-full transition-colors"
                    title={t.clearHistory}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                )}
                <button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
            </div>

            {history.length === 0 ? (
              <div className="text-center p-20 bg-white border-4 border-dashed border-orange-100 rounded-[3rem]">
                <p className="text-xl text-gray-400 font-medium">{t.noHistory}</p>
              </div>
            ) : (
              <div className="space-y-4">
                {history.map((entry) => (
                  <div key={entry.id} className="bg-white p-5 rounded-3xl shadow-lg border-2 border-orange-50 flex items-center justify-between">
                    <div className="space-y-1">
                      <div className="flex items-center gap-2">
                        <span className={`text-[10px] px-2 py-0.5 rounded-full font-black uppercase tracking-widest ${
                          entry.difficulty === Difficulty.HARD ? 'bg-red-100 text-red-600' :
                          entry.difficulty === Difficulty.MEDIUM ? 'bg-orange-100 text-orange-600' :
                          'bg-green-100 text-green-600'
                        }`}>
                          {entry.difficulty}
                        </span>
                        <span className="text-xs text-gray-400 font-medium">{entry.date}</span>
                      </div>
                      <h3 className="text-lg font-bold text-gray-900">
                        {Math.round((entry.score / entry.total) * 100)}% ({entry.score}/{entry.total})
                      </h3>
                    </div>
                    <div className="w-12 h-12 rounded-full border-4 border-orange-100 flex items-center justify-center">
                       <span className="text-sm font-black text-orange-600">{Math.round((entry.score / entry.total) * 10)}</span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {appState === 'BOOKMARKS' && (
          <div className="w-full space-y-6 animate-fade-in pb-10">
            <div className="flex items-center justify-between">
              <h2 className="text-3xl font-black text-orange-900">{t.savedQuestions}</h2>
              <button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            {bookmarks.length === 0 ? (
              <div className="text-center p-20 bg-white border-4 border-dashed border-orange-100 rounded-[3rem]">
                <p className="text-xl text-gray-400 font-medium">{t.noBookmarks}</p>
              </div>
            ) : (
              <div className="space-y-4">
                {bookmarks.map((q) => (
                  <div key={q.id} className="bg-white p-6 rounded-3xl shadow-lg border-2 border-orange-50 relative group">
                    <button 
                      onClick={() => toggleBookmark(q)}
                      className="absolute top-4 right-4 text-orange-600 hover:scale-110 transition-transform"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24">
                        <path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/>
                      </svg>
                    </button>
                    <div className="mb-2">
                       <span className="text-[10px] bg-orange-100 text-orange-600 px-2 py-0.5 rounded-full font-black uppercase tracking-widest">{q.era}</span>
                    </div>
                    <h3 className="text-lg font-bold text-gray-900 pr-8">{q.text}</h3>
                    <div className="mt-4 p-4 bg-orange-50 rounded-xl">
                      <p className="text-sm font-bold text-orange-900 uppercase tracking-tighter mb-1">सही उत्तर (Correct): {q.options[q.correctAnswer]}</p>
                      <p className="text-xs text-orange-800 leading-relaxed italic">{q.explanation}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {appState === 'DIFFICULTY_SELECT' && (
          <div className="w-full max-w-md space-y-6 animate-fade-in">
            <div className="text-center mb-10">
              <h2 className="text-4xl font-black text-orange-900 drop-shadow-sm">{t.selectDifficulty}</h2>
              <p className="text-orange-700/60 mt-2">अपनी क्षमतानुसार चुनौती चुनें</p>
            </div>
            <div className="grid grid-cols-1 gap-5">
              {DIFFICULTIES.map((diff) => (
                <button
                  key={diff.code}
                  onClick={() => startQuiz(diff.code)}
                  className="group relative overflow-hidden p-6 bg-white border-4 border-orange-50 hover:border-orange-500 rounded-3xl shadow-lg hover:shadow-2xl transition-all duration-300 text-left"
                >
                  <div className="flex justify-between items-center relative z-10">
                    <div>
                      <h3 className="text-2xl font-black text-gray-900 group-hover:text-orange-600 transition-colors">
                        {t[diff.code]}
                      </h3>
                      <div className="flex gap-4 mt-2 text-sm font-bold text-gray-400 uppercase tracking-tighter">
                        <span className="flex items-center gap-1">
                          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path d="M9 2a1 1 0 000 2h2a1 1 0 100-2H9z"/><path fillRule="evenodd" d="M4 5a2 2 0 012-2 3 3 0 003 3h2a3 3 0 003-3 2 2 0 012 2v11a2 2 0 01-2 2H6a2 2 0 01-2-2V5zm3 4a1 1 0 000 2h.01a1 1 0 100-2H7zm3 0a1 1 0 000 2h3a1 1 0 100-2h-3zm-3 4a1 1 0 100 2h.01a1 1 0 100-2H7zm3 0a1 1 0 100 2h3a1 1 0 100-2h-3z" clipRule="evenodd"/></svg>
                          {diff.count} {t.questions}
                        </span>
                        <span className="flex items-center gap-1">
                          <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z" clipRule="evenodd"/></svg>
                          {diff.time / 60} {t.minutes}
                        </span>
                      </div>
                    </div>
                    <div className="bg-orange-50 p-3 rounded-2xl group-hover:bg-orange-100 transition-colors">
                       <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-orange-600 group-hover:translate-x-1 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" />
                      </svg>
                    </div>
                  </div>
                </button>
              ))}
            </div>
            <button 
              onClick={() => handleNav('LANDING')}
              className="w-full py-4 text-gray-400 font-bold hover:text-orange-600 transition tracking-widest text-sm"
            >
              वपस जाएं (BACK TO HOME)
            </button>
          </div>
        )}

        {appState === 'QUIZ' && (
          <div className="w-full pb-20">
            {loading ? (
              <div className="flex flex-col items-center justify-center min-h-[400px] space-y-6">
                <div className="relative">
                  <div className="w-20 h-20 border-8 border-orange-100 rounded-full"></div>
                  <div className="w-20 h-20 border-8 border-orange-600 border-t-transparent rounded-full animate-spin absolute top-0"></div>
                </div>
                <div className="text-center">
                  <p className="text-2xl font-black text-orange-900 animate-pulse">
                    {quiz.questions.length < quiz.totalQuestions && quiz.currentIndex >= quiz.questions.length - 1 
                      ? "अगले प्रश्नों को संजोया जा रहा है..." 
                      : "इतिहास के पन्ने खुल रहे हैं..."}
                  </p>
                  <p className="text-orange-700/60 font-medium italic">
                    {isSyncing ? "पृष्ठभूमि में ज्ञान संचय जारी है..." : "कृपया प्रतीक्षा करें"}
                  </p>
                </div>
              </div>
            ) : quiz.questions.length > 0 && quiz.questions[quiz.currentIndex] ? (
              <div className="space-y-8">
                {/* Progress Bar */}
                <div className="w-full bg-orange-100 h-3 rounded-full overflow-hidden shadow-inner border border-orange-200">
                  <div 
                    className="bg-orange-600 h-full transition-all duration-500 ease-out"
                    style={{ width: `${((quiz.currentIndex + 1) / quiz.totalQuestions) * 100}%` }}
                  ></div>
                </div>

                <div className="flex justify-between items-center text-sm font-black text-orange-900">
                  <div className="flex flex-col">
                    <span className="uppercase tracking-widest text-xs opacity-50">{t[quiz.difficulty]}</span>
                    <span className="text-lg">प्रसंग {quiz.currentIndex + 1} / {quiz.totalQuestions}</span>
                  </div>
                  <div className="flex items-center gap-3">
                    <button 
                      onClick={() => toggleBookmark(quiz.questions[quiz.currentIndex])}
                      className={`p-2 rounded-full transition-colors border-2 ${isBookmarked(quiz.questions[quiz.currentIndex].id) ? 'bg-orange-600 border-orange-600 text-white' : 'bg-white border-orange-200 text-orange-600 hover:bg-orange-50'}`}
                      title={isBookmarked(quiz.questions[quiz.currentIndex].id) ? "Remove Bookmark" : "Bookmark Question"}
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24">
                        <path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/>
                      </svg>
                    </button>
                    <div className="flex flex-col items-end gap-1">
                      <div className="bg-orange-600 text-white px-4 py-1.5 rounded-2xl shadow-md uppercase tracking-tighter">
                        {quiz.questions[quiz.currentIndex].era}
                      </div>
                      {isSyncing && (
                         <span className="text-[9px] text-orange-400 font-black animate-pulse uppercase tracking-widest">
                           SYNCING {quiz.questions.length}/{quiz.totalQuestions}
                         </span>
                      )}
                    </div>
                  </div>
                </div>

                <h2 className="text-3xl md:text-4xl font-black text-gray-900 leading-tight hindi-font">
                  {quiz.questions[quiz.currentIndex].text}
                </h2>

                <div className="grid grid-cols-1 gap-4">
                  {quiz.questions[quiz.currentIndex].options.map((option, idx) => (
                    <button
                      key={idx}
                      onClick={() => handleAnswer(idx)}
                      disabled={selectedAnswer !== null}
                      className={`group p-5 text-left rounded-3xl border-4 transition-all duration-200 flex items-center ${
                        selectedAnswer === null 
                          ? 'border-orange-50 bg-white hover:border-orange-600 hover:shadow-xl' 
                          : idx === quiz.questions[quiz.currentIndex].correctAnswer
                            ? 'border-green-600 bg-green-50 text-green-900 ring-8 ring-green-100'
                            : selectedAnswer === idx
                              ? 'border-red-600 bg-red-50 text-red-900 ring-8 ring-red-100'
                              : 'border-gray-100 opacity-40 grayscale'
                      }`}
                    >
                      <span className={`w-10 h-10 rounded-full flex items-center justify-center font-black mr-4 text-lg border-2 transition-colors ${
                        selectedAnswer === null 
                          ? 'bg-orange-50 border-orange-200 text-orange-600 group-hover:bg-orange-600 group-hover:text-white'
                          : idx === quiz.questions[quiz.currentIndex].correctAnswer
                            ? 'bg-green-600 border-green-600 text-white'
                            : selectedAnswer === idx
                              ? 'bg-red-600 border-red-600 text-white'
                              : 'bg-gray-200 text-gray-400'
                      }`}>
                        {String.fromCharCode(65 + idx)}
                      </span>
                      <span className="text-xl font-bold">{option}</span>
                    </button>
                  ))}
                </div>

                {showExplanation && (
                  <div className="p-8 bg-blue-50 border-4 border-blue-600 rounded-[2.5rem] animate-fade-in shadow-xl relative overflow-hidden">
                    <h4 className="font-black text-blue-900 mb-2 uppercase tracking-tighter flex items-center gap-2">
                       इतिहास का सार (In-Depth Explanation)
                    </h4>
                    <p className="text-blue-800 text-lg leading-relaxed font-medium">{quiz.questions[quiz.currentIndex].explanation}</p>
                    <button
                      onClick={nextQuestion}
                      className="mt-8 w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-5 rounded-3xl transition shadow-2xl transform active:scale-95 text-xl uppercase tracking-widest"
                    >
                      {quiz.currentIndex + 1 < quiz.totalQuestions ? t.next : t.finish}
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="text-center p-12 bg-red-50 rounded-[3rem] border-4 border-red-200">
                <p className="text-2xl font-black text-red-800">प्रश्नों को लोड करने में त्रुटि हुई।</p>
                <button onClick={() => handleNav('LANDING')} className="px-10 py-4 bg-orange-600 text-white font-black rounded-3xl shadow-xl mt-6">पुनः प्रयास करें</button>
              </div>
            )}
          </div>
        )}

        {appState === 'RESULT' && (
          <div className="text-center space-y-10 animate-fade-in w-full py-10">
            <div className="relative inline-block">
              <svg className="w-64 h-64 drop-shadow-2xl relative">
                <circle cx="128" cy="128" r="110" fill="none" stroke="#fed7aa" strokeWidth="18" />
                <circle 
                  cx="128" cy="128" r="110" fill="none" stroke="#ea580c" strokeWidth="18" 
                  strokeDasharray={`${(quiz.score / quiz.totalQuestions) * 691.15} 691.15`}
                  strokeLinecap="round"
                  transform="rotate(-90 128 128)"
                  className="transition-all duration-1000 ease-out"
                />
              </svg>
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="text-6xl font-black text-orange-600">{Math.round((quiz.score / quiz.totalQuestions) * 100)}%</span>
                <span className="text-xs font-black text-gray-500 uppercase tracking-[0.3em] mt-1">{t.score}</span>
              </div>
            </div>

            <div className="space-y-4">
              <h3 className="text-5xl font-black text-gray-900 tracking-tighter">
                {quiz.score === quiz.totalQuestions ? "विजेता! (Legendary)" : quiz.score > quiz.totalQuestions / 2 ? "विजयी भव!" : "प्रयास जारी रखें!"}
              </h3>
              <p className="text-2xl text-orange-800 font-bold bg-orange-100 px-6 py-3 rounded-full inline-block">
                आपने {t[quiz.difficulty]} स्तर पर {quiz.totalQuestions} में से {quiz.score} सही उत्तर दिए।
              </p>
            </div>

            <div className="flex flex-col sm:flex-row gap-5 w-full max-w-lg mx-auto">
              <button 
                onClick={() => handleNav('LANDING')}
                className="flex-1 py-5 bg-white border-4 border-orange-600 text-orange-600 font-black rounded-3xl shadow-xl hover:bg-orange-50 transition transform hover:scale-105"
              >
                मुख्य पृष्ठ (HOME)
              </button>
              <button 
                 onClick={() => startQuiz(quiz.difficulty)}
                className="flex-1 py-5 bg-orange-600 text-white font-black rounded-3xl shadow-xl hover:bg-orange-700 transition transform hover:scale-105"
              >
                पुनः प्रयास (RETRY)
              </button>
            </div>
          </div>
        )}

        {appState === 'SETTINGS' && (
          <div className="w-full bg-white p-10 rounded-[3rem] shadow-[0_35px_60px_-15px_rgba(0,0,0,0.3)] space-y-10 border-4 border-orange-50">
            <div className="flex items-center justify-between border-b-2 border-orange-100 pb-6">
              <h2 className="text-4xl font-black text-gray-900 tracking-tighter">{t.settings}</h2>
              <button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>

            <section className="space-y-6">
              <h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider">
                <span className="bg-orange-100 p-2 rounded-xl">🔊</span>
                {t.soundEffects}
              </h3>
              <div className="flex gap-4">
                <button 
                  onClick={() => { setSoundEnabled(true); playSound('nav'); }}
                  className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${soundEnabled ? 'bg-orange-600 text-white shadow-orange-200' : 'bg-gray-100 text-gray-400 grayscale'}`}
                >
                  {t.on}
                </button>
                <button 
                  onClick={() => setSoundEnabled(false)}
                  className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${!soundEnabled ? 'bg-orange-600 text-white shadow-orange-200' : 'bg-gray-100 text-gray-400 grayscale'}`}
                >
                  {t.off}
                </button>
              </div>
            </section>

            <section className="space-y-6">
              <h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider">
                 <span className="bg-orange-100 p-2 rounded-xl">🌐</span>
                {t.selectLang}
              </h3>
              <div className="grid grid-cols-2 gap-4">
                {LANGUAGES.map((lang) => (
                  <button
                    key={lang.code}
                    onClick={() => {
                      setLanguage(lang.code);
                      playSound('nav');
                    }}
                    className={`p-4 rounded-2xl border-4 transition-all text-lg font-black ${
                      language === lang.code 
                        ? 'border-orange-600 bg-orange-50 text-orange-600 shadow-inner' 
                        : 'border-gray-50 hover:border-orange-200 bg-gray-50/50 text-gray-400'
                    }`}
                  >
                    {lang.name}
                  </button>
                ))}
              </div>
            </section>
          </div>
        )}
      </main>

      <footer className="w-full p-8 text-center">
        <div className="max-w-xs mx-auto h-px bg-orange-100 mb-6"></div>
        <p className="text-gray-400 text-sm font-bold uppercase tracking-[0.4em]">
           &copy; {new Date().getFullYear()} {APP_NAME}
        </p>
        <p className="text-orange-900/30 text-[10px] mt-2 font-black tracking-widest">BHARAT VARSHA HISTORY PROJECT</p>
      </footer>
    </div>
  );
};

export default App;

export enum Language {
  HINDI = 'HINDI',
  ENGLISH = 'ENGLISH',
  SANSKRIT = 'SANSKRIT',
  TAMIL = 'TAMIL',
  TELUGU = 'TELUGU',
  MARATHI = 'MARATHI',
  BENGALI = 'BENGALI',
  GUJARATI = 'GUJARATI'
}

export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD'
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
  era: 'Ancient' | 'Medieval' | 'Modern';
}

export interface HistoryEntry {
  id: string;
  difficulty: Difficulty;
  score: number;
  total: number;
  skipped: number;
  date: string;
}

export type AppState = 'LANDING' | 'DIFFICULTY_SELECT' | 'QUIZ' | 'SETTINGS' | 'RESULT' | 'BOOKMARKS' | 'HISTORY';

export interface QuizState {
  questions: Question[];
  currentIndex: number;
  score: number;
  skippedCount: number;
  skipsRemaining: number;
  isComplete: boolean;
  difficulty: Difficulty;
  timeRemaining: number;
  totalQuestions: number;
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Language, Question, QuizState, Difficulty, HistoryEntry } from './types';
import { fetchQuestions } from './services/geminiService';
import { AUTHOR_NAME, APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES } from './constants';

const BOOKMARKS_KEY = 'history_bookmarks';
const HISTORY_KEY = 'quiz_history_data';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState>({
    questions: [],
    currentIndex: 0,
    score: 0,
    skippedCount: 0,
    skipsRemaining: 0,
    isComplete: false,
    difficulty: Difficulty.MEDIUM,
    timeRemaining: 0,
    totalQuestions: 0
  });
  const [bookmarks, setBookmarks] = useState<Question[]>([]);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);

  const t = TRANSLATIONS[language];

  // Load persistence on init
  useEffect(() => {
    const savedBookmarks = localStorage.getItem(BOOKMARKS_KEY);
    if (savedBookmarks) {
      try {
        setBookmarks(JSON.parse(savedBookmarks));
      } catch (e) {
        console.error("Failed to parse bookmarks", e);
      }
    }

    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) {
      try {
        setHistory(JSON.parse(savedHistory));
      } catch (e) {
        console.error("Failed to parse history", e);
      }
    }
  }, []);

  // Save persistence on change
  useEffect(() => {
    localStorage.setItem(BOOKMARKS_KEY, JSON.stringify(bookmarks));
  }, [bookmarks]);

  useEffect(() => {
    localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
  }, [history]);

  // Timer Effect
  useEffect(() => {
    if (appState === 'QUIZ' && quiz.timeRemaining > 0 && !loading) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [appState, loading]);

  const handleTimeUp = () => {
    playSound('incorrect');
    saveToHistory(quiz.score, quiz.currentIndex + 1, quiz.skippedCount); 
    setAppState('RESULT');
  };

  const getAudioContext = () => {
    if (!audioCtxRef.current) {
      audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    return audioCtxRef.current;
  };

  const playSound = (type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    const ctx = getAudioContext();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();

    osc.connect(gain);
    gain.connect(ctx.destination);

    const now = ctx.currentTime;

    if (type === 'correct') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(523.25, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0.1, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'incorrect') {
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(220, now);
      osc.frequency.linearRampToValueAtTime(110, now + 0.2);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now);
      osc.stop(now + 0.3);
    } else if (type === 'nav') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(800, now);
      gain.gain.setValueAtTime(0.05, now);
      gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
      osc.start(now);
      osc.stop(now + 0.1);
    }
  };

  const formatTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${h > 0 ? h + ':' : ''}${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const backgroundSync = async (difficulty: Difficulty, target: number, currentLang: Language) => {
    if (syncRef.current) return;
    syncRef.current = true;
    setIsSyncing(true);

    let currentCount = 10;
    const BATCH_SIZE = 15;

    while (currentCount < target && syncRef.current) {
      const remaining = target - currentCount;
      const fetchCount = Math.min(BATCH_SIZE, remaining);

      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, fetchCount);
        if (moreQuestions.length === 0) break;

        setQuiz(prev => ({
          ...prev,
          questions: [...prev.questions, ...moreQuestions]
        }));
        currentCount += moreQuestions.length;
      } catch (err) {
        console.error("Sync error:", err);
        break;
      }
      await new Promise(r => setTimeout(r, 2000));
    }

    setIsSyncing(false);
    syncRef.current = false;
  };

  const startQuiz = async (difficulty: Difficulty) => {
    playSound('nav');
    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true);
    setAppState('QUIZ');
    syncRef.current = true;

    const initialQuestions = await fetchQuestions(language, difficulty, 10);

    setQuiz({
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: config.maxSkips,
      isComplete: false,
      difficulty,
      timeRemaining: config.time,
      totalQuestions: config.count
    });
    setLoading(false);

    backgroundSync(difficulty, config.count, language);
  };

  const saveToHistory = (score: number, totalPlayed: number, skipped: number) => {
    const newEntry: HistoryEntry = {
      id: Date.now().toString(),
      difficulty: quiz.difficulty,
      score,
      total: totalPlayed,
      skipped,
      date: new Date().toLocaleDateString(undefined, {
        day: 'numeric',
        month: 'short',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      })
    };
    setHistory(prev => [newEntry, ...prev].slice(0, 50)); 
  };

  const handleAnswer = (index: number) => {
    if (selectedAnswer !== null) return;
    setSelectedAnswer(index);
    setShowExplanation(true);
    if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
      playSound('correct');
      setQuiz(prev => ({ ...prev, score: prev.score + 1 }));
    } else {
      playSound('incorrect');
    }
  };

  const handleSkip = () => {
    if (quiz.skipsRemaining <= 0 || selectedAnswer !== null) return;
    playSound('nav');

    const isLast = quiz.currentIndex + 1 >= quiz.totalQuestions;

    setQuiz(prev => ({
      ...prev,
      skipsRemaining: prev.skipsRemaining - 1,
      skippedCount: prev.skippedCount + 1
    }));

    if (isLast) {
      saveToHistory(quiz.score, quiz.totalQuestions, quiz.skippedCount + 1);
      setAppState('RESULT');
    } else {
      moveNext();
    }
  };

  const moveNext = () => {
    if (quiz.currentIndex + 1 >= quiz.questions.length) {
      setLoading(true);
      const checkBuffer = setInterval(() => {
        setQuiz(prev => {
          if (prev.currentIndex + 1 < prev.questions.length) {
            clearInterval(checkBuffer);
            setLoading(false);
            return { ...prev, currentIndex: prev.currentIndex + 1 };
          }
          return prev;
        });
      }, 500);
    } else {
      setQuiz(prev => ({ ...prev, currentIndex: prev.currentIndex + 1 }));
    }
  };

  const nextQuestion = () => {
    playSound('nav');
    setSelectedAnswer(null);
    setShowExplanation(false);

    if (quiz.currentIndex + 1 < quiz.totalQuestions) {
      moveNext();
    } else {
      saveToHistory(quiz.score, quiz.totalQuestions, quiz.skippedCount);
      setAppState('RESULT');
    }
  };

  const togglePrimaryLanguage = () => {
    playSound('nav');
    setLanguage(prev => prev === Language.HINDI ? Language.ENGLISH : Language.HINDI);
  };

  const handleNav = (state: AppState) => {
    playSound('nav');
    setAppState(state);
    if (state !== 'QUIZ') {
      syncRef.current = false;
    }
  };

  const toggleBookmark = (q: Question) => {
    playSound('nav');
    setBookmarks(prev => {
      const exists = prev.find(b => b.id === q.id);
      if (exists) {
        return prev.filter(b => b.id !== q.id);
      } else {
        return [...prev, q];
      }
    });
  };

  const clearHistory = () => {
    playSound('nav');
    if (window.confirm(t.clearHistory + '?')) {
      setHistory([]);
    }
  };

  const isBookmarked = (id: string) => bookmarks.some(b => b.id === id);

  return (
    <div className="min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800">
      {/* Header */}
      <header className="w-full p-4 flex justify-between items-center bg-orange-600 text-white shadow-md z-30 sticky top-0">
        <span className="font-bold text-lg cursor-pointer flex items-center gap-2" onClick={() => handleNav('LANDING')}>
          <span className="bg-white text-orange-600 w-8 h-8 rounded-full flex items-center justify-center font-black">इ</span>
          <span className="hidden xs:inline">{AUTHOR_NAME}</span>
        </span>

        {appState === 'QUIZ' && (
          <div className="flex items-center gap-2 sm:gap-3 bg-white/20 px-2 sm:px-3 py-1.5 rounded-full font-mono font-bold text-xs sm:text-sm">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <span className={quiz.timeRemaining < 60 ? 'text-yellow-300 animate-pulse' : ''}>
              {formatTime(quiz.timeRemaining)}
            </span>
          </div>
        )}

        <div className="flex gap-1.5 sm:gap-2">
          <button 
            onClick={() => handleNav('HISTORY')}
            className="bg-white/20 hover:bg-white/30 p-1.5 rounded-full transition"
            title={t.history}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
          </button>
          <button 
            onClick={() => handleNav('BOOKMARKS')}
            className="bg-white/20 hover:bg-white/30 p-1.5 rounded-full transition relative"
            title={t.bookmarks}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24">
              <path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/>
            </svg>
            {bookmarks.length > 0 && (
               <span className="absolute -top-1 -right-1 bg-white text-orange-600 text-[10px] w-4 h-4 rounded-full flex items-center justify-center font-black shadow-sm">
                 {bookmarks.length}
               </span>
            )}
          </button>
          <button 
            onClick={() => handleNav('SETTINGS')}
            className="p-1.5 hover:bg-white/10 rounded-full transition"
            title={t.settings}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
          </button>
        </div>
      </header>

      <main className="flex-1 w-full max-w-2xl px-4 py-8 flex flex-col items-center justify-center">
        {appState === 'LANDING' && (
          <div className="text-center animate-fade-in py-10">
            <h1 className="text-6xl md:text-9xl font-black text-orange-600 mb-2 hindi-font tracking-tighter drop-shadow-xl select-none">
              {INTRO_MAIN}
            </h1>
            <p className="text-xl md:text-3xl text-orange-800 font-bold mb-12 italic opacity-80">
              "{INTRO_SUB}"
            </p>
            <div className="space-y-4 max-w-sm mx-auto">
              <button 
                onClick={() => handleNav('DIFFICULTY_SELECT')}
                className="w-full py-5 px-8 bg-orange-600 hover:bg-orange-700 text-white font-black text-2xl rounded-3xl shadow-2xl transform hover:scale-105 active:scale-95 transition-all duration-200 uppercase tracking-widest"
              >
                {t.start}
              </button>

              <div className="grid grid-cols-2 gap-4">
                <button 
                  onClick={() => handleNav('BOOKMARKS')}
                  className="w-full py-3 px-2 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition-all flex items-center justify-center gap-2 text-sm"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-orange-600" fill="currentColor" viewBox="0 0 24 24">
                    <path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/>
                  </svg>
                  {t.bookmarks}
                </button>
                <button 
                  onClick={() => handleNav('HISTORY')}
                  className="w-full py-3 px-2 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition-all flex items-center justify-center gap-2 text-sm"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-orange-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                  {t.history}
                </button>
              </div>

              <p className="text-sm text-orange-400 font-medium">भारतीय इतिहास की एक महायात्रा</p>
            </div>
          </div>
        )}

        {appState === 'HISTORY' && (
          <div className="w-full space-y-6 animate-fade-in pb-10">
            <div className="flex items-center justify-between">
              <h2 className="text-3xl font-black text-orange-900">{t.history}</h2>
              <div className="flex items-center gap-2">
                {history.length > 0 && (
                  <button 
                    onClick={clearHistory}
                    className="p-2 text-red-500 hover:bg-red-50 rounded-full transition-colors"
                    title={t.clearHistory}
                  >
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                )}
                <button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors">
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
            </div>

            {history.length === 0 ? (
              <div className="text-center p-20 bg-white border-4 border-dashed border-orange-100 rounded-[3rem]">
                <p className="text-xl text-gray-400 font-medium">{t.noHistory}</p>
              </div>
            ) : (
              <div className="space-y-4">
                {history.map((entry) => (
                  <div key={entry.id} className="bg-white p-5 rounded-3xl shadow-lg border-2 border-orange-50 flex items-center justify-between">
                    <div className="space-y-1">
                      <div className="flex items-center gap-2">
                        <span className={`text-[10px] px-2 py-0.5 rounded-full font-black uppercase tracking-widest ${
                          entry.difficulty === Difficulty.HARD ? 'bg-red-100 text-red-600' :
                          entry.difficulty === Difficulty.MEDIUM ? 'bg-orange-100 text-orange-600' :
                          'bg-green-100 text-green-600'
                        }`}>
                          {entry.difficulty}
                        </span>
                        <span className="text-xs text-gray-400 font-medium">{entry.date}</span>
                      </div>
                      <h3 className="text-lg font-bold text-gray-900">
                        {Math.round((entry.score / entry.total) * 100)}% ({entry.score}/{entry.total})
                      </h3>
                      {entry.skipped > 0 && (
                        <p className="text-[10px] text-gray-400 italic">{t.skipped}: {entry.skipped}</p>
                      )}
                    </div>
                    <div className="w-12 h-12 rounded-full border-4 border-orange-100 flex items-center justify-center">
                       <span className="text-sm font-black text-orange-600">{Math.round((entry.score / entry.total) * 10)}</span>
                    </div>
                  </div>
                ))}
              </div>
