                    <div className={`bg-${diff.color}-50 p-3 rounded-2xl group-hover:bg-${diff.color}-100 transition-colors`}><svg xmlns="http://www.w3.org/2000/svg" className={`h-8 w-8 text-${diff.color}-600 group-hover:translate-x-1 transition-transform`} fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 5l7 7-7 7" /></svg></div>
                  </div>
                </button>
              ))}
            </div>
            <button onClick={() => handleNav('LANDING')} className="w-full py-4 text-gray-400 font-bold hover:text-orange-600 transition tracking-widest text-sm">वपस जाएं (BACK TO HOME)</button>
