                  <div className="flex items-center gap-3">
                    <button onClick={() => toggleBookmark(quiz.questions[quiz.currentIndex])} className={`p-2 rounded-full transition-colors border-2 ${isBookmarked(quiz.questions[quiz.currentIndex].id) ? 'bg-orange-600 border-orange-600 text-white' : 'bg-white border-orange-200 text-orange-600 hover:bg-orange-50'}`}><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg></button>
