              <button onClick={() => startQuiz(Difficulty.CHALLENGE)} className="w-full py-4 px-8 bg-red-600 hover:bg-red-700 text-white font-black text-xl rounded-3xl shadow-xl transform hover:scale-105 active:scale-95 transition-all duration-200 flex items-center justify-center gap-3"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>{t.timedChallenge}</button>
