                <button onClick={() => { if(quiz.isDailyMode) handleNav('LANDING'); else startQuiz(quiz.difficulty); }} className={`flex-1 py-5 text-white font-black rounded-3xl shadow-xl transition transform hover:scale-105 ${quiz.isChallengeMode ? 'bg-red-600' : 'bg-orange-600'}`}>{quiz.isDailyMode ? t.finish : t.restart}</button>
              </div>
            </div>
          </div>
        )}
        {appState === 'SETTINGS' && (
          <div className="w-full bg-white p-10 rounded-[3rem] shadow-xl space-y-10 border-4 border-orange-50">
            <div className="flex items-center justify-between border-b-2 border-orange-100 pb-6"><h2 className="text-4xl font-black text-gray-900 tracking-tighter">{t.settings}</h2><button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg></button></div>
            <section className="space-y-6"><h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider"><span>🔊</span>{t.soundEffects}</h3><div className="flex gap-4"><button onClick={() => { setSoundEnabled(true); playSound('nav'); }} className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${soundEnabled ? 'bg-orange-600 text-white' : 'bg-gray-100 text-gray-400'}`}>{t.on}</button><button onClick={() => setSoundEnabled(false)} className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${!soundEnabled ? 'bg-orange-600 text-white' : 'bg-gray-100 text-gray-400'}`}>{t.off}</button></div></section>
            <section className="space-y-6"><h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider"><span>🌐</span>{t.selectLang}</h3><div className="grid grid-cols-2 gap-4">{LANGUAGES.map((lang) => (<button key={lang.code} onClick={() => { setLanguage(lang.code); playSound('nav'); }} className={`p-4 rounded-2xl border-4 transition-all text-lg font-black ${language === lang.code ? 'border-orange-600 bg-orange-50 text-orange-600 shadow-inner' : 'border-gray-50 text-gray-400'}`}>{lang.name}</button>))}</div></section>
          </div>
        )}
      </main>
      <footer className="w-full p-8 text-center">
        <div className="flex items-center justify-center gap-2 text-[10px] font-black text-orange-400 uppercase tracking-widest mb-4">
           <span className="w-2 h-2 bg-green-500 rounded-full"></span>
           Online & Verified by Google Search
        </div>
        <div className="max-w-xs mx-auto h-px bg-orange-100 mb-6"></div>
        <p className="text-gray-400 text-sm font-bold uppercase tracking-[0.4em]">&copy; {new Date().getFullYear()} {APP_NAME}</p>
        <p className="text-orange-900/30 text-[10px] mt-2 font-black tracking-widest">BHARAT VARSHA HISTORY PROJECT</p>
      </footer>
    </div>
  );
};

export default App;

export enum Language {
  HINDI = 'HINDI',
  ENGLISH = 'ENGLISH',
  SANSKRIT = 'SANSKRIT',
  TAMIL = 'TAMIL',
  TELUGU = 'TELUGU',
  MARATHI = 'MARATHI',
  BENGALI = 'BENGALI',
  GUJARATI = 'GUJARATI'
}

export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD',
  CHALLENGE = 'CHALLENGE'
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
  era: 'Ancient' | 'Medieval' | 'Modern';
  sources?: { title: string; uri: string }[];
}

export interface HistoryEntry {
  id: string;
  difficulty: Difficulty | 'DAILY';
  score: number;
  total: number;
  skipped: number;
  date: string;
  isChallenge?: boolean;
}

export type AppState = 'LANDING' | 'DIFFICULTY_SELECT' | 'QUIZ' | 'SETTINGS' | 'RESULT' | 'BOOKMARKS' | 'HISTORY' | 'COUNTDOWN';

export interface QuizState {
  questions: Question[];
  currentIndex: number;
  score: number;
  skippedCount: number;
  skipsRemaining: number;
  isComplete: boolean;
  difficulty: Difficulty;
  timeRemaining: number;
  totalQuestions: number;
  isChallengeMode?: boolean;
  isDailyMode?: boolean;
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Language, Question, QuizState, Difficulty, HistoryEntry } from './types';
import { fetchQuestions } from './services/geminiService';
import { AUTHOR_NAME, APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES, DAILY_QUIZ_COUNT } from './constants';

const BOOKMARKS_KEY = 'history_bookmarks';
const HISTORY_KEY = 'quiz_history_data';
const ACTIVE_QUIZ_KEY = 'active_quiz_session';
const DAILY_STATS_KEY = 'daily_stats_v1';

const PRE_QUIZ_FACTS = [
  "सिंधु घाटी सभ्यता दुनिया की सबसे पुरानी शहरी सभ्यताओं में से एक थी।",
  "मौर्य साम्राज्य ने पहली बार लगभग पूरे भारतीय उपमहाद्वीप को एकजुट किया।",
  "प्राचीन नालंदा विश्वविद्यालय में 90 लाख से अधिक पांडुलिपियां थीं।",
  "छत्रपति शिवाजी महाराज को भारतीय नौसेना का जनक माना जाता है।",
  "सम्राट अशोक के शिलालेख शांति और अहिंसा का संदेश देते हैं।",
  "गुप्त काल को भारतीय इतिहास का 'स्वर्ण युग' कहा जाता है।",
  "रानी लक्ष्मीबाई ने 1857 के स्वतंत्रता संग्राम में अदम्य साहस दिखाया।",
  "भारतीय संविधान दुनिया का सबसे बड़ा लिखित संविधान है।"
];

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState | null>(null);
  const [bookmarks, setBookmarks] = useState<Question[]>([]);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [showCopied, setShowCopied] = useState(false);

  // Countdown Logic
  const [preQuizTimer, setPreQuizTimer] = useState(10);
  const [randomFact, setRandomFact] = useState("");

  // Daily Stats
  const [dailyStreak, setDailyStreak] = useState(0);
  const [lastDailyDate, setLastDailyDate] = useState<string | null>(null);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);

  const t = TRANSLATIONS[language] || TRANSLATIONS[Language.ENGLISH];

  // Load persistence on init
  useEffect(() => {
    const savedBookmarks = localStorage.getItem(BOOKMARKS_KEY);
    if (savedBookmarks) {
      try { setBookmarks(JSON.parse(savedBookmarks)); } catch (e) { console.error(e); }
    }

    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) {
      try { setHistory(JSON.parse(savedHistory)); } catch (e) { console.error(e); }
    }

    const savedStats = localStorage.getItem(DAILY_STATS_KEY);
    if (savedStats) {
      try {
        const stats = JSON.parse(savedStats);
        setDailyStreak(stats.streak || 0);
        setLastDailyDate(stats.lastDate || null);

        if (stats.lastDate) {
          const last = new Date(stats.lastDate);
          last.setHours(0, 0, 0, 0);
          const today = new Date();
          today.setHours(0, 0, 0, 0);

          const yesterday = new Date(today);
          yesterday.setDate(yesterday.getDate() - 1);

          if (last.getTime() < yesterday.getTime()) {
             setDailyStreak(0);
          }
        }
      } catch (e) { console.error(e); }
    }

    const savedActiveQuiz = localStorage.getItem(ACTIVE_QUIZ_KEY);
    if (savedActiveQuiz) {
      try { 
        const parsed = JSON.parse(savedActiveQuiz);
        if (parsed && !parsed.isComplete) {
          setQuiz(parsed);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  // Countdown timer effect
  useEffect(() => {
    if (appState === 'COUNTDOWN' && preQuizTimer > 0) {
      const timer = setTimeout(() => {
        setPreQuizTimer(preQuizTimer - 1);
        if (preQuizTimer % 2 === 0) playSound('nav');
      }, 1000);
      return () => clearTimeout(timer);
    } else if (appState === 'COUNTDOWN' && preQuizTimer === 0) {
      setAppState('QUIZ');
    }
  }, [appState, preQuizTimer]);

  // Save persistence on change
  useEffect(() => {
    localStorage.setItem(BOOKMARKS_KEY, JSON.stringify(bookmarks));
  }, [bookmarks]);

  useEffect(() => {
    localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    if (quiz) {
      localStorage.setItem(ACTIVE_QUIZ_KEY, JSON.stringify(quiz));
    }
  }, [quiz]);

  useEffect(() => {
    localStorage.setItem(DAILY_STATS_KEY, JSON.stringify({ streak: dailyStreak, lastDate: lastDailyDate }));
  }, [dailyStreak, lastDailyDate]);

  // Timer Effect
  useEffect(() => {
    if (appState === 'QUIZ' && quiz && quiz.timeRemaining > 0 && !loading) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (!prev) return null;
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [appState, loading, quiz?.timeRemaining]);

  const handleTimeUp = () => {
    if (!quiz) return;
    playSound('incorrect');
    const attempted = quiz.isChallengeMode ? quiz.currentIndex : quiz.currentIndex + 1;
    finishQuiz(attempted);
  };

  const getAudioContext = () => {
    if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    return audioCtxRef.current;
  };

  const playSound = (type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    const ctx = getAudioContext();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    const now = ctx.currentTime;
    if (type === 'correct') {
      osc.type = 'sine'; osc.frequency.setValueAtTime(523.25, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0.1, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now); osc.stop(now + 0.3);
    } else if (type === 'incorrect') {
      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(220, now);
      osc.frequency.linearRampToValueAtTime(110, now + 0.2);
      gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now); osc.stop(now + 0.3);
    } else if (type === 'nav') {
      osc.type = 'sine'; osc.frequency.setValueAtTime(800, now);
      gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
      osc.start(now); osc.stop(now + 0.1);
    }
  };

  const formatTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${h > 0 ? h + ':' : ''}${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const backgroundSync = async (difficulty: Difficulty, target: number, currentLang: Language, existingCount: number, isDaily: boolean = false) => {
    if (syncRef.current) return;
    syncRef.current = true;
    setIsSyncing(true);

    let currentCount = existingCount;
    const BATCH_SIZE = 20; 

    while (currentCount < target && syncRef.current) {
      const remaining = target - currentCount;
      const fetchCount = Math.min(BATCH_SIZE, remaining);
      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, fetchCount, isDaily);
        if (moreQuestions.length === 0) break;
        setQuiz(prev => {
          if (!prev) return null;
          const uniqueNew = moreQuestions.filter(mq => !prev.questions.some(pq => pq.text === mq.text));
          return { ...prev, questions: [...prev.questions, ...uniqueNew] };
        });
        currentCount += moreQuestions.length;
      } catch (err) { break; }
      await new Promise(r => setTimeout(r, 3000));
    }
    setIsSyncing(false);
    syncRef.current = false;
  };

  const triggerCountdown = () => {
    setPreQuizTimer(10);
    setRandomFact(PRE_QUIZ_FACTS[Math.floor(Math.random() * PRE_QUIZ_FACTS.length)]);
    setAppState('COUNTDOWN');
  };

  const startQuiz = async (difficulty: Difficulty, resume = false) => {
    playSound('nav');
    if (resume && quiz) {
      setAppState('QUIZ');
      if (quiz.questions.length < quiz.totalQuestions) {
        backgroundSync(quiz.difficulty, quiz.totalQuestions, language, quiz.questions.length, quiz.isDailyMode);
      }
      return;
    }

    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true);
    syncRef.current = true;

    const initialQuestions = await fetchQuestions(language, difficulty, 10);
    const newQuiz: QuizState = {
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: config.maxSkips,
      isComplete: false,
      difficulty,
      timeRemaining: config.time,
      totalQuestions: config.count,
      isChallengeMode: difficulty === Difficulty.CHALLENGE
    };
    setQuiz(newQuiz);
    setLoading(false);
    triggerCountdown();
    backgroundSync(difficulty, config.count, language, 10);
  };

  const startDailyQuiz = async () => {
    if (isDailyDone) return;
    playSound('nav');
    setLoading(true);
    syncRef.current = true;

    const initialQuestions = await fetchQuestions(language, Difficulty.MEDIUM, 10, true);
    const newQuiz: QuizState = {
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: 10,
      isComplete: false,
      difficulty: Difficulty.MEDIUM,
      timeRemaining: 20 * 60, 
      totalQuestions: DAILY_QUIZ_COUNT,
      isDailyMode: true
    };
    setQuiz(newQuiz);
    setLoading(false);
    triggerCountdown();
    backgroundSync(Difficulty.MEDIUM, DAILY_QUIZ_COUNT, language, 10, true);
  };

  const saveToHistory = (score: number, totalPlayed: number, skipped: number, diff: Difficulty | 'DAILY', isChallenge?: boolean) => {
    const newEntry: HistoryEntry = {
      id: Date.now().toString(),
      difficulty: diff,
      score,
      total: totalPlayed,
      skipped,
      date: new Date().toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }),
      isChallenge
    };
    setHistory(prev => [newEntry, ...prev].slice(0, 50)); 
  };

  const handleAnswer = (index: number) => {
    if (!quiz || selectedAnswer !== null) return;
    setSelectedAnswer(index);
    setShowExplanation(true);
    if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
      playSound('correct');
      setQuiz(prev => prev ? ({ ...prev, score: prev.score + 1 }) : null);
    } else {
      playSound('incorrect');
    }
  };

  const handleSkip = () => {
    if (!quiz || quiz.skipsRemaining <= 0 || selectedAnswer !== null) return;
    playSound('nav');
    const isLast = quiz.currentIndex + 1 >= quiz.totalQuestions;
    setQuiz(prev => prev ? ({ ...prev, skipsRemaining: prev.skipsRemaining - 1, skippedCount: prev.skippedCount + 1 }) : null);
    if (isLast) {
      finishQuiz(quiz.totalQuestions);
    } else {
      moveNext();
    }
  };

  const finishQuiz = (attempted?: number) => {
    if (!quiz) return;
    const finalAttempted = attempted ?? (quiz.isChallengeMode ? quiz.currentIndex : quiz.currentIndex + 1);
    const diffLabel = quiz.isDailyMode ? 'DAILY' : quiz.difficulty;

    saveToHistory(quiz.score, finalAttempted, quiz.skippedCount, diffLabel, quiz.isChallengeMode);

    if (quiz.isDailyMode) {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const todayStr = today.toISOString().split('T')[0];

      if (lastDailyDate !== todayStr) {
        const last = lastDailyDate ? new Date(lastDailyDate) : null;
        if (last) last.setHours(0,0,0,0);

        const yesterday = new Date(today);
        yesterday.setDate(yesterday.getDate() - 1);
        yesterday.setHours(0,0,0,0);

        if (!last || last.getTime() === yesterday.getTime()) {
           setDailyStreak(prev => prev + 1);
        } else if (last.getTime() < yesterday.getTime()) {
           setDailyStreak(1);
        }
        setLastDailyDate(todayStr);
      }
    }

    setAppState('RESULT');
    localStorage.removeItem(ACTIVE_QUIZ_KEY);
  };

  const moveNext = () => {
    if (!quiz) return;
    if (quiz.currentIndex + 1 >= quiz.questions.length) {
      setLoading(true);
      const checkBuffer = setInterval(() => {
        setQuiz(prev => {
          if (prev && prev.currentIndex + 1 < prev.questions.length) {
            clearInterval(checkBuffer);
            setLoading(false);
            return { ...prev, currentIndex: prev.currentIndex + 1 };
          }
          return prev;
        });
      }, 500);
    } else {
      setQuiz(prev => prev ? ({ ...prev, currentIndex: prev.currentIndex + 1 }) : null);
    }
  };

  const nextQuestion = () => {
    if (!quiz) return;
    playSound('nav');
    setSelectedAnswer(null);
    setShowExplanation(false);
    if (quiz.currentIndex + 1 < quiz.totalQuestions) {
      moveNext();
    } else {
      finishQuiz();
    }
  };

  const handleNav = (state: AppState) => {
    playSound('nav');
    setAppState(state);
    if (state !== 'QUIZ' && state !== 'COUNTDOWN') syncRef.current = false;
  };

  const toggleBookmark = (q: Question) => {
    playSound('nav');
    setBookmarks(prev => prev.find(b => b.id === q.id) ? prev.filter(b => b.id !== q.id) : [...prev, q]);
  };

  const clearHistory = () => {
    playSound('nav');
    if (window.confirm(t.clearHistory + '?')) setHistory([]);
  };

  const handleShare = async () => {
    if (!quiz) return;
    playSound('nav');
    const total = quiz.isChallengeMode ? quiz.currentIndex : quiz.totalQuestions;
    const diffLabel = quiz.isDailyMode ? t.dailyQuiz : (t[quiz.difficulty] || quiz.difficulty);
    const message = t.shareText(quiz.score, total, diffLabel);
    if (navigator.share) {
      try { await navigator.share({ title: APP_NAME, text: message, url: window.location.href }); } catch (err) { console.error(err); }
    } else {
      try { await navigator.clipboard.writeText(message); setShowCopied(true); setTimeout(() => setShowCopied(false), 2000); } catch (err) { console.error(err); }
    }
  };

  const isBookmarked = (id: string) => bookmarks.some(b => b.id === id);

  const ThematicLoader = () => (
    <div className="flex flex-col items-center justify-center min-h-[400px] w-full max-w-lg mx-auto p-8 space-y-12 animate-fade-in">
      <div className="relative">
        <div className="w-32 h-32 text-orange-600 animate-[spin_10s_linear_infinite] drop-shadow-lg">
          <svg viewBox="0 0 100 100" className="w-full h-full" fill="currentColor">
            <circle cx="50" cy="50" r="48" fill="none" stroke="currentColor" strokeWidth="1" />
            <circle cx="50" cy="50" r="8" fill="currentColor" />
            {[...Array(24)].map((_, i) => (
              <line key={i} x1="50" y1="50" x2={50 + 40 * Math.cos((i * 15 * Math.PI) / 180)} y2={50 + 40 * Math.sin((i * 15 * Math.PI) / 180)} stroke="currentColor" strokeWidth="1.5" />
            ))}
            <circle cx="50" cy="50" r="42" fill="none" stroke="currentColor" strokeWidth="2" />
          </svg>
        </div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-40 h-40 border-4 border-orange-200 rounded-full animate-ping opacity-20"></div>
      </div>
      <div className="w-full space-y-8 text-center">
        <div className="space-y-2">
          <p className="text-3xl font-black text-orange-900 tracking-tighter">
            {quiz && quiz.questions.length < quiz.totalQuestions && quiz.currentIndex >= quiz.questions.length - 1 ? "कालचक्र घूम रहा है..." : "इतिहास के पन्नों को खोजा जा रहा है..."}
          </p>
          <div className="flex items-center justify-center gap-2 text-orange-700/60 font-black text-xs uppercase tracking-widest">
            <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
            {isSyncing ? `प्रमाण एकत्रित हो रहे हैं... (${quiz?.questions.length}/${quiz?.totalQuestions})` : "ज्ञान संचय जारी है..."}
          </div>
        </div>
        <div className="relative w-full h-1 bg-orange-100 rounded-full overflow-hidden">
          <div className="absolute inset-0 bg-gradient-to-r from-orange-400 via-red-500 to-orange-400 w-1/3 animate-[translateX_3s_linear_infinite]"></div>
        </div>
        <div className="flex justify-between text-[10px] font-black text-orange-400 uppercase tracking-tighter px-1"><span>प्राचीन</span><span>मध्यकालीन</span><span>आधुनिक</span></div>
      </div>
      <style>{`@keyframes translateX { 0% { transform: translateX(-100%); } 100% { transform: translateX(300%); } }`}</style>
    </div>
  );

  const isDailyDone = lastDailyDate === new Date().toISOString().split('T')[0];

  return (
    <div className={`min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800 ${quiz?.isChallengeMode && (appState === 'QUIZ' || appState === 'COUNTDOWN') ? 'ring-inset ring-8 ring-red-500/20' : ''}`}>
      <header className={`w-full p-4 flex justify-between items-center text-white shadow-md z-30 sticky top-0 transition-colors ${quiz?.isChallengeMode && (appState === 'QUIZ' || appState === 'COUNTDOWN') ? 'bg-red-600' : 'bg-orange-600'}`}>
        <span className="font-bold text-lg cursor-pointer flex items-center gap-2" onClick={() => handleNav('LANDING')}>
          <span className="bg-white text-orange-600 w-8 h-8 rounded-full flex items-center justify-center font-black">इ</span>
          <span className="hidden xs:inline">{AUTHOR_NAME}</span>
        </span>
        {(appState === 'QUIZ' || appState === 'COUNTDOWN') && quiz && (
