                  <div className="space-y-4">
                    <h3 className="text-5xl font-black text-gray-900 tracking-tighter">{quiz.score === quiz.totalQuestions ? "विजेता! (Legendary)" : quiz.score > quiz.totalQuestions / 2 ? "विजयी भव!" : "प्रयास जारी रखें!"}</h3>
                    <p className={`text-2xl font-bold px-6 py-3 rounded-full inline-block ${quiz.isDailyMode ? 'bg-indigo-100 text-indigo-800' : 'bg-orange-100 text-orange-800'}`}>
                      आपने {quiz.isDailyMode ? t.dailyQuiz : (t[quiz.difficulty] || quiz.difficulty)} स्तर पर {quiz.totalQuestions} में से {quiz.score} सही उत्तर दिए।
                    </p>
                    {quiz.isDailyMode && (
                       <div className="mt-4 text-indigo-600 font-black text-xl animate-bounce">
                          🔥 {t.dailyStreak}: {dailyStreak}
                       </div>
                    )}
                  </div>
                </>
             )}
            <div className="flex flex-col gap-4 w-full max-w-lg mx-auto">
              <button onClick={handleShare} className="w-full py-5 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-3xl shadow-xl transition transform hover:scale-105 active:scale-95 flex items-center justify-center gap-3 text-xl uppercase tracking-widest">{t.shareScore}</button>
              <div className="flex flex-col sm:flex-row gap-5">
                <button onClick={() => { handleNav('LANDING'); setQuiz(null); localStorage.removeItem(ACTIVE_QUIZ_KEY); }} className="flex-1 py-5 bg-white border-4 border-orange-600 text-orange-600 font-black rounded-3xl shadow-xl hover:bg-orange-50 transition transform hover:scale-105">मुख्य पृष्ठ (HOME)</button>
                <button onClick={() => { if(quiz.isDailyMode) handleNav('LANDING'); else startQuiz(quiz.difficulty); }} className={`flex-1 py-5 text-white font-black rounded-3xl shadow-xl transition transform hover:scale-105 ${quiz.isChallengeMode ? 'bg-red-600' : 'bg-orange-600'}`}>{quiz.isDailyMode ? t.finish : t.restart}</button>
              </div>
            </div>
          </div>
        )}
        {appState === 'SETTINGS' && (
          <div className="w-full bg-white p-10 rounded-[3rem] shadow-xl space-y-10 border-4 border-orange-50">
            <div className="flex items-center justify-between border-b-2 border-orange-100 pb-6"><h2 className="text-4xl font-black text-gray-900 tracking-tighter">{t.settings}</h2><button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg></button></div>
            <section className="space-y-6"><h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider"><span>🔊</span>{t.soundEffects}</h3><div className="flex gap-4"><button onClick={() => { setSoundEnabled(true); playSound('nav'); }} className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${soundEnabled ? 'bg-orange-600 text-white' : 'bg-gray-100 text-gray-400'}`}>{t.on}</button><button onClick={() => setSoundEnabled(false)} className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${!soundEnabled ? 'bg-orange-600 text-white' : 'bg-gray-100 text-gray-400'}`}>{t.off}</button></div></section>
            <section className="space-y-6"><h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider"><span>🌐</span>{t.selectLang}</h3><div className="grid grid-cols-2 gap-4">{LANGUAGES.map((lang) => (<button key={lang.code} onClick={() => { setLanguage(lang.code); playSound('nav'); }} className={`p-4 rounded-2xl border-4 transition-all text-lg font-black ${language === lang.code ? 'border-orange-600 bg-orange-50 text-orange-600 shadow-inner' : 'border-gray-50 text-gray-400'}`}>{lang.name}</button>))}</div></section>
          </div>
        )}
      </main>
      <footer className="w-full p-8 text-center">
        <div className="flex items-center justify-center gap-2 text-[10px] font-black text-orange-400 uppercase tracking-widest mb-4">
           <span className="w-2 h-2 bg-green-500 rounded-full"></span>
           Online & Verified by Google Search
        </div>
        <div className="max-w-xs mx-auto h-px bg-orange-100 mb-6"></div>
        <p className="text-gray-400 text-sm font-bold uppercase tracking-[0.4em]">&copy; {new Date().getFullYear()} {APP_NAME}</p>
        <p className="text-orange-900/30 text-[10px] mt-2 font-black tracking-widest">BHARAT VARSHA HISTORY PROJECT</p>
      </footer>
    </div>
  );
};

export default App;

export enum Language {
  HINDI = 'HINDI',
  ENGLISH = 'ENGLISH',
  SANSKRIT = 'SANSKRIT',
  TAMIL = 'TAMIL',
  TELUGU = 'TELUGU',
  MARATHI = 'MARATHI',
  BENGALI = 'BENGALI',
  GUJARATI = 'GUJARATI'
}

export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD',
  CHALLENGE = 'CHALLENGE',
  EXAM = 'EXAM'
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
  era: 'Ancient' | 'Medieval' | 'Modern';
  sources?: { title: string; uri: string }[];
}

export interface HistoryEntry {
  id: string;
  difficulty: Difficulty | 'DAILY';
  score: number;
  total: number;
  skipped: number;
  date: string;
  isChallenge?: boolean;
}

export type AppState = 'LANDING' | 'DIFFICULTY_SELECT' | 'QUIZ' | 'SETTINGS' | 'RESULT' | 'BOOKMARKS' | 'HISTORY' | 'COUNTDOWN';

export interface QuizState {
  questions: Question[];
  currentIndex: number;
  score: number;
  skippedCount: number;
  skipsRemaining: number;
  isComplete: boolean;
  difficulty: Difficulty;
  timeRemaining: number;
  totalQuestions: number;
  isChallengeMode?: boolean;
  isDailyMode?: boolean;
  isExamMode?: boolean;
}

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Language, Question, QuizState, Difficulty, HistoryEntry } from './types';
import { fetchQuestions } from './services/geminiService';
import { AUTHOR_NAME, APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES, DAILY_QUIZ_COUNT } from './constants';

const BOOKMARKS_KEY = 'history_bookmarks';
const HISTORY_KEY = 'quiz_history_data';
const ACTIVE_QUIZ_KEY = 'active_quiz_session';
const DAILY_STATS_KEY = 'daily_stats_v1';

const PRE_QUIZ_FACTS = [
  "सिंधु घाटी सभ्यता दुनिया की सबसे पुरानी शहरी सभ्यताओं में से एक थी।",
  "मौर्य साम्राज्य ने पहली बार लगभग पूरे भारतीय उपमहाद्वीप को एकजुट किया।",
  "प्राचीन नालंदा विश्वविद्यालय में 90 लाख से अधिक पांडुलिपियां थीं।",
  "छत्रपति शिवाजी महाराज को भारतीय नौसेना का जनक माना जाता है।",
  "सम्राट अशोक के शिलालेख शांति और अहिंसा का संदेश देते हैं।",
  "गुप्त काल को भारतीय इतिहास का 'स्वर्ण युग' कहा जाता है।",
  "रानी लक्ष्मीबाई ने 1857 के स्वतंत्रता संग्राम में अदम्य साहस दिखाया।",
  "भारतीय संविधान दुनिया का सबसे बड़ा लिखित संविधान है।"
];

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState | null>(null);
  const [bookmarks, setBookmarks] = useState<Question[]>([]);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [showCopied, setShowCopied] = useState(false);

  // Countdown Logic
  const [preQuizTimer, setPreQuizTimer] = useState(10);
  const [randomFact, setRandomFact] = useState("");

  // Daily Stats
  const [dailyStreak, setDailyStreak] = useState(0);
  const [lastDailyDate, setLastDailyDate] = useState<string | null>(null);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);

  const t = TRANSLATIONS[language] || TRANSLATIONS[Language.ENGLISH];

  // Load persistence on init
  useEffect(() => {
    const savedBookmarks = localStorage.getItem(BOOKMARKS_KEY);
    if (savedBookmarks) {
      try { setBookmarks(JSON.parse(savedBookmarks)); } catch (e) { console.error(e); }
    }

    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) {
      try { setHistory(JSON.parse(savedHistory)); } catch (e) { console.error(e); }
    }

    const savedStats = localStorage.getItem(DAILY_STATS_KEY);
    if (savedStats) {
      try {
        const stats = JSON.parse(savedStats);
        setDailyStreak(stats.streak || 0);
        setLastDailyDate(stats.lastDate || null);

        if (stats.lastDate) {
          const last = new Date(stats.lastDate);
          last.setHours(0, 0, 0, 0);
          const today = new Date();
          today.setHours(0, 0, 0, 0);

          const yesterday = new Date(today);
          yesterday.setDate(yesterday.getDate() - 1);

          if (last.getTime() < yesterday.getTime()) {
             setDailyStreak(0);
          }
        }
      } catch (e) { console.error(e); }
    }

    const savedActiveQuiz = localStorage.getItem(ACTIVE_QUIZ_KEY);
    if (savedActiveQuiz) {
      try { 
        const parsed = JSON.parse(savedActiveQuiz);
        if (parsed && !parsed.isComplete) {
          setQuiz(parsed);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  // Countdown timer effect
  useEffect(() => {
    if (appState === 'COUNTDOWN' && preQuizTimer > 0) {
      const timer = setTimeout(() => {
        setPreQuizTimer(preQuizTimer - 1);
        if (preQuizTimer % 2 === 0) playSound('nav');
      }, 1000);
      return () => clearTimeout(timer);
    } else if (appState === 'COUNTDOWN' && preQuizTimer === 0) {
      setAppState('QUIZ');
    }
  }, [appState, preQuizTimer]);

  // Save persistence on change
  useEffect(() => {
    localStorage.setItem(BOOKMARKS_KEY, JSON.stringify(bookmarks));
  }, [bookmarks]);

  useEffect(() => {
    localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    if (quiz) {
      localStorage.setItem(ACTIVE_QUIZ_KEY, JSON.stringify(quiz));
    }
  }, [quiz]);

  useEffect(() => {
    localStorage.setItem(DAILY_STATS_KEY, JSON.stringify({ streak: dailyStreak, lastDate: lastDailyDate }));
  }, [dailyStreak, lastDailyDate]);

  // Timer Effect
  useEffect(() => {
    if (appState === 'QUIZ' && quiz && quiz.timeRemaining > 0 && !loading) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (!prev) return null;
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [appState, loading, quiz?.timeRemaining]);

  const handleTimeUp = () => {
    if (!quiz) return;
    playSound('incorrect');
    const attempted = quiz.isChallengeMode ? quiz.currentIndex : quiz.currentIndex + 1;
    finishQuiz(attempted);
  };

  const getAudioContext = () => {
    if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    return audioCtxRef.current;
  };

  const playSound = (type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    const ctx = getAudioContext();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    const now = ctx.currentTime;
    if (type === 'correct') {
      osc.type = 'sine'; osc.frequency.setValueAtTime(523.25, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0.1, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now); osc.stop(now + 0.3);
    } else if (type === 'incorrect') {
      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(220, now);
      osc.frequency.linearRampToValueAtTime(110, now + 0.2);
      gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now); osc.stop(now + 0.3);
    } else if (type === 'nav') {
      osc.type = 'sine'; osc.frequency.setValueAtTime(800, now);
      gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
      osc.start(now); osc.stop(now + 0.1);
    }
  };

  const formatTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${h > 0 ? h + ':' : ''}${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const backgroundSync = async (difficulty: Difficulty, target: number, currentLang: Language, existingCount: number, isDaily: boolean = false) => {
    if (syncRef.current) return;
    syncRef.current = true;
    setIsSyncing(true);

    let currentCount = existingCount;
    const BATCH_SIZE = 20; 

    while (currentCount < target && syncRef.current) {
      const remaining = target - currentCount;
      const fetchCount = Math.min(BATCH_SIZE, remaining);
      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, fetchCount, isDaily);
        if (moreQuestions.length === 0) break;
        setQuiz(prev => {
          if (!prev) return null;
          const uniqueNew = moreQuestions.filter(mq => !prev.questions.some(pq => pq.text === mq.text));
          return { ...prev, questions: [...prev.questions, ...uniqueNew] };
        });
        currentCount += moreQuestions.length;
      } catch (err) { break; }
      await new Promise(r => setTimeout(r, 3000));
    }
    setIsSyncing(false);
    syncRef.current = false;
  };

  const triggerCountdown = () => {
    setPreQuizTimer(10);
    setRandomFact(PRE_QUIZ_FACTS[Math.floor(Math.random() * PRE_QUIZ_FACTS.length)]);
    setAppState('COUNTDOWN');
  };

  const startQuiz = async (difficulty: Difficulty, resume = false) => {
    playSound('nav');
    if (resume && quiz) {
      setAppState('QUIZ');
      if (quiz.questions.length < quiz.totalQuestions) {
        backgroundSync(quiz.difficulty, quiz.totalQuestions, language, quiz.questions.length, quiz.isDailyMode);
      }
      return;
    }

    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true);
    syncRef.current = true;

    const initialQuestions = await fetchQuestions(language, difficulty, 10);
    const newQuiz: QuizState = {
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: config.maxSkips,
      isComplete: false,
      difficulty,
      timeRemaining: config.time,
      totalQuestions: config.count,
      isChallengeMode: difficulty === Difficulty.CHALLENGE,
      isExamMode: difficulty === Difficulty.EXAM
    };
    setQuiz(newQuiz);
    setLoading(false);
    triggerCountdown();
    backgroundSync(difficulty, config.count, language, 10);
  };

  const startDailyQuiz = async () => {
    if (isDailyDone) return;
    playSound('nav');
    setLoading(true);
    syncRef.current = true;

    const initialQuestions = await fetchQuestions(language, Difficulty.MEDIUM, 10, true);
    const newQuiz: QuizState = {
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: 10,
      isComplete: false,
      difficulty: Difficulty.MEDIUM,
      timeRemaining: 20 * 60, 
      totalQuestions: DAILY_QUIZ_COUNT,
      isDailyMode: true
    };
    setQuiz(newQuiz);
    setLoading(false);
    triggerCountdown();
    backgroundSync(Difficulty.MEDIUM, DAILY_QUIZ_COUNT, language, 10, true);
  };

  const saveToHistory = (score: number, totalPlayed: number, skipped: number, diff: Difficulty | 'DAILY', isChallenge?: boolean) => {
    const newEntry: HistoryEntry = {
      id: Date.now().toString(),
      difficulty: diff,
      score,
      total: totalPlayed,
      skipped,
      date: new Date().toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }),
      isChallenge
    };
    setHistory(prev => [newEntry, ...prev].slice(0, 50)); 
  };

  const handleAnswer = (index: number) => {
    if (!quiz || selectedAnswer !== null) return;
    setSelectedAnswer(index);

    if (quiz.isExamMode) {
      // In Exam mode, no intermediate feedback
      playSound('nav');
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
        setQuiz(prev => prev ? ({ ...prev, score: prev.score + 1 }) : null);
      }
      // Short delay and move to next question automatically
      setTimeout(() => {
        nextQuestion();
      }, 300);
    } else {
      setShowExplanation(true);
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
        playSound('correct');
        setQuiz(prev => prev ? ({ ...prev, score: prev.score + 1 }) : null);
      } else {
        playSound('incorrect');
      }
    }
  };

  const handleSkip = () => {
    if (!quiz || quiz.skipsRemaining <= 0 || selectedAnswer !== null || quiz.isExamMode) return;
    playSound('nav');
    const isLast = quiz.currentIndex + 1 >= quiz.totalQuestions;
    setQuiz(prev => prev ? ({ ...prev, skipsRemaining: prev.skipsRemaining - 1, skippedCount: prev.skippedCount + 1 }) : null);
    if (isLast) {
      finishQuiz(quiz.totalQuestions);
    } else {
      moveNext();
    }
  };

  const finishQuiz = (attempted?: number) => {
    if (!quiz) return;
    const finalAttempted = attempted ?? (quiz.isChallengeMode ? quiz.currentIndex : quiz.currentIndex + 1);
    const diffLabel = quiz.isDailyMode ? 'DAILY' : quiz.difficulty;

    saveToHistory(quiz.score, finalAttempted, quiz.skippedCount, diffLabel, quiz.isChallengeMode);

    if (quiz.isDailyMode) {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const todayStr = today.toISOString().split('T')[0];

      if (lastDailyDate !== todayStr) {
        const last = lastDailyDate ? new Date(lastDailyDate) : null;
        if (last) last.setHours(0,0,0,0);

        const yesterday = new Date(today);
        yesterday.setDate(yesterday.getDate() - 1);
        yesterday.setHours(0,0,0,0);

        if (!last || last.getTime() === yesterday.getTime()) {
           setDailyStreak(prev => prev + 1);
        } else if (last.getTime() < yesterday.getTime()) {
           setDailyStreak(1);
        }
        setLastDailyDate(todayStr);
      }
    }

    setAppState('RESULT');
    localStorage.removeItem(ACTIVE_QUIZ_KEY);
  };

  const moveNext = () => {
    if (!quiz) return;
    if (quiz.currentIndex + 1 >= quiz.questions.length) {
      setLoading(true);
      const checkBuffer = setInterval(() => {
        setQuiz(prev => {
          if (prev && prev.currentIndex + 1 < prev.questions.length) {
            clearInterval(checkBuffer);
            setLoading(false);
            return { ...prev, currentIndex: prev.currentIndex + 1 };
          }
          return prev;
        });
      }, 500);
    } else {
      setQuiz(prev => prev ? ({ ...prev, currentIndex: prev.currentIndex + 1 }) : null);
    }
  };

  const nextQuestion = () => {
    if (!quiz) return;
    if (!quiz.isExamMode) playSound('nav');
    setSelectedAnswer(null);
    setShowExplanation(false);
    if (quiz.currentIndex + 1 < quiz.totalQuestions) {
      moveNext();
    } else {
      finishQuiz();
    }
  };

  const handleNav = (state: AppState) => {
    playSound('nav');
    setAppState(state);
    if (state !== 'QUIZ' && state !== 'COUNTDOWN') syncRef.current = false;
  };

  const toggleBookmark = (q: Question) => {
    if (quiz?.isExamMode) return;
    playSound('nav');
    setBookmarks(prev => prev.find(b => b.id === q.id) ? prev.filter(b => b.id !== q.id) : [...prev, q]);
  };

  const clearHistory = () => {
    playSound('nav');
    if (window.confirm(t.clearHistory + '?')) setHistory([]);
  };

  const handleShare = async () => {
    if (!quiz) return;
    playSound('nav');
    const total = quiz.isChallengeMode ? quiz.currentIndex : quiz.totalQuestions;
    const diffLabel = quiz.isDailyMode ? t.dailyQuiz : (t[quiz.difficulty] || quiz.difficulty);
    const message = t.shareText(quiz.score, total, diffLabel);
    if (navigator.share) {
      try { await navigator.share({ title: APP_NAME, text: message, url: window.location.href }); } catch (err) { console.error(err); }
    } else {
      try { await navigator.clipboard.writeText(message); setShowCopied(true); setTimeout(() => setShowCopied(false), 2000); } catch (err) { console.error(err); }
    }
  };

  const isBookmarked = (id: string) => bookmarks.some(b => b.id === id);

  const ThematicLoader = () => (
    <div className="flex flex-col items-center justify-center min-h-[400px] w-full max-w-lg mx-auto p-8 space-y-12 animate-fade-in">
      <div className="relative">
        <div className="w-32 h-32 text-orange-600 animate-[spin_10s_linear_infinite] drop-shadow-lg">
          <svg viewBox="0 0 100 100" className="w-full h-full" fill="currentColor">
            <circle cx="50" cy="50" r="48" fill="none" stroke="currentColor" strokeWidth="1" />
            <circle cx="50" cy="50" r="8" fill="currentColor" />
            {[...Array(24)].map((_, i) => (
              <line key={i} x1="50" y1="50" x2={50 + 40 * Math.cos((i * 15 * Math.PI) / 180)} y2={50 + 40 * Math.sin((i * 15 * Math.PI) / 180)} stroke="currentColor" strokeWidth="1.5" />
            ))}
            <circle cx="50" cy="50" r="42" fill="none" stroke="currentColor" strokeWidth="2" />
          </svg>
        </div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-40 h-40 border-4 border-orange-200 rounded-full animate-ping opacity-20"></div>
      </div>
      <div className="w-full space-y-8 text-center">
        <div className="space-y-2">
          <p className="text-3xl font-black text-orange-900 tracking-tighter">
            {quiz && quiz.questions.length < quiz.totalQuestions && quiz.currentIndex >= quiz.questions.length - 1 ? "कालचक्र घूम रहा है..." : "इतिहास के पन्नों को खोजा जा रहा है..."}
          </p>
          <div className="flex items-center justify-center gap-2 text-orange-700/60 font-black text-xs uppercase tracking-widest">
            <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
            {isSyncing ? `प्रमाण एकत्रित हो रहे हैं... (${quiz?.questions.length}/${quiz?.totalQuestions})` : "ज्ञान संचय जारी है..."}
          </div>
        </div>
        <div className="relative w-full h-1 bg-orange-100 rounded-full overflow-hidden">
          <div className="absolute inset-0 bg-gradient-to-r from-orange-400 via-red-500 to-orange-400 w-1/3 animate-[translateX_3s_linear_infinite]"></div>
        </div>
        <div className="flex justify-between text-[10px] font-black text-orange-400 uppercase tracking-tighter px-1"><span>प्राचीन</span><span>मध्यकालीन</span><span>आधुनिक</span></div>
      </div>
      <style>{`@keyframes translateX { 0% { transform: translateX(-100%); } 100% { transform: translateX(300%); } }`}</style>
    </div>
  );

  const isDailyDone = lastDailyDate === new Date().toISOString().split('T')[0];

  return (
    <div className={`min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800 ${quiz?.isChallengeMode && (appState === 'QUIZ' || appState === 'COUNTDOWN') ? 'ring-inset ring-8 ring-red-500/20' : ''}`}>
      <header className={`w-full p-4 flex justify-between items-center text-white shadow-md z-30 sticky top-0 transition-colors ${quiz?.isChallengeMode && (appState === 'QUIZ' || appState === 'COUNTDOWN') ? 'bg-red-600' : quiz?.isExamMode && (appState === 'QUIZ' || appState === 'COUNTDOWN') ? 'bg-slate-800' : 'bg-orange-600'}`}>
        <span className="font-bold text-lg cursor-pointer flex items-center gap-2" onClick={() => handleNav('LANDING')}>
          <span className="bg-white text-orange-600 w-8 h-8 rounded-full flex items-center justify-center font-black">इ</span>
          <span className="hidden xs:inline">{AUTHOR_NAME}</span>
        </span>
        {(appState === 'QUIZ' || appState === 'COUNTDOWN') && quiz && (
          <div className={`flex items-center gap-2 sm:gap-3 px-2 sm:px-3 py-1.5 rounded-full font-mono font-bold text-xs sm:text-sm shadow-inner transition-colors ${quiz.isChallengeMode ? 'bg-black/40' : quiz.isExamMode ? 'bg-white/10' : 'bg-white/20'}`}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            <span className={quiz.timeRemaining < 30 ? 'text-yellow-300 animate-pulse' : ''}>{formatTime(quiz.timeRemaining)}</span>
          </div>
        )}
        <div className="flex gap-1.5 sm:gap-2">
          {dailyStreak > 0 && (
            <div className="flex items-center gap-1 bg-white/20 px-3 py-1 rounded-full text-[10px] font-black">
              🔥 {dailyStreak}
            </div>
          )}
          <button onClick={() => handleNav('HISTORY')} className="bg-white/20 hover:bg-white/30 p-1.5 rounded-full transition"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg></button>
          <button onClick={() => handleNav('BOOKMARKS')} className="bg-white/20 hover:bg-white/30 p-1.5 rounded-full transition relative"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg>{bookmarks.length > 0 && <span className="absolute -top-1 -right-1 bg-white text-orange-600 text-[10px] w-4 h-4 rounded-full flex items-center justify-center font-black">{bookmarks.length}</span>}</button>
          <button onClick={() => handleNav('SETTINGS')} className="p-1.5 hover:bg-white/10 rounded-full transition"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg></button>
        </div>
      </header>
      <main className="flex-1 w-full max-w-2xl px-4 py-8 flex flex-col items-center justify-center">
        {appState === 'LANDING' && (
          <div className="text-center animate-fade-in py-10 w-full">
            <h1 className="text-6xl md:text-9xl font-black text-orange-600 mb-2 hindi-font tracking-tighter drop-shadow-xl select-none">{INTRO_MAIN}</h1>
            <p className="text-xl md:text-3xl text-orange-800 font-bold mb-12 italic opacity-80">"{INTRO_SUB}"</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-w-2xl mx-auto mb-12">
              <div className={`p-6 rounded-[2.5rem] border-4 shadow-xl text-left flex flex-col justify-between h-56 transition-all transform hover:scale-[1.02] ${isDailyDone ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-orange-100'}`}>
                <div>
                  <div className="flex justify-between items-start">
                    <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${isDailyDone ? 'bg-indigo-600 text-white' : 'bg-orange-100 text-orange-600'}`}>
                      {t.dailyQuiz}
                    </span>
                    <span className="text-2xl">🔥 {dailyStreak}</span>
                  </div>
                  <h3 className="text-2xl font-black text-gray-900 mt-4">{t.dailyGoal}</h3>
                  <p className="text-xs text-gray-400 font-bold mt-1">{isDailyDone ? t.dailyDone : "चुनौती स्वीकार करें"}</p>
                </div>
                {!isDailyDone ? (
                   <button onClick={startDailyQuiz} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-2xl shadow-lg transition transform active:scale-95 uppercase tracking-widest text-sm">
                      {t.start}
                   </button>
                ) : (
                  <div className="flex items-center gap-2 text-indigo-600 font-black">
                     <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 24 24" fill="currentColor"><path fillRule="evenodd" d="M2.25 12c0-5.385 4.365-9.75 9.75-9.75s9.75 4.365 9.75 9.75-4.365 9.75-9.75 9.75S2.25 17.385 2.25 12Zm13.36-1.814a.75.75 0 1 0-1.22-.872l-3.236 4.53L9.53 12.22a.75.75 0 0 0-1.06 1.06l2.25 2.25a.75.75 0 0 0 1.14-.094l3.74-5.24Z" clipRule="evenodd" /></svg>
                     {t.dailyDone}
                  </div>
                )}
              </div>

              {/* Exam Mode Landing Button */}
              <div className="p-6 rounded-[2.5rem] border-4 border-slate-100 bg-slate-900 shadow-xl text-left flex flex-col justify-between h-56 transition-all transform hover:scale-[1.02]">
                 <div>
                    <span className="text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full bg-slate-700 text-white">{t.examMode}</span>
                    <h3 className="text-2xl font-black text-white mt-4">{t[Difficulty.EXAM]}</h3>
                    <p className="text-xs text-slate-400 font-bold mt-1">{t.finalResultsOnly}</p>
                 </div>
                 <button onClick={() => startQuiz(Difficulty.EXAM)} className="w-full py-3 bg-white text-slate-900 font-black rounded-2xl shadow-lg transition transform active:scale-95 uppercase tracking-widest text-sm">
                    {t.start}
                 </button>
              </div>
            </div>

            <div className="space-y-4 max-w-sm mx-auto">
              {quiz && !quiz.isComplete && (
                <button onClick={() => startQuiz(quiz.difficulty, true)} className="w-full py-5 px-8 bg-indigo-600 hover:bg-indigo-700 text-white font-black text-xl rounded-3xl shadow-xl transform hover:scale-105 transition flex items-center justify-center gap-3">
                   {t.continue} ({t[quiz.difficulty] || quiz.difficulty})
                </button>
              )}
              <button onClick={() => handleNav('DIFFICULTY_SELECT')} className="w-full py-5 px-8 bg-orange-600 hover:bg-orange-700 text-white font-black text-2xl rounded-3xl shadow-2xl transform hover:scale-105 active:scale-95 transition-all duration-200 uppercase tracking-widest">{t.start}</button>

              <div className="grid grid-cols-2 gap-4">
                <button onClick={() => handleNav('BOOKMARKS')} className="w-full py-3 px-2 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition-all flex items-center justify-center gap-2 text-sm"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-orange-600" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg>{t.bookmarks}</button>
                <button onClick={() => handleNav('HISTORY')} className="w-full py-3 px-2 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition-all flex items-center justify-center gap-2 text-sm"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-orange-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>{t.history}</button>
              </div>
            </div>
          </div>
        )}

        {appState === 'COUNTDOWN' && (
          <div className="flex flex-col items-center justify-center text-center space-y-8 animate-fade-in w-full max-w-lg mx-auto py-20 px-6">
            <div className="relative">
              <svg className="w-64 h-64 transform -rotate-90">
                <circle
                  cx="128"
                  cy="128"
                  r="110"
                  fill="none"
                  stroke={quiz?.isExamMode ? "#334155" : "#fed7aa"}
                  strokeWidth="10"
                />
                <circle
                  cx="128"
                  cy="128"
                  r="110"
                  fill="none"
                  stroke={quiz?.isExamMode ? "#f8fafc" : "#ea580c"}
                  strokeWidth="10"
                  strokeDasharray="691.15"
                  strokeDashoffset={691.15 - (preQuizTimer / 10) * 691.15}
                  strokeLinecap="round"
                  className="transition-all duration-1000 linear"
                />
              </svg>
              <div className="absolute inset-0 flex items-center justify-center">
                <span className={`text-8xl font-black ${quiz?.isExamMode ? 'text-slate-800' : 'text-orange-600'} animate-pulse`}>{preQuizTimer}</span>
              </div>
            </div>

            <div className="space-y-4">
              <h2 className={`text-4xl font-black ${quiz?.isExamMode ? 'text-slate-900' : 'text-orange-900'} tracking-tighter uppercase`}>तैयार हो जाइए!</h2>
              <div className={`p-8 rounded-[2.5rem] border-4 shadow-xl ${quiz?.isExamMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-orange-100 text-gray-800'}`}>
                <p className={`text-xs font-black uppercase tracking-widest mb-2 ${quiz?.isExamMode ? 'text-slate-400' : 'text-orange-400'}`}>क्या आप जानते हैं?</p>
                <p className="text-xl font-bold leading-relaxed italic">"{randomFact}"</p>
              </div>
            </div>

            <p className={`${quiz?.isExamMode ? 'text-slate-500' : 'text-orange-700/60'} font-black animate-bounce`}>प्रश्नोत्तरी बस शुरू होने वाली है...</p>
          </div>
        )}

        {appState === 'HISTORY' && (
          <div className="w-full space-y-6 animate-fade-in pb-10">
            <div className="flex items-center justify-between"><h2 className="text-3xl font-black text-orange-900">{t.history}</h2><div className="flex items-center gap-2">{history.length > 0 && <button onClick={clearHistory} className="p-2 text-red-500 hover:bg-red-50 rounded-full transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>}<button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg></button></div></div>
            <div className="space-y-4">{history.length === 0 ? <div className="text-center p-20 bg-white border-4 border-dashed border-orange-100 rounded-[3rem] text-xl text-gray-400 font-medium">{t.noHistory}</div> : history.map((entry) => (
              <div key={entry.id} className="bg-white p-5 rounded-3xl shadow-lg border-2 border-orange-50 flex items-center justify-between">
                <div className="space-y-1">
                  <div className="flex items-center gap-2">
                    <span className={`text-[10px] px-2 py-0.5 rounded-full font-black uppercase tracking-widest ${entry.difficulty === 'DAILY' ? 'bg-indigo-100 text-indigo-600' : entry.difficulty === Difficulty.EXAM ? 'bg-slate-200 text-slate-700' : entry.difficulty === Difficulty.CHALLENGE ? 'bg-red-100 text-red-600' : entry.difficulty === Difficulty.HARD ? 'bg-rose-100 text-rose-600' : entry.difficulty === Difficulty.MEDIUM ? 'bg-blue-100 text-blue-600' : 'bg-emerald-100 text-emerald-600'}`}>
                      {entry.difficulty === 'DAILY' ? t.dailyQuiz : (t[entry.difficulty as Difficulty] || entry.difficulty)}
                    </span>
                    <span className="text-xs text-gray-400 font-medium">{entry.date}</span>
                  </div>
                  <h3 className="text-lg font-bold text-gray-900">{entry.score}/{entry.total} {entry.isChallenge && <span className="text-xs bg-red-50 text-red-600 px-2 py-0.5 rounded ml-1">CHALLENGE</span>}</h3>
                </div>
                <div className="w-12 h-12 rounded-full border-4 border-orange-100 flex items-center justify-center font-black text-orange-600">{Math.round((entry.score / entry.total) * 100)}%</div>
              </div>
            ))}</div>
          </div>
        )}
        {appState === 'BOOKMARKS' && (
          <div className="w-full space-y-6 animate-fade-in pb-10">
            <div className="flex items-center justify-between"><h2 className="text-3xl font-black text-orange-900">{t.savedQuestions}</h2><button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg></button></div>
            <div className="space-y-4">{bookmarks.length === 0 ? <div className="text-center p-20 bg-white border-4 border-dashed border-orange-100 rounded-[3rem] text-xl text-gray-400 font-medium">{t.noBookmarks}</div> : bookmarks.map((q) => (
              <div key={q.id} className="bg-white p-6 rounded-3xl shadow-lg border-2 border-orange-50 relative group">
                <button onClick={() => toggleBookmark(q)} className="absolute top-4 right-4 text-orange-600 hover:scale-110 transition-transform"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg></button>
                <div className="mb-2"><span className="text-[10px] bg-orange-100 text-orange-600 px-2 py-0.5 rounded-full font-black uppercase tracking-widest">{q.era}</span></div>
                <h3 className="text-lg font-bold text-gray-900 pr-8">{q.text}</h3>
                <div className="mt-4 p-4 bg-orange-50 rounded-xl"><p className="text-sm font-bold text-orange-900 uppercase tracking-tighter mb-1">सही उत्तर (Correct): {q.options[q.correctAnswer]}</p><p className="text-xs text-orange-800 leading-relaxed italic">{q.explanation}</p></div>
              </div>
            ))}</div>
          </div>
        )}
        {appState === 'DIFFICULTY_SELECT' && (
          <div className="w-full max-w-md space-y-6 animate-fade-in">
            <div className="text-center mb-10"><h2 className="text-4xl font-black text-orange-900 drop-shadow-sm">{t.selectDifficulty}</h2><p className="text-orange-700/60 mt-2">अपनी क्षमतानुसार चुनौती चुनें</p></div>
            <div className="grid grid-cols-1 gap-5">
              {DIFFICULTIES.filter(d => d.code !== Difficulty.CHALLENGE).map((diff) => (
                <button key={diff.code} onClick={() => startQuiz(diff.code)} className={`group relative overflow-hidden p-6 bg-white border-4 border-${diff.color}-50 hover:border-${diff.color}-500 rounded-3xl shadow-lg hover:shadow-2xl transition-all duration-300 text-left`}>
                  <div className="flex justify-between items-center relative z-10">
                    <div><h3 className={`text-2xl font-black text-gray-900 group-hover:text-${diff.color}-600 transition-colors`}>{t[diff.code]}</h3><div className="flex flex-wrap gap-3 mt-2 text-xs font-bold text-gray-400 uppercase tracking-tighter"><span className="flex items-center gap-1">{diff.count} {t.questions}</span><span className="flex items-center gap-1">{diff.time / 60} {t.minutes}</span></div></div>
                  </div>
                </button>
              ))}
            </div>
            <button onClick={() => handleNav('LANDING')} className="w-full py-4 text-gray-400 font-bold hover:text-orange-600 transition tracking-widest text-sm">वपस जाएं (BACK TO HOME)</button>
          </div>
        )}
        {appState === 'QUIZ' && quiz && (
          <div className="w-full pb-20">
            {loading ? <ThematicLoader /> : quiz.questions.length > 0 && quiz.questions[quiz.currentIndex] ? (
              <div className="space-y-8">
                <div className="w-full bg-orange-100 h-3 rounded-full overflow-hidden shadow-inner border border-orange-200">
                  <div className={`h-full transition-all duration-500 ease-out ${quiz.isDailyMode ? 'bg-indigo-600' : quiz.isExamMode ? 'bg-slate-800' : 'bg-orange-600'}`} style={{ width: `${((quiz.currentIndex + 1) / quiz.totalQuestions) * 100}%` }}></div>
                </div>
                <div className="flex justify-between items-center text-sm font-black text-orange-900">
                  <div className="flex flex-col">
                    <span className={`uppercase tracking-widest text-xs opacity-50 ${quiz.isChallengeMode ? 'text-red-600 font-black opacity-100' : quiz.isDailyMode ? 'text-indigo-600 font-black opacity-100' : quiz.isExamMode ? 'text-slate-800 font-black opacity-100' : ''}`}>
                      {quiz.isChallengeMode ? t.challengeMode : quiz.isDailyMode ? t.dailyQuiz : quiz.isExamMode ? t.examMode : (t[quiz.difficulty] || quiz.difficulty)}
                    </span>
                    <span className="text-lg">{`प्रसंग ${quiz.currentIndex + 1} / ${quiz.totalQuestions}`}</span>
                  </div>
                  {!quiz.isExamMode && (
                    <div className="flex items-center gap-3"><button onClick={() => toggleBookmark(quiz.questions[quiz.currentIndex])} className={`p-2 rounded-full border-2 ${isBookmarked(quiz.questions[quiz.currentIndex].id) ? 'bg-orange-600 border-orange-600 text-white' : 'bg-white border-orange-200 text-orange-600'}`}><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg></button><div className={`${quiz.isDailyMode ? 'bg-indigo-600' : 'bg-orange-600'} text-white px-4 py-1.5 rounded-2xl shadow-md uppercase tracking-tighter`}>{quiz.questions[quiz.currentIndex].era}</div></div>
                  )}
                </div>
                <h2 className="text-3xl md:text-4xl font-black text-gray-900 leading-tight hindi-font">{quiz.questions[quiz.currentIndex].text}</h2>
                <div className="grid grid-cols-1 gap-4">
                  {quiz.questions[quiz.currentIndex].options.map((option, idx) => (
                    <button key={idx} onClick={() => handleAnswer(idx)} disabled={selectedAnswer !== null} className={`group p-5 text-left rounded-3xl border-4 transition-all duration-200 flex items-center ${selectedAnswer === null ? 'border-orange-50 bg-white hover:border-orange-600 hover:shadow-xl' : (idx === quiz.questions[quiz.currentIndex].correctAnswer && !quiz.isExamMode) ? 'border-green-600 bg-green-50 text-green-900 ring-8 ring-green-100' : (selectedAnswer === idx && !quiz.isExamMode) ? 'border-red-600 bg-red-50 text-red-900' : quiz.isExamMode && selectedAnswer === idx ? 'border-slate-800 bg-slate-50 text-slate-900' : 'opacity-40 grayscale'}`}>
                      <span className={`w-10 h-10 rounded-full flex items-center justify-center font-black mr-4 text-lg border-2 ${selectedAnswer === null ? 'bg-orange-50 border-orange-200 text-orange-600 group-hover:bg-orange-600 group-hover:text-white' : (idx === quiz.questions[quiz.currentIndex].correctAnswer && !quiz.isExamMode) ? 'bg-green-600 border-green-600 text-white' : (selectedAnswer === idx && !quiz.isExamMode) ? 'bg-red-600 border-red-600 text-white' : quiz.isExamMode && selectedAnswer === idx ? 'bg-slate-800 border-slate-800 text-white' : 'bg-gray-200 text-gray-400'}`}>{String.fromCharCode(65 + idx)}</span>
                      <span className="text-xl font-bold">{option}</span>
                    </button>
                  ))}
                </div>
                {showExplanation && !quiz.isExamMode && (
                  <div className={`p-8 bg-blue-50 border-4 border-blue-600 rounded-[2.5rem] animate-fade-in shadow-xl`}>
                    <h4 className="font-black text-blue-900 mb-2 uppercase tracking-tighter">इतिहास का सार</h4>
                    <p className="text-blue-800 text-lg leading-relaxed font-medium mb-6">{quiz.questions[quiz.currentIndex].explanation}</p>
                    {quiz.questions[quiz.currentIndex].sources && quiz.questions[quiz.currentIndex].sources!.length > 0 && (
                      <div className="bg-white/60 p-4 rounded-2xl border-2 border-blue-100 mb-6">
                        <h5 className="text-xs font-black text-blue-900 uppercase tracking-[0.2em] mb-3">प्रमाण और संदर्भ</h5>
                        <ul className="space-y-2">{quiz.questions[quiz.currentIndex].sources!.map((source, sIdx) => (<li key={sIdx}><a href={source.uri} target="_blank" rel="noopener noreferrer" className="text-blue-600 hover:text-blue-800 text-sm font-bold flex items-center gap-2">{source.title}</a></li>))}</ul>
                      </div>
                    )}
                    <button onClick={nextQuestion} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-5 rounded-3xl transition text-xl uppercase tracking-widest">{quiz.currentIndex + 1 < quiz.totalQuestions ? t.next : t.finish}</button>
                  </div>
                )}
              </div>
            ) : null}
          </div>
        )}
        {appState === 'RESULT' && quiz && (
          <div className="text-center space-y-10 animate-fade-in w-full py-10 relative">
             {showCopied && <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-gray-800 text-white px-6 py-3 rounded-full shadow-2xl font-bold z-50 animate-bounce">{t.copied}</div>}
             {quiz.isChallengeMode ? (
                <div className="space-y-6">
                  <div className="w-24 h-24 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto shadow-lg"><svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg></div>
                  <h2 className="text-5xl font-black text-gray-900 tracking-tighter uppercase">{t.challengeMode}</h2>
                  <div className="grid grid-cols-2 gap-4 max-w-sm mx-auto">
                    <div className="bg-white p-6 rounded-3xl border-4 border-orange-100 shadow-sm"><span className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">{t.attempted}</span><span className="text-4xl font-black text-orange-600">{quiz.currentIndex}</span></div>
                    <div className="bg-white p-6 rounded-3xl border-4 border-orange-100 shadow-sm"><span className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">{t.score}</span><span className="text-4xl font-black text-green-600">{quiz.score}</span></div>
                  </div>
                </div>
             ) : (
                <>
                  <div className="relative inline-block"><svg className="w-64 h-64 drop-shadow-2xl relative"><circle cx="128" cy="128" r="110" fill="none" stroke="#fed7aa" strokeWidth="18" /><circle cx="128" cy="128" r="110" fill="none" stroke={`${quiz.isDailyMode ? '#4f46e5' : quiz.isExamMode ? '#1e293b' : '#ea580c'}`} strokeWidth="18" strokeDasharray={`${(quiz.score / quiz.totalQuestions) * 691.15} 691.15`} strokeLinecap="round" transform="rotate(-90 128 128)" className="transition-all duration-1000 ease-out" /></svg><div className="absolute inset-0 flex flex-col items-center justify-center"><span className={`text-6xl font-black ${quiz.isDailyMode ? 'text-indigo-600' : quiz.isExamMode ? 'text-slate-900' : 'text-orange-600'}`}>{Math.round((quiz.score / quiz.totalQuestions) * 100)}%</span><span className="text-xs font-black text-gray-500 uppercase tracking-[0.3em] mt-1">{t.score}</span></div></div>
                  <div className="space-y-4">
                    <h3 className="text-5xl font-black text-gray-900 tracking-tighter">{quiz.score === quiz.totalQuestions ? "विजेता! (Legendary)" : quiz.score > quiz.totalQuestions / 2 ? "विजयी भव!" : "प्रयास जारी रखें!"}</h3>
                    <p className={`text-2xl font-bold px-6 py-3 rounded-full inline-block ${quiz.isDailyMode ? 'bg-indigo-100 text-indigo-800' : quiz.isExamMode ? 'bg-slate-100 text-slate-800' : 'bg-orange-100 text-orange-800'}`}>
                      आपने {quiz.isDailyMode ? t.dailyQuiz : (t[quiz.difficulty] || quiz.difficulty)} स्तर पर {quiz.totalQuestions} में से {quiz.score} सही उत्तर दिए।
                    </p>
                    {quiz.isDailyMode && (
                       <div className="mt-4 text-indigo-600 font-black text-xl animate-bounce">
                          🔥 {t.dailyStreak}: {dailyStreak}
                       </div>
                    )}
                  </div>
                </>
             )}
            <div className="flex flex-col gap-4 w-full max-w-lg mx-auto">
              <button onClick={handleShare} className="w-full py-5 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-3xl shadow-xl transition transform hover:scale-105 active:scale-95 flex items-center justify-center gap-3 text-xl uppercase tracking-widest">{t.shareScore}</button>
              <div className="flex flex-col sm:flex-row gap-5">
                <button onClick={() => { handleNav('LANDING'); setQuiz(null); localStorage.removeItem(ACTIVE_QUIZ_KEY); }} className="flex-1 py-5 bg-white border-4 border-orange-600 text-orange-600 font-black rounded-3xl shadow-xl hover:bg-orange-50 transition transform hover:scale-105">मुख्य पृष्ठ (HOME)</button>
                <button onClick={() => { if(quiz.isDailyMode) handleNav('LANDING'); else startQuiz(quiz.difficulty); }} className={`flex-1 py-5 text-white font-black rounded-3xl shadow-xl transition transform hover:scale-105 ${quiz.isChallengeMode ? 'bg-red-600' : quiz.isExamMode ? 'bg-slate-800' : 'bg-orange-600'}`}>{quiz.isDailyMode ? t.finish : t.restart}</button>
              </div>
            </div>
          </div>
        )}
        {appState === 'SETTINGS' && (
          <div className="w-full bg-white p-10 rounded-[3rem] shadow-xl space-y-10 border-4 border-orange-50">
            <div className="flex items-center justify-between border-b-2 border-orange-100 pb-6"><h2 className="text-4xl font-black text-gray-900 tracking-tighter">{t.settings}</h2><button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg></button></div>
            <section className="space-y-6"><h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider"><span>🔊</span>{t.soundEffects}</h3><div className="flex gap-4"><button onClick={() => { setSoundEnabled(true); playSound('nav'); }} className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${soundEnabled ? 'bg-orange-600 text-white' : 'bg-gray-100 text-gray-400'}`}>{t.on}</button><button onClick={() => setSoundEnabled(false)} className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${!soundEnabled ? 'bg-orange-600 text-white' : 'bg-gray-100 text-gray-400'}`}>{t.off}</button></div></section>
            <section className="space-y-6"><h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider"><span>🌐</span>{t.selectLang}</h3><div className="grid grid-cols-2 gap-4">{LANGUAGES.map((lang) => (<button key={lang.code} onClick={() => { setLanguage(lang.code); playSound('nav'); }} className={`p-4 rounded-2xl border-4 transition-all text-lg font-black ${language === lang.code ? 'border-orange-600 bg-orange-50 text-orange-600 shadow-inner' : 'border-gray-50 text-gray-400'}`}>{lang.name}</button>))}</div></section>
          </div>
        )}
      </main>
      <footer className="w-full p-8 text-center">
        <div className="flex items-center justify-center gap-2 text-[10px] font-black text-orange-400 uppercase tracking-widest mb-4">
           <span className="w-2 h-2 bg-green-500 rounded-full"></span>
           Online & Verified by Google Search
        </div>
        <div className="max-w-xs mx-auto h-px bg-orange-100 mb-6"></div>
        <p className="text-gray-400 text-sm font-bold uppercase tracking-[0.4em]">&copy; {new Date().getFullYear()} {APP_NAME}</p>
        <p className="text-orange-900/30 text-[10px] mt-2 font-black tracking-widest">BHARAT VARSHA HISTORY PROJECT</p>
      </footer>
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.tsx';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Language, Question, QuizState, Difficulty, HistoryEntry } from './types';
import { fetchQuestions } from './services/geminiService';
import { AUTHOR_NAME, APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES, DAILY_QUIZ_COUNT } from './constants';

const BOOKMARKS_KEY = 'history_bookmarks';
const HISTORY_KEY = 'quiz_history_data';
const ACTIVE_QUIZ_KEY = 'active_quiz_session';
const DAILY_STATS_KEY = 'daily_stats_v1';

const PRE_QUIZ_FACTS = [
  "सिंधु घाटी सभ्यता दुनिया की सबसे पुरानी शहरी सभ्यताओं में से एक थी।",
  "मौर्य साम्राज्य ने पहली बार लगभग पूरे भारतीय उपमहाद्वीप को एकजुट किया।",
  "प्राचीन नालंदा विश्वविद्यालय में 90 लाख से अधिक पांडुलिपियां थीं।",
  "छत्रपति शिवाजी महाराज को भारतीय नौसेना का जनक माना जाता है।",
  "सम्राट अशोक के शिलालेख शांति और अहिंसा का संदेश देते हैं।",
  "गुप्त काल को भारतीय इतिहास का 'स्वर्ण युग' कहा जाता है।",
  "रानी लक्ष्मीबाई ने 1857 के स्वतंत्रता संग्राम में अदम्य साहस दिखाया।",
  "भारतीय संविधान दुनिया का सबसे बड़ा लिखित संविधान है।"
];

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState | null>(null);
  const [bookmarks, setBookmarks] = useState<Question[]>([]);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [showCopied, setShowCopied] = useState(false);

  // Countdown Logic
  const [preQuizTimer, setPreQuizTimer] = useState(10);
  const [randomFact, setRandomFact] = useState("");

  // Daily Stats
  const [dailyStreak, setDailyStreak] = useState(0);
  const [lastDailyDate, setLastDailyDate] = useState<string | null>(null);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);

  const t = TRANSLATIONS[language] || TRANSLATIONS[Language.ENGLISH];

  // Load persistence on init
  useEffect(() => {
    const savedBookmarks = localStorage.getItem(BOOKMARKS_KEY);
    if (savedBookmarks) {
      try { setBookmarks(JSON.parse(savedBookmarks)); } catch (e) { console.error(e); }
    }

    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) {
      try { setHistory(JSON.parse(savedHistory)); } catch (e) { console.error(e); }
    }

    const savedStats = localStorage.getItem(DAILY_STATS_KEY);
    if (savedStats) {
      try {
        const stats = JSON.parse(savedStats);
        setDailyStreak(stats.streak || 0);
        setLastDailyDate(stats.lastDate || null);

        if (stats.lastDate) {
          const last = new Date(stats.lastDate);
          last.setHours(0, 0, 0, 0);
          const today = new Date();
          today.setHours(0, 0, 0, 0);

          const yesterday = new Date(today);
          yesterday.setDate(yesterday.getDate() - 1);

          if (last.getTime() < yesterday.getTime()) {
             setDailyStreak(0);
          }
        }
      } catch (e) { console.error(e); }
    }

    const savedActiveQuiz = localStorage.getItem(ACTIVE_QUIZ_KEY);
    if (savedActiveQuiz) {
      try { 
        const parsed = JSON.parse(savedActiveQuiz);
        if (parsed && !parsed.isComplete) {
          setQuiz(parsed);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  // Countdown timer effect
  useEffect(() => {
    if (appState === 'COUNTDOWN' && preQuizTimer > 0) {
      const timer = setTimeout(() => {
        setPreQuizTimer(preQuizTimer - 1);
        if (preQuizTimer % 2 === 0) playSound('nav');
      }, 1000);
      return () => clearTimeout(timer);
    } else if (appState === 'COUNTDOWN' && preQuizTimer === 0) {
      setAppState('QUIZ');
    }
  }, [appState, preQuizTimer]);

  // Save persistence on change
  useEffect(() => {
    localStorage.setItem(BOOKMARKS_KEY, JSON.stringify(bookmarks));
  }, [bookmarks]);

  useEffect(() => {
    localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    if (quiz) {
      localStorage.setItem(ACTIVE_QUIZ_KEY, JSON.stringify(quiz));
    }
  }, [quiz]);

  useEffect(() => {
    localStorage.setItem(DAILY_STATS_KEY, JSON.stringify({ streak: dailyStreak, lastDate: lastDailyDate }));
  }, [dailyStreak, lastDailyDate]);

  // Timer Effect
  useEffect(() => {
    if (appState === 'QUIZ' && quiz && quiz.timeRemaining > 0 && !loading) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (!prev) return null;
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [appState, loading, quiz?.timeRemaining]);

  const handleTimeUp = () => {
    if (!quiz) return;
    playSound('incorrect');
    const attempted = quiz.isChallengeMode ? quiz.currentIndex : quiz.currentIndex + 1;
    finishQuiz(attempted);
  };

  const getAudioContext = () => {
    if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    return audioCtxRef.current;
  };

  const playSound = (type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    const ctx = getAudioContext();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    const now = ctx.currentTime;
    if (type === 'correct') {
      osc.type = 'sine'; osc.frequency.setValueAtTime(523.25, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0.1, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now); osc.stop(now + 0.3);
    } else if (type === 'incorrect') {
      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(220, now);
      osc.frequency.linearRampToValueAtTime(110, now + 0.2);
      gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now); osc.stop(now + 0.3);
    } else if (type === 'nav') {
      osc.type = 'sine'; osc.frequency.setValueAtTime(800, now);
      gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
      osc.start(now); osc.stop(now + 0.1);
    }
  };

  const formatTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${h > 0 ? h + ':' : ''}${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const backgroundSync = async (difficulty: Difficulty, target: number, currentLang: Language, existingCount: number, isDaily: boolean = false) => {
    if (syncRef.current) return;
    syncRef.current = true;
    setIsSyncing(true);

    let currentCount = existingCount;
    const BATCH_SIZE = 20; 

    while (currentCount < target && syncRef.current) {
      const remaining = target - currentCount;
      const fetchCount = Math.min(BATCH_SIZE, remaining);
      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, fetchCount, isDaily);
        if (moreQuestions.length === 0) break;
        setQuiz(prev => {
          if (!prev) return null;
          const uniqueNew = moreQuestions.filter(mq => !prev.questions.some(pq => pq.text === mq.text));
          return { ...prev, questions: [...prev.questions, ...uniqueNew] };
        });
        currentCount += moreQuestions.length;
      } catch (err) { break; }
      await new Promise(r => setTimeout(r, 3000));
    }
    setIsSyncing(false);
    syncRef.current = false;
  };

  const triggerCountdown = () => {
    setPreQuizTimer(10);
    setRandomFact(PRE_QUIZ_FACTS[Math.floor(Math.random() * PRE_QUIZ_FACTS.length)]);
    setAppState('COUNTDOWN');
  };

  const startQuiz = async (difficulty: Difficulty, resume = false) => {
    playSound('nav');
    if (resume && quiz) {
      setAppState('QUIZ');
      if (quiz.questions.length < quiz.totalQuestions) {
        backgroundSync(quiz.difficulty, quiz.totalQuestions, language, quiz.questions.length, quiz.isDailyMode);
      }
      return;
    }

    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true);
    syncRef.current = true;

    const initialQuestions = await fetchQuestions(language, difficulty, 10);
    const newQuiz: QuizState = {
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: config.maxSkips,
      isComplete: false,
      difficulty,
      timeRemaining: config.time,
      totalQuestions: config.count,
      isChallengeMode: difficulty === Difficulty.CHALLENGE,
      isExamMode: difficulty === Difficulty.EXAM
    };
    setQuiz(newQuiz);
    setLoading(false);
    triggerCountdown();
    backgroundSync(difficulty, config.count, language, 10);
  };

  const startDailyQuiz = async () => {
    if (isDailyDone) return;
    playSound('nav');
    setLoading(true);
    syncRef.current = true;

    const initialQuestions = await fetchQuestions(language, Difficulty.MEDIUM, 10, true);
    const newQuiz: QuizState = {
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: 10,
      isComplete: false,
      difficulty: Difficulty.MEDIUM,
      timeRemaining: 20 * 60, 
      totalQuestions: DAILY_QUIZ_COUNT,
      isDailyMode: true
    };
    setQuiz(newQuiz);
    setLoading(false);
    triggerCountdown();
    backgroundSync(Difficulty.MEDIUM, DAILY_QUIZ_COUNT, language, 10, true);
  };

  const saveToHistory = (score: number, totalPlayed: number, skipped: number, diff: Difficulty | 'DAILY', isChallenge?: boolean) => {
    const newEntry: HistoryEntry = {
      id: Date.now().toString(),
      difficulty: diff,
      score,
      total: totalPlayed,
      skipped,
      date: new Date().toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }),
      isChallenge
    };
    setHistory(prev => [newEntry, ...prev].slice(0, 50)); 
  };

  const handleAnswer = (index: number) => {
    if (!quiz || selectedAnswer !== null) return;
    setSelectedAnswer(index);

    if (quiz.isExamMode) {
      playSound('nav');
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
        setQuiz(prev => prev ? ({ ...prev, score: prev.score + 1 }) : null);
      }
      setTimeout(() => {
        nextQuestion();
      }, 300);
    } else {
      setShowExplanation(true);
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
        playSound('correct');
        setQuiz(prev => prev ? ({ ...prev, score: prev.score + 1 }) : null);
      } else {
        playSound('incorrect');
      }
    }
  };

  const handleSkip = () => {
    if (!quiz || quiz.skipsRemaining <= 0 || selectedAnswer !== null || quiz.isExamMode) return;
    playSound('nav');
    const isLast = quiz.currentIndex + 1 >= quiz.totalQuestions;
    setQuiz(prev => prev ? ({ ...prev, skipsRemaining: prev.skipsRemaining - 1, skippedCount: prev.skippedCount + 1 }) : null);
    if (isLast) {
      finishQuiz(quiz.totalQuestions);
    } else {
      moveNext();
    }
  };

  const finishQuiz = (attempted?: number) => {
    if (!quiz) return;
    const finalAttempted = attempted ?? (quiz.isChallengeMode ? quiz.currentIndex : quiz.currentIndex + 1);
    const diffLabel = quiz.isDailyMode ? 'DAILY' : quiz.difficulty;

    saveToHistory(quiz.score, finalAttempted, quiz.skippedCount, diffLabel, quiz.isChallengeMode);

    if (quiz.isDailyMode) {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const todayStr = today.toISOString().split('T')[0];

      if (lastDailyDate !== todayStr) {
        const last = lastDailyDate ? new Date(lastDailyDate) : null;
        if (last) last.setHours(0,0,0,0);

        const yesterday = new Date(today);
        yesterday.setDate(yesterday.getDate() - 1);
        yesterday.setHours(0,0,0,0);

        if (!last || last.getTime() === yesterday.getTime()) {
           setDailyStreak(prev => prev + 1);
        } else if (last.getTime() < yesterday.getTime()) {
           setDailyStreak(1);
        }
        setLastDailyDate(todayStr);
      }
    }

    setAppState('RESULT');
    localStorage.removeItem(ACTIVE_QUIZ_KEY);
  };

  const moveNext = () => {
    if (!quiz) return;
    if (quiz.currentIndex + 1 >= quiz.questions.length) {
      setLoading(true);
      const checkBuffer = setInterval(() => {
        setQuiz(prev => {
          if (prev && prev.currentIndex + 1 < prev.questions.length) {
            clearInterval(checkBuffer);
            setLoading(false);
            return { ...prev, currentIndex: prev.currentIndex + 1 };
          }
          return prev;
        });
      }, 500);
    } else {
      setQuiz(prev => prev ? ({ ...prev, currentIndex: prev.currentIndex + 1 }) : null);
    }
  };

  const nextQuestion = () => {
    if (!quiz) return;
    if (!quiz.isExamMode) playSound('nav');
    setSelectedAnswer(null);
    setShowExplanation(false);
    if (quiz.currentIndex + 1 < quiz.totalQuestions) {
      moveNext();
    } else {
      finishQuiz();
    }
  };

  const handleNav = (state: AppState) => {
    playSound('nav');
    setAppState(state);
    if (state !== 'QUIZ' && state !== 'COUNTDOWN') syncRef.current = false;
  };

  const toggleBookmark = (q: Question) => {
    if (quiz?.isExamMode) return;
    playSound('nav');
    setBookmarks(prev => prev.find(b => b.id === q.id) ? prev.filter(b => b.id !== q.id) : [...prev, q]);
  };

  const clearHistory = () => {
    playSound('nav');
    if (window.confirm(t.clearHistory + '?')) setHistory([]);
  };

  const handleShare = async () => {
    if (!quiz) return;
    playSound('nav');
    const total = quiz.isChallengeMode ? quiz.currentIndex : quiz.totalQuestions;
    const diffLabel = quiz.isDailyMode ? t.dailyQuiz : (t[quiz.difficulty] || quiz.difficulty);
    const message = t.shareText(quiz.score, total, diffLabel);
    if (navigator.share) {
      try { await navigator.share({ title: APP_NAME, text: message, url: window.location.href }); } catch (err) { console.error(err); }
    } else {
      try { await navigator.clipboard.writeText(message); setShowCopied(true); setTimeout(() => setShowCopied(false), 2000); } catch (err) { console.error(err); }
    }
  };

  const isBookmarked = (id: string) => bookmarks.some(b => b.id === id);

  const ThematicLoader = () => (
    <div className="flex flex-col items-center justify-center min-h-[400px] w-full max-w-lg mx-auto p-8 space-y-12 animate-fade-in">
      <div className="relative">
        <div className="w-32 h-32 text-orange-600 animate-[spin_10s_linear_infinite] drop-shadow-lg">
          <svg viewBox="0 0 100 100" className="w-full h-full" fill="currentColor">
            <circle cx="50" cy="50" r="48" fill="none" stroke="currentColor" strokeWidth="1" />
            <circle cx="50" cy="50" r="8" fill="currentColor" />
            {[...Array(24)].map((_, i) => (
              <line key={i} x1="50" y1="50" x2={50 + 40 * Math.cos((i * 15 * Math.PI) / 180)} y2={50 + 40 * Math.sin((i * 15 * Math.PI) / 180)} stroke="currentColor" strokeWidth="1.5" />
            ))}
            <circle cx="50" cy="50" r="42" fill="none" stroke="currentColor" strokeWidth="2" />
          </svg>
        </div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-40 h-40 border-4 border-orange-200 rounded-full animate-ping opacity-20"></div>
      </div>
      <div className="w-full space-y-8 text-center">
        <div className="space-y-2">
          <p className="text-3xl font-black text-orange-900 tracking-tighter">
            {quiz && quiz.questions.length < quiz.totalQuestions && quiz.currentIndex >= quiz.questions.length - 1 ? "कालचक्र घूम रहा है..." : "इतिहास के पन्नों को खोजा जा रहा है..."}
          </p>
          <div className="flex items-center justify-center gap-2 text-orange-700/60 font-black text-xs uppercase tracking-widest">
            <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
            {isSyncing ? `प्रमाण एकत्रित हो रहे हैं... (${quiz?.questions.length}/${quiz?.totalQuestions})` : "ज्ञान संचय जारी है..."}
          </div>
        </div>
        <div className="relative w-full h-1 bg-orange-100 rounded-full overflow-hidden">
          <div className="absolute inset-0 bg-gradient-to-r from-orange-400 via-red-500 to-orange-400 w-1/3 animate-[translateX_3s_linear_infinite]"></div>
        </div>
        <div className="flex justify-between text-[10px] font-black text-orange-400 uppercase tracking-tighter px-1"><span>प्राचीन</span><span>मध्यकालीन</span><span>आधुनिक</span></div>
      </div>
      <style>{`@keyframes translateX { 0% { transform: translateX(-100%); } 100% { transform: translateX(300%); } }`}</style>
    </div>
  );

  const isDailyDone = lastDailyDate === new Date().toISOString().split('T')[0];

  return (
    <div className={`min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800 ${quiz?.isChallengeMode && (appState === 'QUIZ' || appState === 'COUNTDOWN') ? 'ring-inset ring-8 ring-red-500/20' : ''}`}>
      <header className={`w-full p-4 flex justify-between items-center text-white shadow-md z-30 sticky top-0 transition-colors ${quiz?.isChallengeMode && (appState === 'QUIZ' || appState === 'COUNTDOWN') ? 'bg-red-600' : quiz?.isExamMode && (appState === 'QUIZ' || appState === 'COUNTDOWN') ? 'bg-slate-800' : 'bg-orange-600'}`}>
        <span className="font-bold text-lg cursor-pointer flex items-center gap-2" onClick={() => handleNav('LANDING')}>
          <span className="bg-white text-orange-600 w-8 h-8 rounded-full flex items-center justify-center font-black">इ</span>
          <span className="hidden xs:inline">{AUTHOR_NAME}</span>
        </span>
        {(appState === 'QUIZ' || appState === 'COUNTDOWN') && quiz && (
          <div className={`flex items-center gap-2 sm:gap-3 px-2 sm:px-3 py-1.5 rounded-full font-mono font-bold text-xs sm:text-sm shadow-inner transition-colors ${quiz.isChallengeMode ? 'bg-black/40' : quiz.isExamMode ? 'bg-white/10' : 'bg-white/20'}`}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            <span className={quiz.timeRemaining < 30 ? 'text-yellow-300 animate-pulse' : ''}>{formatTime(quiz.timeRemaining)}</span>
          </div>
        )}
        <div className="flex gap-1.5 sm:gap-2">
          {dailyStreak > 0 && (
            <div className="flex items-center gap-1 bg-white/20 px-3 py-1 rounded-full text-[10px] font-black">
              🔥 {dailyStreak}
            </div>
          )}
          <button onClick={() => handleNav('HISTORY')} className="bg-white/20 hover:bg-white/30 p-1.5 rounded-full transition"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg></button>
          <button onClick={() => handleNav('BOOKMARKS')} className="bg-white/20 hover:bg-white/30 p-1.5 rounded-full transition relative"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg>{bookmarks.length > 0 && <span className="absolute -top-1 -right-1 bg-white text-orange-600 text-[10px] w-4 h-4 rounded-full flex items-center justify-center font-black">{bookmarks.length}</span>}</button>
          <button onClick={() => handleNav('SETTINGS')} className="p-1.5 hover:bg-white/10 rounded-full transition"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg></button>
        </div>
      </header>
      <main className="flex-1 w-full max-w-2xl px-4 py-8 flex flex-col items-center justify-center">
        {appState === 'LANDING' && (
          <div className="text-center animate-fade-in py-10 w-full">
            <h1 className="text-6xl md:text-9xl font-black text-orange-600 mb-2 hindi-font tracking-tighter drop-shadow-xl select-none">{INTRO_MAIN}</h1>
            <p className="text-xl md:text-3xl text-orange-800 font-bold mb-12 italic opacity-80">"{INTRO_SUB}"</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-w-2xl mx-auto mb-12">
              <div className={`p-6 rounded-[2.5rem] border-4 shadow-xl text-left flex flex-col justify-between h-56 transition-all transform hover:scale-[1.02] ${isDailyDone ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-orange-100'}`}>
                <div>
                  <div className="flex justify-between items-start">
                    <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${isDailyDone ? 'bg-indigo-600 text-white' : 'bg-orange-100 text-orange-600'}`}>
                      {t.dailyQuiz}
                    </span>
                    <span className="text-2xl">🔥 {dailyStreak}</span>
                  </div>
                  <h3 className="text-2xl font-black text-gray-900 mt-4">{t.dailyGoal}</h3>
                  <p className="text-xs text-gray-400 font-bold mt-1">{isDailyDone ? t.dailyDone : "चुनौती स्वीकार करें"}</p>
                </div>
                {!isDailyDone ? (
                   <button onClick={startDailyQuiz} className="w-full py-3 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-2xl shadow-lg transition transform active:scale-95 uppercase tracking-widest text-sm">
                      {t.start}
                   </button>
                ) : (
                  <div className="flex items-center gap-2 text-indigo-600 font-black">
                     <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 24 24" fill="currentColor"><path fillRule="evenodd" d="M2.25 12c0-5.385 4.365-9.75 9.75-9.75s9.75 4.365 9.75 9.75-4.365 9.75-9.75 9.75S2.25 17.385 2.25 12Zm13.36-1.814a.75.75 0 1 0-1.22-.872l-3.236 4.53L9.53 12.22a.75.75 0 0 0-1.06 1.06l2.25 2.25a.75.75 0 0 0 1.14-.094l3.74-5.24Z" clipRule="evenodd" /></svg>
                     {t.dailyDone}
                  </div>
                )}
              </div>

              <div className="p-6 rounded-[2.5rem] border-4 border-slate-100 bg-slate-900 shadow-xl text-left flex flex-col justify-between h-56 transition-all transform hover:scale-[1.02]">
                 <div>
                    <span className="text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full bg-slate-700 text-white">{t.examMode}</span>
                    <h3 className="text-2xl font-black text-white mt-4">{t[Difficulty.EXAM]}</h3>
                    <p className="text-xs text-slate-400 font-bold mt-1">{t.finalResultsOnly}</p>
                 </div>
                 <button onClick={() => startQuiz(Difficulty.EXAM)} className="w-full py-3 bg-white text-slate-900 font-black rounded-2xl shadow-lg transition transform active:scale-95 uppercase tracking-widest text-sm">
                    {t.start}
                 </button>
              </div>
            </div>

            <div className="space-y-4 max-w-sm mx-auto">
              {quiz && !quiz.isComplete && (
                <button onClick={() => startQuiz(quiz.difficulty, true)} className="w-full py-5 px-8 bg-indigo-600 hover:bg-indigo-700 text-white font-black text-xl rounded-3xl shadow-xl transform hover:scale-105 transition flex items-center justify-center gap-3">
                   {t.continue} ({t[quiz.difficulty] || quiz.difficulty})
                </button>
              )}
              <button onClick={() => handleNav('DIFFICULTY_SELECT')} className="w-full py-5 px-8 bg-orange-600 hover:bg-orange-700 text-white font-black text-2xl rounded-3xl shadow-2xl transform hover:scale-105 active:scale-95 transition-all duration-200 uppercase tracking-widest">{t.start}</button>

              <div className="grid grid-cols-2 gap-4">
                <button onClick={() => handleNav('BOOKMARKS')} className="w-full py-3 px-2 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition-all flex items-center justify-center gap-2 text-sm"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-orange-600" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg>{t.bookmarks}</button>
                <button onClick={() => handleNav('HISTORY')} className="w-full py-3 px-2 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition-all flex items-center justify-center gap-2 text-sm"><svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 text-orange-600" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>{t.history}</button>
              </div>
            </div>
          </div>
        )}

        {appState === 'COUNTDOWN' && (
          <div className="flex flex-col items-center justify-center text-center space-y-8 animate-fade-in w-full max-w-lg mx-auto py-20 px-6">
            <div className="relative">
              <svg className="w-64 h-64 transform -rotate-90">
                <circle cx="128" cy="128" r="110" fill="none" stroke={quiz?.isExamMode ? "#334155" : "#fed7aa"} strokeWidth="10" />
                <circle cx="128" cy="128" r="110" fill="none" stroke={quiz?.isExamMode ? "#f8fafc" : "#ea580c"} strokeWidth="10" strokeDasharray="691.15" strokeDashoffset={691.15 - (preQuizTimer / 10) * 691.15} strokeLinecap="round" className="transition-all duration-1000 linear" />
              </svg>
              <div className="absolute inset-0 flex items-center justify-center">
                <span className={`text-8xl font-black ${quiz?.isExamMode ? 'text-slate-800' : 'text-orange-600'} animate-pulse`}>{preQuizTimer}</span>
              </div>
            </div>
            <div className="space-y-4">
              <h2 className={`text-4xl font-black ${quiz?.isExamMode ? 'text-slate-900' : 'text-orange-900'} tracking-tighter uppercase`}>तैयार हो जाइए!</h2>
              <div className={`p-8 rounded-[2.5rem] border-4 shadow-xl ${quiz?.isExamMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-orange-100 text-gray-800'}`}>
                <p className={`text-xs font-black uppercase tracking-widest mb-2 ${quiz?.isExamMode ? 'text-slate-400' : 'text-orange-400'}`}>क्या आप जानते हैं?</p>
                <p className="text-xl font-bold leading-relaxed italic">"{randomFact}"</p>
              </div>
            </div>
            <p className={`${quiz?.isExamMode ? 'text-slate-500' : 'text-orange-700/60'} font-black animate-bounce`}>प्रश्नोत्तरी बस शुरू होने वाली है...</p>
          </div>
        )}

        {appState === 'HISTORY' && (
          <div className="w-full space-y-6 animate-fade-in pb-10">
            <div className="flex items-center justify-between"><h2 className="text-3xl font-black text-orange-900">{t.history}</h2><div className="flex items-center gap-2">{history.length > 0 && <button onClick={clearHistory} className="p-2 text-red-500 hover:bg-red-50 rounded-full transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" /></svg></button>}<button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg></button></div></div>
            <div className="space-y-4">{history.length === 0 ? <div className="text-center p-20 bg-white border-4 border-dashed border-orange-100 rounded-[3rem] text-xl text-gray-400 font-medium">{t.noHistory}</div> : history.map((entry) => (
              <div key={entry.id} className="bg-white p-5 rounded-3xl shadow-lg border-2 border-orange-50 flex items-center justify-between">
                <div className="space-y-1">
                  <div className="flex items-center gap-2">
                    <span className={`text-[10px] px-2 py-0.5 rounded-full font-black uppercase tracking-widest ${entry.difficulty === 'DAILY' ? 'bg-indigo-100 text-indigo-600' : entry.difficulty === Difficulty.EXAM ? 'bg-slate-200 text-slate-700' : entry.difficulty === Difficulty.CHALLENGE ? 'bg-red-100 text-red-600' : entry.difficulty === Difficulty.HARD ? 'bg-rose-100 text-rose-600' : entry.difficulty === Difficulty.MEDIUM ? 'bg-blue-100 text-blue-600' : 'bg-emerald-100 text-emerald-600'}`}>
                      {entry.difficulty === 'DAILY' ? t.dailyQuiz : (t[entry.difficulty as Difficulty] || entry.difficulty)}
                    </span>
                    <span className="text-xs text-gray-400 font-medium">{entry.date}</span>
                  </div>
                  <h3 className="text-lg font-bold text-gray-900">{entry.score}/{entry.total} {entry.isChallenge && <span className="text-xs bg-red-50 text-red-600 px-2 py-0.5 rounded ml-1">CHALLENGE</span>}</h3>
                </div>
                <div className="w-12 h-12 rounded-full border-4 border-orange-100 flex items-center justify-center font-black text-orange-600">{Math.round((entry.score / entry.total) * 100)}%</div>
              </div>
            ))}</div>
          </div>
        )}

        {appState === 'BOOKMARKS' && (
          <div className="w-full space-y-6 animate-fade-in pb-10">
            <div className="flex items-center justify-between"><h2 className="text-3xl font-black text-orange-900">{t.savedQuestions}</h2><button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg></button></div>
            <div className="space-y-4">{bookmarks.length === 0 ? <div className="text-center p-20 bg-white border-4 border-dashed border-orange-100 rounded-[3rem] text-xl text-gray-400 font-medium">{t.noBookmarks}</div> : bookmarks.map((q) => (
              <div key={q.id} className="bg-white p-6 rounded-3xl shadow-lg border-2 border-orange-50 relative group">
                <button onClick={() => toggleBookmark(q)} className="absolute top-4 right-4 text-orange-600 hover:scale-110 transition-transform"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg></button>
                <div className="mb-2"><span className="text-[10px] bg-orange-100 text-orange-600 px-2 py-0.5 rounded-full font-black uppercase tracking-widest">{q.era}</span></div>
                <h3 className="text-lg font-bold text-gray-900 pr-8">{q.text}</h3>
                <div className="mt-4 p-4 bg-orange-50 rounded-xl"><p className="text-sm font-bold text-orange-900 uppercase tracking-tighter mb-1">सही उत्तर (Correct): {q.options[q.correctAnswer]}</p><p className="text-xs text-orange-800 leading-relaxed italic">{q.explanation}</p></div>
              </div>
            ))}</div>
          </div>
        )}

        {appState === 'DIFFICULTY_SELECT' && (
          <div className="w-full max-w-md space-y-6 animate-fade-in">
            <div className="text-center mb-10"><h2 className="text-4xl font-black text-orange-900 drop-shadow-sm">{t.selectDifficulty}</h2><p className="text-orange-700/60 mt-2">अपनी क्षमतानुसार चुनौती चुनें</p></div>
            <div className="grid grid-cols-1 gap-5">
              {DIFFICULTIES.filter(d => d.code !== Difficulty.CHALLENGE && d.code !== Difficulty.EXAM).map((diff) => (
                <button key={diff.code} onClick={() => startQuiz(diff.code)} className={`group relative overflow-hidden p-6 bg-white border-4 border-${diff.color}-50 hover:border-${diff.color}-500 rounded-3xl shadow-lg hover:shadow-2xl transition-all duration-300 text-left`}>
                  <div className="flex justify-between items-center relative z-10">
                    <div><h3 className={`text-2xl font-black text-gray-900 group-hover:text-${diff.color}-600 transition-colors`}>{t[diff.code]}</h3><div className="flex flex-wrap gap-3 mt-2 text-xs font-bold text-gray-400 uppercase tracking-tighter"><span className="flex items-center gap-1">{diff.count} {t.questions}</span><span className="flex items-center gap-1">{diff.time / 60} {t.minutes}</span></div></div>
                  </div>
                </button>
              ))}
            </div>
            <button onClick={() => handleNav('LANDING')} className="w-full py-4 text-gray-400 font-bold hover:text-orange-600 transition tracking-widest text-sm">वपस जाएं (BACK TO HOME)</button>
          </div>
        )}

        {appState === 'QUIZ' && quiz && (
          <div className="w-full pb-20">
            {loading ? <ThematicLoader /> : quiz.questions.length > 0 && quiz.questions[quiz.currentIndex] ? (
              <div className="space-y-8">
                <div className="w-full bg-orange-100 h-3 rounded-full overflow-hidden shadow-inner border border-orange-200">
                  <div className={`h-full transition-all duration-500 ease-out ${quiz.isDailyMode ? 'bg-indigo-600' : quiz.isExamMode ? 'bg-slate-800' : 'bg-orange-600'}`} style={{ width: `${((quiz.currentIndex + 1) / quiz.totalQuestions) * 100}%` }}></div>
                </div>
                <div className="flex justify-between items-center text-sm font-black text-orange-900">
                  <div className="flex flex-col">
                    <span className={`uppercase tracking-widest text-xs opacity-50 ${quiz.isChallengeMode ? 'text-red-600 font-black opacity-100' : quiz.isDailyMode ? 'text-indigo-600 font-black opacity-100' : quiz.isExamMode ? 'text-slate-800 font-black opacity-100' : ''}`}>
                      {quiz.isChallengeMode ? t.challengeMode : quiz.isDailyMode ? t.dailyQuiz : quiz.isExamMode ? t.examMode : (t[quiz.difficulty] || quiz.difficulty)}
                    </span>
                    <span className="text-lg">{`प्रसंग ${quiz.currentIndex + 1} / ${quiz.totalQuestions}`}</span>
                  </div>
                  {!quiz.isExamMode && (
                    <div className="flex items-center gap-3"><button onClick={() => toggleBookmark(quiz.questions[quiz.currentIndex])} className={`p-2 rounded-full border-2 ${isBookmarked(quiz.questions[quiz.currentIndex].id) ? 'bg-orange-600 border-orange-600 text-white' : 'bg-white border-orange-200 text-orange-600'}`}><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg></button><div className={`${quiz.isDailyMode ? 'bg-indigo-600' : 'bg-orange-600'} text-white px-4 py-1.5 rounded-2xl shadow-md uppercase tracking-tighter`}>{quiz.questions[quiz.currentIndex].era}</div></div>
                  )}
                </div>
                <h2 className="text-3xl md:text-4xl font-black text-gray-900 leading-tight hindi-font">{quiz.questions[quiz.currentIndex].text}</h2>
                <div className="grid grid-cols-1 gap-4">
                  {quiz.questions[quiz.currentIndex].options.map((option, idx) => (
                    <button key={idx} onClick={() => handleAnswer(idx)} disabled={selectedAnswer !== null} className={`group p-5 text-left rounded-3xl border-4 transition-all duration-200 flex items-center ${selectedAnswer === null ? 'border-orange-50 bg-white hover:border-orange-600 hover:shadow-xl' : (idx === quiz.questions[quiz.currentIndex].correctAnswer && !quiz.isExamMode) ? 'border-green-600 bg-green-50 text-green-900 ring-8 ring-green-100' : (selectedAnswer === idx && !quiz.isExamMode) ? 'border-red-600 bg-red-50 text-red-900' : quiz.isExamMode && selectedAnswer === idx ? 'border-slate-800 bg-slate-50 text-slate-900' : 'opacity-40 grayscale'}`}>
                      <span className={`w-10 h-10 rounded-full flex items-center justify-center font-black mr-4 text-lg border-2 ${selectedAnswer === null ? 'bg-orange-50 border-orange-200 text-orange-600 group-hover:bg-orange-600 group-hover:text-white' : (idx === quiz.questions[quiz.currentIndex].correctAnswer && !quiz.isExamMode) ? 'bg-green-600 border-green-600 text-white' : (selectedAnswer === idx && !quiz.isExamMode) ? 'bg-red-600 border-red-600 text-white' : quiz.isExamMode && selectedAnswer === idx ? 'bg-slate-800 border-slate-800 text-white' : 'bg-gray-200 text-gray-400'}`}>{String.fromCharCode(65 + idx)}</span>
                      <span className="text-xl font-bold">{option}</span>
                    </button>
                  ))}
                </div>
                {showExplanation && !quiz.isExamMode && (
                  <div className={`p-8 bg-blue-50 border-4 border-blue-600 rounded-[2.5rem] animate-fade-in shadow-xl`}>
                    <h4 className="font-black text-blue-900 mb-2 uppercase tracking-tighter">इतिहास का सार</h4>
                    <p className="text-blue-800 text-lg leading-relaxed font-medium mb-6">{quiz.questions[quiz.currentIndex].explanation}</p>
                    {quiz.questions[quiz.currentIndex].sources && quiz.questions[quiz.currentIndex].sources!.length > 0 && (
                      <div className="bg-white/60 p-4 rounded-2xl border-2 border-blue-100 mb-6">
                        <h5 className="text-xs font-black text-blue-900 uppercase tracking-[0.2em] mb-3">प्रमाण और संदर्भ</h5>
                        <ul className="space-y-2">{quiz.questions[quiz.currentIndex].sources!.map((source, sIdx) => (<li key={sIdx}><a href={source.uri} target="_blank" rel="noopener noreferrer" className="text-blue-600 hover:text-blue-800 text-sm font-bold flex items-center gap-2">{source.title}</a></li>))}</ul>
                      </div>
                    )}
                    <button onClick={nextQuestion} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-5 rounded-3xl transition text-xl uppercase tracking-widest">{quiz.currentIndex + 1 < quiz.totalQuestions ? t.next : t.finish}</button>
                  </div>
                )}
              </div>
            ) : null}
          </div>
        )}

        {appState === 'RESULT' && quiz && (
          <div className="text-center space-y-10 animate-fade-in w-full py-10 relative">
             {showCopied && <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-gray-800 text-white px-6 py-3 rounded-full shadow-2xl font-bold z-50 animate-bounce">{t.copied}</div>}
             {quiz.isChallengeMode ? (
                <div className="space-y-6">
                  <div className="w-24 h-24 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto shadow-lg"><svg xmlns="http://www.w3.org/2000/svg" className="h-12 w-12" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M13 10V3L4 14h7v7l9-11h-7z" /></svg></div>
                  <h2 className="text-5xl font-black text-gray-900 tracking-tighter uppercase">{t.challengeMode}</h2>
                  <div className="grid grid-cols-2 gap-4 max-w-sm mx-auto">
                    <div className="bg-white p-6 rounded-3xl border-4 border-orange-100 shadow-sm"><span className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">{t.attempted}</span><span className="text-4xl font-black text-orange-600">{quiz.currentIndex}</span></div>
                    <div className="bg-white p-6 rounded-3xl border-4 border-orange-100 shadow-sm"><span className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">{t.score}</span><span className="text-4xl font-black text-green-600">{quiz.score}</span></div>
                  </div>
                </div>
             ) : (
                <>
                  <div className="relative inline-block"><svg className="w-64 h-64 drop-shadow-2xl relative"><circle cx="128" cy="128" r="110" fill="none" stroke="#fed7aa" strokeWidth="18" /><circle cx="128" cy="128" r="110" fill="none" stroke={`${quiz.isDailyMode ? '#4f46e5' : quiz.isExamMode ? '#1e293b' : '#ea580c'}`} strokeWidth="18" strokeDasharray={`${(quiz.score / quiz.totalQuestions) * 691.15} 691.15`} strokeLinecap="round" transform="rotate(-90 128 128)" className="transition-all duration-1000 ease-out" /></svg><div className="absolute inset-0 flex flex-col items-center justify-center"><span className={`text-6xl font-black ${quiz.isDailyMode ? 'text-indigo-600' : quiz.isExamMode ? 'text-slate-900' : 'text-orange-600'}`}>{Math.round((quiz.score / quiz.totalQuestions) * 100)}%</span><span className="text-xs font-black text-gray-500 uppercase tracking-[0.3em] mt-1">{t.score}</span></div></div>
                  <div className="space-y-4">
                    <h3 className="text-5xl font-black text-gray-900 tracking-tighter">{quiz.score === quiz.totalQuestions ? "विजेता! (Legendary)" : quiz.score > quiz.totalQuestions / 2 ? "विजयी भव!" : "प्रयास जारी रखें!"}</h3>
                    <p className={`text-2xl font-bold px-6 py-3 rounded-full inline-block ${quiz.isDailyMode ? 'bg-indigo-100 text-indigo-800' : quiz.isExamMode ? 'bg-slate-100 text-slate-800' : 'bg-orange-100 text-orange-800'}`}>
                      आपने {quiz.isDailyMode ? t.dailyQuiz : (t[quiz.difficulty] || quiz.difficulty)} स्तर पर {quiz.totalQuestions} में से {quiz.score} सही उत्तर दिए।
                    </p>
                    {quiz.isDailyMode && (
                       <div className="mt-4 text-indigo-600 font-black text-xl animate-bounce">
                          🔥 {t.dailyStreak}: {dailyStreak}
                       </div>
                    )}
                  </div>
                </>
             )}
            <div className="flex flex-col gap-4 w-full max-w-lg mx-auto">
              <button onClick={handleShare} className="w-full py-5 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-3xl shadow-xl transition transform hover:scale-105 active:scale-95 flex items-center justify-center gap-3 text-xl uppercase tracking-widest">{t.shareScore}</button>
              <div className="flex flex-col sm:flex-row gap-5">
                <button onClick={() => { handleNav('LANDING'); setQuiz(null); localStorage.removeItem(ACTIVE_QUIZ_KEY); }} className="flex-1 py-5 bg-white border-4 border-orange-600 text-orange-600 font-black rounded-3xl shadow-xl hover:bg-orange-50 transition transform hover:scale-105">मुख्य पृष्ठ (HOME)</button>
                <button onClick={() => { if(quiz.isDailyMode) handleNav('LANDING'); else startQuiz(quiz.difficulty); }} className={`flex-1 py-5 text-white font-black rounded-3xl shadow-xl transition transform hover:scale-105 ${quiz.isChallengeMode ? 'bg-red-600' : quiz.isExamMode ? 'bg-slate-800' : 'bg-orange-600'}`}>{quiz.isDailyMode ? t.finish : t.restart}</button>
              </div>
            </div>
          </div>
        )}

        {appState === 'SETTINGS' && (
          <div className="w-full bg-white p-10 rounded-[3rem] shadow-xl space-y-10 border-4 border-orange-50">
            <div className="flex items-center justify-between border-b-2 border-orange-100 pb-6"><h2 className="text-4xl font-black text-gray-900 tracking-tighter">{t.settings}</h2><button onClick={() => handleNav('LANDING')} className="bg-orange-100 p-2 rounded-full text-orange-600 hover:bg-orange-600 hover:text-white transition-colors"><svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg></button></div>
            <section className="space-y-6"><h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider"><span>🔊</span>{t.soundEffects}</h3><div className="flex gap-4"><button onClick={() => { setSoundEnabled(true); playSound('nav'); }} className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${soundEnabled ? 'bg-orange-600 text-white' : 'bg-gray-100 text-gray-400'}`}>{t.on}</button><button onClick={() => setSoundEnabled(false)} className={`flex-1 py-5 rounded-3xl font-black text-xl transition-all shadow-md ${!soundEnabled ? 'bg-orange-600 text-white' : 'bg-gray-100 text-gray-400'}`}>{t.off}</button></div></section>
            <section className="space-y-6"><h3 className="text-xl font-black text-orange-900 flex items-center gap-3 uppercase tracking-wider"><span>🌐</span>{t.selectLang}</h3><div className="grid grid-cols-2 gap-4">{LANGUAGES.map((lang) => (<button key={lang.code} onClick={() => { setLanguage(lang.code); playSound('nav'); }} className={`p-4 rounded-2xl border-4 transition-all text-lg font-black ${language === lang.code ? 'border-orange-600 bg-orange-50 text-orange-600 shadow-inner' : 'border-gray-50 text-gray-400'}`}>{lang.name}</button>))}</div></section>
          </div>
        )}
      </main>
      <footer className="w-full p-8 text-center">
        <div className="flex items-center justify-center gap-2 text-[10px] font-black text-orange-400 uppercase tracking-widest mb-4">
           <span className="w-2 h-2 bg-green-500 rounded-full"></span>
           Online & Verified by Google Search
        </div>
        <div className="max-w-xs mx-auto h-px bg-orange-100 mb-6"></div>
        <p className="text-gray-400 text-sm font-bold uppercase tracking-[0.4em]">&copy; {new Date().getFullYear()} {APP_NAME}</p>
        <p className="text-orange-900/30 text-[10px] mt-2 font-black tracking-widest">BHARAT VARSHA HISTORY PROJECT</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { AppState, Language, Question, QuizState, Difficulty, HistoryEntry } from './types';
import { fetchQuestions } from './services/geminiService';
import { AUTHOR_NAME, APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES, DAILY_QUIZ_COUNT } from './constants';

const BOOKMARKS_KEY = 'history_bookmarks';
const HISTORY_KEY = 'quiz_history_data';
const ACTIVE_QUIZ_KEY = 'active_quiz_session';
const DAILY_STATS_KEY = 'daily_stats_v1';

const PRE_QUIZ_FACTS = [
  "सिंधु घाटी सभ्यता दुनिया की सबसे पुरानी शहरी सभ्यताओं में से एक थी।",
  "मौर्य साम्राज्य ने पहली बार लगभग पूरे भारतीय उपमहाद्वीप को एकजुट किया।",
  "प्राचीन नालंदा विश्वविद्यालय में 90 लाख से अधिक पांडुलिपियां थीं।",
  "छत्रपति शिवाजी महाराज को भारतीय नौसेना का जनक माना जाता है।",
  "सम्राट अशोक के शिलालेख शांति और अहिंसा का संदेश देते हैं।",
  "गुप्त काल को भारतीय इतिहास का 'स्वर्ण युग' कहा जाता है।",
  "रानी लक्ष्मीबाई ने 1857 के स्वतंत्रता संग्राम में अदम्य साहस दिखाया।",
  "भारतीय संविधान दुनिया का सबसे बड़ा लिखित संविधान है।"
];

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState | null>(null);
  const [bookmarks, setBookmarks] = useState<Question[]>([]);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [showCopied, setShowCopied] = useState(false);

  // Countdown Logic
  const [preQuizTimer, setPreQuizTimer] = useState(10);
  const [randomFact, setRandomFact] = useState("");

  // Daily Stats
  const [dailyStreak, setDailyStreak] = useState(0);
  const [lastDailyDate, setLastDailyDate] = useState<string | null>(null);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);

  const t = TRANSLATIONS[language] || TRANSLATIONS[Language.ENGLISH];

  // Load persistence on init
  useEffect(() => {
    const savedBookmarks = localStorage.getItem(BOOKMARKS_KEY);
    if (savedBookmarks) {
      try { setBookmarks(JSON.parse(savedBookmarks)); } catch (e) { console.error(e); }
    }

    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) {
      try { setHistory(JSON.parse(savedHistory)); } catch (e) { console.error(e); }
    }

    const savedStats = localStorage.getItem(DAILY_STATS_KEY);
    if (savedStats) {
      try {
        const stats = JSON.parse(savedStats);
        setDailyStreak(stats.streak || 0);
        setLastDailyDate(stats.lastDate || null);

        if (stats.lastDate) {
          const last = new Date(stats.lastDate);
          last.setHours(0, 0, 0, 0);
          const today = new Date();
          today.setHours(0, 0, 0, 0);

          const yesterday = new Date(today);
          yesterday.setDate(yesterday.getDate() - 1);

          if (last.getTime() < yesterday.getTime()) {
             setDailyStreak(0);
          }
        }
      } catch (e) { console.error(e); }
    }

    const savedActiveQuiz = localStorage.getItem(ACTIVE_QUIZ_KEY);
    if (savedActiveQuiz) {
      try { 
        const parsed = JSON.parse(savedActiveQuiz);
        if (parsed && !parsed.isComplete) {
          setQuiz(parsed);
        }
      } catch (e) { console.error(e); }
    }
  }, []);

  // Countdown timer effect
  useEffect(() => {
    if (appState === 'COUNTDOWN' && preQuizTimer > 0) {
      const timer = setTimeout(() => {
        setPreQuizTimer(preQuizTimer - 1);
        if (preQuizTimer % 2 === 0) playSound('nav');
      }, 1000);
      return () => clearTimeout(timer);
    } else if (appState === 'COUNTDOWN' && preQuizTimer === 0) {
      setAppState('QUIZ');
    }
  }, [appState, preQuizTimer]);

  // Save persistence on change
  useEffect(() => {
    localStorage.setItem(BOOKMARKS_KEY, JSON.stringify(bookmarks));
  }, [bookmarks]);

  useEffect(() => {
    localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    if (quiz) {
      localStorage.setItem(ACTIVE_QUIZ_KEY, JSON.stringify(quiz));
    }
  }, [quiz]);

  useEffect(() => {
    localStorage.setItem(DAILY_STATS_KEY, JSON.stringify({ streak: dailyStreak, lastDate: lastDailyDate }));
  }, [dailyStreak, lastDailyDate]);

  // Timer Effect
  useEffect(() => {
    if (appState === 'QUIZ' && quiz && quiz.timeRemaining > 0 && !loading) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (!prev) return null;
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [appState, loading, quiz?.timeRemaining]);

  const handleTimeUp = () => {
    if (!quiz) return;
    playSound('incorrect');
    const attempted = quiz.isChallengeMode ? quiz.currentIndex : quiz.currentIndex + 1;
    finishQuiz(attempted);
  };

  const getAudioContext = () => {
    if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    return audioCtxRef.current;
  };

  const playSound = (type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    const ctx = getAudioContext();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    const now = ctx.currentTime;
    if (type === 'correct') {
      osc.type = 'sine'; osc.frequency.setValueAtTime(523.25, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
      gain.gain.setValueAtTime(0.1, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now); osc.stop(now + 0.3);
    } else if (type === 'incorrect') {
      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(220, now);
      osc.frequency.linearRampToValueAtTime(110, now + 0.2);
      gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.3);
      osc.start(now); osc.stop(now + 0.3);
    } else if (type === 'nav') {
      osc.type = 'sine'; osc.frequency.setValueAtTime(800, now);
      gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.01, now + 0.1);
      osc.start(now); osc.stop(now + 0.1);
    }
  };

  const formatTime = (seconds: number) => {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${h > 0 ? h + ':' : ''}${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  };

  const backgroundSync = async (difficulty: Difficulty, target: number, currentLang: Language, existingCount: number, isDaily: boolean = false) => {
    if (syncRef.current) return;
    syncRef.current = true;
    setIsSyncing(true);

    let currentCount = existingCount;
    const BATCH_SIZE = 20; 

    while (currentCount < target && syncRef.current) {
      const remaining = target - currentCount;
      const fetchCount = Math.min(BATCH_SIZE, remaining);
      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, fetchCount, isDaily);
        if (moreQuestions.length === 0) break;
        setQuiz(prev => {
          if (!prev) return null;
          const uniqueNew = moreQuestions.filter(mq => !prev.questions.some(pq => pq.text === mq.text));
          return { ...prev, questions: [...prev.questions, ...uniqueNew] };
        });
        currentCount += moreQuestions.length;
      } catch (err) { break; }
      await new Promise(r => setTimeout(r, 3000));
    }
    setIsSyncing(false);
    syncRef.current = false;
  };

  const triggerCountdown = () => {
    setPreQuizTimer(10);
    setRandomFact(PRE_QUIZ_FACTS[Math.floor(Math.random() * PRE_QUIZ_FACTS.length)]);
    setAppState('COUNTDOWN');
  };

  const startQuiz = async (difficulty: Difficulty, resume = false) => {
    playSound('nav');
    if (resume && quiz) {
      setAppState('QUIZ');
      if (quiz.questions.length < quiz.totalQuestions) {
        backgroundSync(quiz.difficulty, quiz.totalQuestions, language, quiz.questions.length, quiz.isDailyMode);
      }
      return;
    }

    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true);
    syncRef.current = true;

    const initialQuestions = await fetchQuestions(language, difficulty, 10);
    const newQuiz: QuizState = {
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: config.maxSkips,
      isComplete: false,
      difficulty,
      timeRemaining: config.time,
      totalQuestions: config.count,
      isChallengeMode: difficulty === Difficulty.CHALLENGE,
      isExamMode: difficulty === Difficulty.EXAM
    };
    setQuiz(newQuiz);
    setLoading(false);
    triggerCountdown();
    backgroundSync(difficulty, config.count, language, 10);
  };

  const startDailyQuiz = async () => {
    if (isDailyDone) return;
    playSound('nav');
    setLoading(true);
    syncRef.current = true;

    const initialQuestions = await fetchQuestions(language, Difficulty.MEDIUM, 10, true);
    const newQuiz: QuizState = {
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: 10,
      isComplete: false,
      difficulty: Difficulty.MEDIUM,
      timeRemaining: 20 * 60, 
      totalQuestions: DAILY_QUIZ_COUNT,
      isDailyMode: true
    };
    setQuiz(newQuiz);
    setLoading(false);
    triggerCountdown();
    backgroundSync(Difficulty.MEDIUM, DAILY_QUIZ_COUNT, language, 10, true);
  };

  const saveToHistory = (score: number, totalPlayed: number, skipped: number, diff: Difficulty | 'DAILY', isChallenge?: boolean) => {
    const newEntry: HistoryEntry = {
      id: Date.now().toString(),
      difficulty: diff,
      score,
      total: totalPlayed,
      skipped,
      date: new Date().toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }),
      isChallenge
    };
    setHistory(prev => [newEntry, ...prev].slice(0, 50)); 
  };

  const handleAnswer = (index: number) => {
    if (!quiz || selectedAnswer !== null) return;
    setSelectedAnswer(index);

    if (quiz.isExamMode) {
      playSound('nav');
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
        setQuiz(prev => prev ? ({ ...prev, score: prev.score + 1 }) : null);
      }
      setTimeout(() => {
        nextQuestion();
      }, 300);
    } else {
      setShowExplanation(true);
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
        playSound('correct');
        setQuiz(prev => prev ? ({ ...prev, score: prev.score + 1 }) : null);
      } else {
        playSound('incorrect');
      }
    }
  };

  const handleSkip = () => {
    if (!quiz || quiz.skipsRemaining <= 0 || selectedAnswer !== null || quiz.isExamMode) return;
    playSound('nav');
    const isLast = quiz.currentIndex + 1 >= quiz.totalQuestions;
    setQuiz(prev => prev ? ({ ...prev, skipsRemaining: prev.skipsRemaining - 1, skippedCount: prev.skippedCount + 1 }) : null);
    if (isLast) {
      finishQuiz(quiz.totalQuestions);
    } else {
      moveNext();
    }
  };

  const finishQuiz = (attempted?: number) => {
    if (!quiz) return;
    const finalAttempted = attempted ?? (quiz.isChallengeMode ? quiz.currentIndex : quiz.currentIndex + 1);
    const diffLabel = quiz.isDailyMode ? 'DAILY' : quiz.difficulty;

    saveToHistory(quiz.score, finalAttempted, quiz.skippedCount, diffLabel, quiz.isChallengeMode);

    if (quiz.isDailyMode) {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const todayStr = today.toISOString().split('T')[0];

      if (lastDailyDate !== todayStr) {
        const last = lastDailyDate ? new Date(lastDailyDate) : null;
        if (last) last.setHours(0,0,0,0);

        const yesterday = new Date(today);
        yesterday.setDate(yesterday.getDate() - 1);
        yesterday.setHours(0,0,0,0);

        if (!last || last.getTime() === yesterday.getTime()) {
           setDailyStreak(prev => prev + 1);
        } else if (last.getTime() < yesterday.getTime()) {
           setDailyStreak(1);
        }
        setLastDailyDate(todayStr);
      }
    }

    setAppState('RESULT');
    localStorage.removeItem(ACTIVE_QUIZ_KEY);
  };

  const moveNext = () => {
    if (!quiz) return;
    if (quiz.currentIndex + 1 >= quiz.questions.length) {
      setLoading(true);
      const checkBuffer = setInterval(() => {
        setQuiz(prev => {
          if (prev && prev.currentIndex + 1 < prev.questions.length) {
            clearInterval(checkBuffer);
            setLoading(false);
            return { ...prev, currentIndex: prev.currentIndex + 1 };
          }
          return prev;
        });
      }, 500);
    } else {
      setQuiz(prev => prev ? ({ ...prev, currentIndex: prev.currentIndex + 1 }) : null);
    }
  };

  const nextQuestion = () => {
    if (!quiz) return;
    if (!quiz.isExamMode) playSound('nav');
    setSelectedAnswer(null);
    setShowExplanation(false);
    if (quiz.currentIndex + 1 < quiz.totalQuestions) {
      moveNext();
    } else {
      finishQuiz();
    }
  };

  const handleNav = (state: AppState) => {
    playSound('nav');
    setAppState(state);
    if (state !== 'QUIZ' && state !== 'COUNTDOWN') syncRef.current = false;
  };

  const toggleBookmark = (q: Question) => {
    if (quiz?.isExamMode) return;
    playSound('nav');
    setBookmarks(prev => prev.find(b => b.id === q.id) ? prev.filter(b => b.id !== q.id) : [...prev, q]);
  };

  const clearHistory = () => {
    playSound('nav');
    if (window.confirm(t.clearHistory + '?')) setHistory([]);
  };

  const handleShare = async () => {
    if (!quiz) return;
    playSound('nav');
    const total = quiz.isChallengeMode ? quiz.currentIndex : quiz.totalQuestions;
    const diffLabel = quiz.isDailyMode ? t.dailyQuiz : (t[quiz.difficulty] || quiz.difficulty);
    const message = t.shareText(quiz.score, total, diffLabel);
    if (navigator.share) {
      try { await navigator.share({ title: APP_NAME, text: message, url: window.location.href }); } catch (err) { console.error(err); }
    } else {
      try { await navigator.clipboard.writeText(message); setShowCopied(true); setTimeout(() => setShowCopied(false), 2000); } catch (err) { console.error(err); }
    }
  };

  const isBookmarked = (id: string) => bookmarks.some(b => b.id === id);

  const ThematicLoader = () => (
    <div className="flex flex-col items-center justify-center min-h-[400px] w-full max-w-lg mx-auto p-8 space-y-12 animate-fade-in">
      <div className="relative">
        <div className="w-32 h-32 text-orange-600 animate-[spin_10s_linear_infinite] drop-shadow-lg">
          <svg viewBox="0 0 100 100" className="w-full h-full" fill="currentColor">
            <circle cx="50" cy="50" r="48" fill="none" stroke="currentColor" strokeWidth="1" />
            <circle cx="50" cy="50" r="8" fill="currentColor" />
            {[...Array(24)].map((_, i) => (
              <line key={i} x1="50" y1="50" x2={50 + 40 * Math.cos((i * 15 * Math.PI) / 180)} y2={50 + 40 * Math.sin((i * 15 * Math.PI) / 180)} stroke="currentColor" strokeWidth="1.5" />
            ))}
            <circle cx="50" cy="50" r="42" fill="none" stroke="currentColor" strokeWidth="2" />
          </svg>
        </div>
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-40 h-40 border-4 border-orange-200 rounded-full animate-ping opacity-20"></div>
      </div>
      <div className="w-full space-y-8 text-center">
        <div className="space-y-2">
          <p className="text-3xl font-black text-orange-900 tracking-tighter">
            {quiz && quiz.questions.length < quiz.totalQuestions && quiz.currentIndex >= quiz.questions.length - 1 ? "कालचक्र घूम रहा है..." : "इतिहास के पन्नों को खोजा जा रहा है..."}
          </p>
          <div className="flex items-center justify-center gap-2 text-orange-700/60 font-black text-xs uppercase tracking-widest">
            <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
            {isSyncing ? `प्रमाण एकत्रित हो रहे हैं... (${quiz?.questions.length}/${quiz?.totalQuestions})` : "ज्ञान संचय जारी है..."}
          </div>
        </div>
        <div className="relative w-full h-1 bg-orange-100 rounded-full overflow-hidden">
          <div className="absolute inset-0 bg-gradient-to-r from-orange-400 via-red-500 to-orange-400 w-1/3 animate-[translateX_3s_linear_infinite]"></div>
        </div>
        <div className="flex justify-between text-[10px] font-black text-orange-400 uppercase tracking-tighter px-1"><span>प्राचीन</span><span>मध्यकालीन</span><span>आधुनिक</span></div>
      </div>
      <style>{`@keyframes translateX { 0% { transform: translateX(-100%); } 100% { transform: translateX(300%); } }`}</style>
    </div>
  );

  const isDailyDone = lastDailyDate === new Date().toISOString().split('T')[0];

  return (
    <div className={`min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800 ${quiz?.isChallengeMode && (appState === 'QUIZ' || appState === 'COUNTDOWN') ? 'ring-inset ring-8 ring-red-500/20' : ''}`}>
      <header className={`w-full p-4 flex justify-between items-center text-white shadow-md z-30 sticky top-0 transition-colors ${quiz?.isChallengeMode && (appState === 'QUIZ' || appState === 'COUNTDOWN') ? 'bg-red-600' : quiz?.isExamMode && (appState === 'QUIZ' || appState === 'COUNTDOWN') ? 'bg-slate-800' : 'bg-orange-600'}`}>
        <span className="font-bold text-lg cursor-pointer flex items-center gap-2" onClick={() => handleNav('LANDING')}>
          <span className="bg-white text-orange-600 w-8 h-8 rounded-full flex items-center justify-center font-black">इ</span>
          <span className="hidden xs:inline">{AUTHOR_NAME}</span>
        </span>
        {(appState === 'QUIZ' || appState === 'COUNTDOWN') && quiz && (
          <div className={`flex items-center gap-2 sm:gap-3 px-2 sm:px-3 py-1.5 rounded-full font-mono font-bold text-xs sm:text-sm shadow-inner transition-colors ${quiz.isChallengeMode ? 'bg-black/40' : quiz.isExamMode ? 'bg-white/10' : 'bg-white/20'}`}>
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            <span className={quiz.timeRemaining < 30 ? 'text-yellow-300 animate-pulse' : ''}>{formatTime(quiz.timeRemaining)}</span>
          </div>
        )}
        <div className="flex gap-1.5 sm:gap-2">
          {dailyStreak > 0 && (
            <div className="flex items-center gap-1 bg-white/20 px-3 py-1 rounded-full text-[10px] font-black">
              🔥 {dailyStreak}
            </div>
          )}
          <button onClick={() => handleNav('HISTORY')} className="bg-white/20 hover:bg-white/30 p-1.5 rounded-full transition"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg></button>
          <button onClick={() => handleNav('BOOKMARKS')} className="bg-white/20 hover:bg-white/30 p-1.5 rounded-full transition relative"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg>{bookmarks.length > 0 && <span className="absolute -top-1 -right-1 bg-white text-orange-600 text-[10px] w-4 h-4 rounded-full flex items-center justify-center font-black">{bookmarks.length}</span>}</button>
          <button onClick={() => handleNav('SETTINGS')} className="p-1.5 hover:bg-white/10 rounded-full transition"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg></button>
        </div>
      </header>
      <main className="flex-1 w-full max-w-2xl px-4 py-8 flex flex-col items-center justify-center">
        {appState === 'LANDING' && (
          <div className="text-center animate-fade-in py-10 w-full">
