          <div className="bg-white rounded-[3rem] p-8 max-w-md w-full shadow-2xl border-4 border-orange-100 text-center animate-fade-in">
             <div className="w-20 h-20 bg-orange-100 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl">🎓</div>
             <h2 className="text-3xl font-black text-orange-900 mb-2">स्वागत है (Welcome)</h2>
             <p className="text-gray-500 font-medium mb-8">ऐप का अनुभव लेने और महत्वपूर्ण संदेश प्राप्त करने के लिए अपना Gmail दर्ज करें।</p>
             <form onSubmit={handleEmailSubmit} className="space-y-4">
                <input 
