                <button type="submit" className="w-full py-4 bg-orange-600 hover:bg-orange-700 text-white font-black rounded-2xl shadow-xl transition-transform active:scale-95 uppercase tracking-widest">
                  जारी रखें (Continue)
                </button>
             </form>
          </div>
        </div>
