                    <p className={`text-xs font-bold mt-1 ${isSunday ? 'text-slate-400' : 'text-gray-400'}`}>{isSunday ? t.finalResultsOnly : "अगली परीक्षा रविवार को (Next Sunday)"}</p>
                 </div>
                 <button onClick={() => isSunday && startQuiz(Difficulty.EXAM)} disabled={!isSunday} className={`w-full py-3 font-black rounded-2xl shadow-lg transition transform active:scale-95 uppercase tracking-widest text-sm ${isSunday ? 'bg-white text-slate-900 hover:bg-slate-50' : 'bg-gray-300 text-gray-500 cursor-not-allowed'}`}>
                    {isSunday ? t.start : "Locked"}
