            <div className="space-y-4 max-w-sm mx-auto">
              <button onClick={() => handleNav('DIFFICULTY_SELECT')} className="w-full py-5 px-8 bg-orange-600 hover:bg-orange-700 text-white font-black text-2xl rounded-3xl shadow-2xl transform hover:scale-105 transition uppercase tracking-widest">{t.start}</button>
              <div className="grid grid-cols-2 gap-4">
                <button onClick={() => handleNav('BOOKMARKS')} className="w-full py-3 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition flex items-center justify-center gap-2 text-sm">🔖 {t.bookmarks}</button>
                <button onClick={() => handleNav('HISTORY')} className="w-full py-3 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition flex items-center justify-center gap-2 text-sm">📜 {t.history}</button>
              </div>
            </div>
          </div>
        )}

        {appState === 'COUNTDOWN' && (
          <div className="flex flex-col items-center justify-center text-center space-y-8 animate-fade-in w-full max-w-lg mx-auto py-20 px-6">
