        {appState === 'QUIZ' && quiz && (
          <div className="w-full pb-20">
            {loading ? <ThematicLoader /> : (
              <div className="space-y-8 animate-fade-in">
                <div className="w-full bg-orange-100 h-3 rounded-full overflow-hidden border border-orange-200">
                  <div className={`h-full transition-all duration-500 ease-out ${quiz.isDailyMode ? 'bg-indigo-600' : quiz.isExamMode ? 'bg-slate-800' : 'bg-orange-600'}`} style={{ width: `${((quiz.currentIndex + 1) / quiz.totalQuestions) * 100}%` }}></div>
