import { GoogleGenAI, Type } from "@google/genai";
import { Question, Language, Difficulty } from "../types";

// Always use the direct process.env.API_KEY when initializing the GoogleGenAI client
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const getDifficultyInstruction = (difficulty: Difficulty) => {
  switch (difficulty) {
    case Difficulty.EASY:
      return "Focus on basic well-known facts like 1947 independence, Ashoka's pillars, the Taj Mahal, and major independence leaders.";
    case Difficulty.MEDIUM:
      return "Focus on administrative reforms, minor battles, constitutional developments, and detailed features of major dynasties (Cholas, Guptas, Mughals).";
    case Difficulty.HARD:
      return "Focus on extremely obscure details: specific inscriptions, minor vassal states, regional art schools (Pahari, Deccan), pre-historic sites (Burzahom, Mehrgarh), and specific tribal uprisings.";
    case Difficulty.CHALLENGE:
      return "Provide a mix of all eras with varying difficulty, optimized for quick mental recall.";
    default:
      return "";
  }
};

export const fetchQuestions = async (language: Language, difficulty: Difficulty, count: number, isDaily: boolean = false): Promise<Question[]> => {
  // Use AbortController for faster cancellation if needed, though gemini-sdk handles standard fetches
  try {
    const eras = ["Ancient", "Medieval", "Modern"];
    const randomEra = eras[Math.floor(Math.random() * eras.length)];
    const todayStr = new Date().toISOString().split('T')[0];

    const contextInstruction = isDaily 
      ? `Generate a CURATED daily set of ${count} questions. Today's theme seed is ${todayStr}. Ensure a balanced mix of eras.`
      : `Generate ${count} UNIQUE and HISTORICALLY ACCURATE objective questions. Focus Era: ${randomEra}.`;

    // Speed optimization: Generate slightly more at once to reduce round trips
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `${contextInstruction}
      Language: ${language}.
      Difficulty Level: ${difficulty}. ${getDifficultyInstruction(difficulty)}.
      Verification: Use Google Search to cross-reference multiple historical sources.
      Avoid: Do not repeat common questions. Be specific and academic.
      Output: Return a JSON array of question objects.`,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              text: { type: Type.STRING },
              options: {
                type: Type.ARRAY,
                items: { type: Type.STRING },
                minItems: 4,
                maxItems: 4
              },
              correctAnswer: { type: Type.INTEGER, minimum: 0, maximum: 3 },
              explanation: { type: Type.STRING },
              era: { type: Type.STRING, enum: ["Ancient", "Medieval", "Modern"] }
            },
            required: ["id", "text", "options", "correctAnswer", "explanation", "era"]
          }
        }
      }
    });

    const questions: Question[] = JSON.parse(response.text || "[]");
    const groundingChunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    const sources = groundingChunks?.map((chunk: any) => ({
      title: chunk.web?.title || "Historical Reference",
      uri: chunk.web?.uri || ""
    })).filter((s: any) => s.uri !== "") || [];

    return questions.map(q => ({
      ...q,
      id: q.id || Math.random().toString(36).substr(2, 9),
      sources: sources.length > 0 ? sources.slice(0, 2) : undefined
    }));
  } catch (error) {
    console.error("Error fetching questions:", error);
    return [];
  }
};

