  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [showCopied, setShowCopied] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  // Gmail Collection
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [emailInput, setEmailInput] = useState("");
  const [showEmailModal, setShowEmailModal] = useState(false);

  // Sunday Check
  const [isSunday, setIsSunday] = useState(false);
  const [showExamNotification, setShowExamNotification] = useState(false);

  // Daily Stats
  const [dailyStreak, setDailyStreak] = useState(0);
  const [lastDailyDate, setLastDailyDate] = useState<string | null>(null);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);

  const t = useMemo(() => TRANSLATIONS[language] || TRANSLATIONS[Language.ENGLISH], [language]);

  // Derived state to check if daily quiz is completed today
  const isDailyDone = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    return lastDailyDate === todayStr;
  }, [lastDailyDate]);

  // Derived state for searching bookmarks
  const filteredBookmarks = useMemo(() => {
    return bookmarks.filter(q => 
      q.text.toLowerCase().includes(searchQuery.toLowerCase()) || 
      q.explanation.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [bookmarks, searchQuery]);

  // Audio optimization
  const playSound = useCallback((type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      const now = ctx.currentTime;

      if (type === 'correct') {
        osc.type = 'sine'; osc.frequency.setValueAtTime(523.25, now);
        osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
        gain.gain.setValueAtTime(0.1, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
        osc.start(now); osc.stop(now + 0.3);
      } else if (type === 'incorrect') {
        osc.type = 'sawtooth'; osc.frequency.setValueAtTime(220, now);
        osc.frequency.linearRampToValueAtTime(110, now + 0.2);
        gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
        osc.start(now); osc.stop(now + 0.3);
      } else if (type === 'nav') {
        osc.type = 'sine'; osc.frequency.setValueAtTime(800, now);
        gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
        osc.start(now); osc.stop(now + 0.1);
      }
    } catch (e) {
      console.warn("Audio Context Error", e);
    }
  }, [soundEnabled]);

  // Performance: stable nav handler
  const handleNav = useCallback((state: AppState) => {
    playSound('nav');
    setAppState(state);
    setSearchQuery("");
    if (state !== 'QUIZ') syncRef.current = false;
  }, [playSound]);

  // Sunday Check & Initialization
  useEffect(() => {
    const day = new Date().getDay();
    const sundayStatus = day === 0;
    setIsSunday(sundayStatus);
    if (sundayStatus) {
      setShowExamNotification(true);
      setTimeout(() => setShowExamNotification(false), 4000);
    }

    const savedEmail = localStorage.getItem(USER_EMAIL_KEY);
    if (savedEmail) {
      setUserEmail(savedEmail);
    } else {
      setShowEmailModal(true);
    }

    const savedBookmarks = localStorage.getItem(BOOKMARKS_KEY);
    if (savedBookmarks) {
      try { setBookmarks(JSON.parse(savedBookmarks)); } catch (e) { console.error(e); }
    }

    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) {
      try { setHistory(JSON.parse(savedHistory)); } catch (e) { console.error(e); }
    }

    const savedStats = localStorage.getItem(DAILY_STATS_KEY);
    if (savedStats) {
      try {
        const stats = JSON.parse(savedStats);
        setDailyStreak(stats.streak || 0);
        setLastDailyDate(stats.lastDate || null);
      } catch (e) { console.error(e); }
    }

    const savedActiveQuiz = localStorage.getItem(ACTIVE_QUIZ_KEY);
    if (savedActiveQuiz) {
      try { 
        const parsed = JSON.parse(savedActiveQuiz);
        if (parsed && !parsed.isComplete) setQuiz(parsed);
      } catch (e) { console.error(e); }
    }
  }, []);

  const handleEmailSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (emailInput.includes('@') && emailInput.includes('.')) {
      localStorage.setItem(USER_EMAIL_KEY, emailInput);
      setUserEmail(emailInput);
      setShowEmailModal(false);
      playSound('correct');
    }
  };

  // Batch updates for persistence
  useEffect(() => {
    const timeout = setTimeout(() => {
      localStorage.setItem(BOOKMARKS_KEY, JSON.stringify(bookmarks));
    }, 500);
    return () => clearTimeout(timeout);
  }, [bookmarks]);

  useEffect(() => {
    const timeout = setTimeout(() => {
      localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
    }, 500);
    return () => clearTimeout(timeout);
  }, [history]);

  useEffect(() => {
    if (quiz) localStorage.setItem(ACTIVE_QUIZ_KEY, JSON.stringify(quiz));
  }, [quiz]);

  useEffect(() => {
    localStorage.setItem(DAILY_STATS_KEY, JSON.stringify({ streak: dailyStreak, lastDate: lastDailyDate }));
  }, [dailyStreak, lastDailyDate]);

  // Optimized Quiz Timer
  useEffect(() => {
    if (appState === 'QUIZ' && quiz && quiz.timeRemaining > 0 && !loading) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (!prev) return null;
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [appState, loading, quiz?.timeRemaining]);

  const handleTimeUp = useCallback(() => {
    if (!quiz) return;
    playSound('incorrect');
    const attempted = quiz.isChallengeMode ? quiz.currentIndex : quiz.currentIndex + 1;
    finishQuiz(attempted);
  }, [quiz, playSound]);

  const backgroundSync = useCallback(async (difficulty: Difficulty, target: number, currentLang: Language, existingCount: number, isDaily: boolean = false) => {
    if (syncRef.current) return;
    syncRef.current = true;
    setIsSyncing(true);
    let currentCount = existingCount;
    while (currentCount < target && syncRef.current) {
      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, 30, isDaily);
        if (moreQuestions.length === 0) break;
        setQuiz(prev => {
          if (!prev) return null;
          const uniqueNew = moreQuestions.filter(mq => !prev.questions.some(pq => pq.text === mq.text));
          return { ...prev, questions: [...prev.questions, ...uniqueNew] };
        });
        currentCount += moreQuestions.length;
      } catch (err) { 
        console.error("Sync error", err);
        break; 
      }
      await new Promise(r => setTimeout(r, 2000));
    }
    setIsSyncing(false);
    syncRef.current = false;
  }, []);

  const startQuiz = useCallback(async (difficulty: Difficulty, resume = false) => {
    if (difficulty === Difficulty.EXAM && !isSunday) return;
    playSound('nav');
    if (resume && quiz) {
      setAppState('QUIZ');
      if (quiz.questions.length < quiz.totalQuestions) {
        backgroundSync(quiz.difficulty, quiz.totalQuestions, language, quiz.questions.length, quiz.isDailyMode);
      }
      return;
    }
    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true);
    syncRef.current = true;
    const initialQuestions = await fetchQuestions(language, difficulty, 12);
    const newQuiz: QuizState = {
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: config.maxSkips,
      isComplete: false,
      difficulty,
      timeRemaining: config.time,
      totalQuestions: config.count,
      isChallengeMode: difficulty === Difficulty.CHALLENGE,
      isExamMode: difficulty === Difficulty.EXAM
    };
    setQuiz(newQuiz);
    setLoading(false);
    setAppState('QUIZ');
    backgroundSync(difficulty, config.count, language, 12);
  }, [isSunday, playSound, quiz, language, backgroundSync]);

  const startDailyQuiz = useCallback(async () => {
    if (isDailyDone) return;
    playSound('nav');
    setLoading(true);
    syncRef.current = true;
    const initialQuestions = await fetchQuestions(language, Difficulty.MEDIUM, 10, true);
    const newQuiz: QuizState = {
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: 10,
      isComplete: false,
      difficulty: Difficulty.MEDIUM,
      timeRemaining: 20 * 60, 
      totalQuestions: DAILY_QUIZ_COUNT,
      isDailyMode: true
    };
    setQuiz(newQuiz);
    setLoading(false);
    setAppState('QUIZ');
    backgroundSync(Difficulty.MEDIUM, DAILY_QUIZ_COUNT, language, 10, true);
  }, [isDailyDone, playSound, language, backgroundSync]);

  const finishQuiz = useCallback((attempted?: number) => {
    if (!quiz) return;
    const finalAttempted = attempted ?? (quiz.isChallengeMode ? quiz.currentIndex : quiz.currentIndex + 1);
    const newEntry: HistoryEntry = {
      id: Date.now().toString(),
      difficulty: quiz.isDailyMode ? 'DAILY' : quiz.difficulty,
      score: quiz.score,
      total: finalAttempted,
      skipped: quiz.skippedCount,
      date: new Date().toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }),
      isChallenge: quiz.isChallengeMode
    };
    setHistory(prev => [newEntry, ...prev].slice(0, 50)); 

    if (quiz.isDailyMode) {
      const todayStr = new Date().toISOString().split('T')[0];
      if (lastDailyDate !== todayStr) {
        setDailyStreak(prev => prev + 1);
        setLastDailyDate(todayStr);
      }
    }
    setAppState('RESULT');
    localStorage.removeItem(ACTIVE_QUIZ_KEY);
  }, [quiz, lastDailyDate]);

  const moveNext = useCallback(() => {
    if (!quiz) return;
    if (quiz.currentIndex + 1 < quiz.questions.length) {
      setQuiz(prev => prev ? ({ ...prev, currentIndex: prev.currentIndex + 1 }) : null);
    } else {
      setLoading(true);
      const checkBuffer = setInterval(() => {
        setQuiz(prev => {
          if (prev && prev.currentIndex + 1 < prev.questions.length) {
            clearInterval(checkBuffer);
            setLoading(false);
            return { ...prev, currentIndex: prev.currentIndex + 1 };
          }
          return prev;
        });
      }, 300);
    }
  }, [quiz]);

  const nextQuestion = useCallback(() => {
    if (!quiz) return;
    if (!quiz.isExamMode) playSound('nav');
    setSelectedAnswer(null);
    setShowExplanation(false);
    if (quiz.currentIndex + 1 < quiz.totalQuestions) moveNext();
    else finishQuiz();
  }, [quiz, playSound, moveNext, finishQuiz]);

  const handleAnswer = useCallback((index: number) => {
    if (!quiz || selectedAnswer !== null) return;
    setSelectedAnswer(index);
    if (quiz.isExamMode) {
      playSound('nav');
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
        setQuiz(prev => prev ? ({ ...prev, score: prev.score + 1 }) : null);
      }
      setTimeout(() => nextQuestion(), 250);
    } else {
      setShowExplanation(true);
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
        playSound('correct');
        setQuiz(prev => prev ? ({ ...prev, score: prev.score + 1 }) : null);
      } else {
        playSound('incorrect');
      }
    }
  }, [quiz, selectedAnswer, playSound, nextQuestion]);

  const handleSkip = useCallback(() => {
    if (!quiz || quiz.skipsRemaining <= 0 || selectedAnswer !== null || quiz.isExamMode) return;
    playSound('nav');
    const isLast = quiz.currentIndex + 1 >= quiz.totalQuestions;
    setQuiz(prev => prev ? ({ ...prev, skipsRemaining: prev.skipsRemaining - 1, skippedCount: prev.skippedCount + 1 }) : null);
    if (isLast) finishQuiz(quiz.totalQuestions);
    else moveNext();
  }, [quiz, selectedAnswer, playSound, finishQuiz, moveNext]);

  const toggleBookmark = useCallback((q: Question) => {
    if (quiz?.isExamMode) return;
    playSound('nav');
    setBookmarks(prev => prev.find(b => b.id === q.id) ? prev.filter(b => b.id !== q.id) : [...prev, q]);
  }, [quiz?.isExamMode, playSound]);

  const handleShare = useCallback(async () => {
    if (!quiz) return;
    playSound('nav');
    const total = quiz.isChallengeMode ? quiz.currentIndex : quiz.totalQuestions;
    const message = t.shareText(quiz.score, total, quiz.isDailyMode ? t.dailyQuiz : (t[quiz.difficulty] || quiz.difficulty));
    if (navigator.share) {
      try { await navigator.share({ title: APP_NAME, text: message, url: window.location.href }); } catch (e) { console.warn(e); }
    } else {
      try { await navigator.clipboard.writeText(message); setShowCopied(true); setTimeout(() => setShowCopied(false), 2000); } catch (e) { console.warn(e); }
    }
  }, [quiz, t, playSound]);

  const ThematicLoader = () => (
    <div className="flex flex-col items-center justify-center min-h-[400px] w-full max-w-lg mx-auto p-8 space-y-12 animate-fade-in will-change-transform">
      <div className="relative">
        <div className="w-32 h-32 text-orange-600 animate-[spin_6s_linear_infinite] drop-shadow-lg">
          <svg viewBox="0 0 100 100" className="w-full h-full" fill="currentColor">
            <circle cx="50" cy="50" r="48" fill="none" stroke="currentColor" strokeWidth="1" />
            <circle cx="50" cy="50" r="8" fill="currentColor" />
            {[...Array(24)].map((_, i) => (
              <line key={i} x1="50" y1="50" x2={50 + 40 * Math.cos((i * 15 * Math.PI) / 180)} y2={50 + 40 * Math.sin((i * 15 * Math.PI) / 180)} stroke="currentColor" strokeWidth="1.5" />
            ))}
            <circle cx="50" cy="50" r="42" fill="none" stroke="currentColor" strokeWidth="2" />
          </svg>
        </div>
      </div>
      <p className="text-3xl font-black text-orange-900 tracking-tighter text-center">इतिहास के पन्नों को खोजा जा रहा है...</p>
    </div>
  );

  const clearHistory = useCallback(() => {
    playSound('nav');
    if (window.confirm(t.clearHistory + '?')) setHistory([]);
  }, [playSound, t.clearHistory]);

  return (
    <div className={`min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800 transition-all duration-300 ${quiz?.isChallengeMode && appState === 'QUIZ' ? 'ring-inset ring-8 ring-red-500/20' : ''}`}>

      {showExamNotification && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-50 bg-slate-900 text-white px-8 py-4 rounded-3xl shadow-2xl flex items-center gap-4 animate-bounce border-2 border-slate-700 will-change-transform">
           <span className="text-2xl">📢</span>
           <span className="font-black text-lg tracking-wider">Pariksha Mod opening!</span>
        </div>
      )}

      {showEmailModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4 transition-opacity">
          <div className="bg-white rounded-[3rem] p-8 max-w-md w-full shadow-2xl border-4 border-orange-100 text-center animate-fade-in will-change-transform">
             <div className="w-20 h-20 bg-orange-100 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl">🎓</div>
             <h2 className="text-3xl font-black text-orange-900 mb-2">स्वागत है (Welcome)</h2>
             <p className="text-gray-500 font-medium mb-8 leading-tight">ऐप का अनुभव लेने और महत्वपूर्ण संदेश प्राप्त करने के लिए अपना Gmail दर्ज करें।</p>
             <form onSubmit={handleEmailSubmit} className="space-y-4">
                <input 
                  type="email" 
                  required
                  placeholder="अपना Gmail दर्ज करें..."
                  value={emailInput}
                  onChange={(e) => setEmailInput(e.target.value)}
                  className="w-full py-4 px-6 rounded-2xl border-2 border-orange-100 focus:border-orange-600 focus:outline-none text-lg font-bold transition-all shadow-inner"
                />
                <button type="submit" className="w-full py-4 bg-orange-600 hover:bg-orange-700 text-white font-black rounded-2xl shadow-xl transition-transform active:scale-95 uppercase tracking-widest">
                  जारी रखें (Continue)
                </button>
             </form>
          </div>
        </div>
      )}

      <header className={`w-full p-4 flex justify-between items-center text-white shadow-md z-30 sticky top-0 transition-colors duration-300 ${quiz?.isChallengeMode && appState === 'QUIZ' ? 'bg-red-600' : quiz?.isExamMode && appState === 'QUIZ' ? 'bg-slate-800' : 'bg-orange-600'}`}>
        <span className="font-bold text-lg cursor-pointer flex items-center gap-2 select-none" onClick={() => handleNav('LANDING')}>
          <span className="bg-white text-orange-600 w-8 h-8 rounded-full flex items-center justify-center font-black">इ</span>
          <span className="hidden xs:inline">{AUTHOR_NAME}</span>
        </span>
        <div className="flex gap-1.5 sm:gap-2 items-center">
          {dailyStreak > 0 && <div className="flex items-center gap-1 bg-white/20 px-3 py-1 rounded-full text-[10px] font-black animate-pulse">🔥 {dailyStreak}</div>}
          <button onClick={() => handleNav('BOOKMARKS')} className="bg-white/20 hover:bg-white/30 p-1.5 rounded-full transition-all active:scale-90 relative"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg></button>
          <button onClick={() => handleNav('SETTINGS')} className="p-1.5 hover:bg-white/10 rounded-full transition-all active:scale-90"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg></button>
        </div>
      </header>

      <main className="flex-1 w-full max-w-2xl px-4 py-8 flex flex-col items-center justify-center">
        {appState === 'LANDING' && (
          <div className="text-center animate-fade-in py-10 w-full will-change-transform">
            <h1 className="text-6xl md:text-9xl font-black text-orange-600 mb-2 hindi-font tracking-tighter drop-shadow-xl">{INTRO_MAIN}</h1>
            <p className="text-xl md:text-3xl text-orange-800 font-bold mb-12 italic opacity-80">"{INTRO_SUB}"</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-2xl mx-auto mb-12">
              <div className={`p-6 rounded-[2.5rem] border-4 shadow-xl text-left flex flex-col justify-between h-56 transition-all duration-300 transform hover:-translate-y-1 ${isDailyDone ? 'bg-indigo-50 border-indigo-200' : 'bg-white border-orange-100'}`}>
                <div>
                  <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${isDailyDone ? 'bg-indigo-600 text-white' : 'bg-orange-100 text-orange-600'}`}>{t.dailyQuiz}</span>
                  <h3 className="text-2xl font-black text-gray-900 mt-4 leading-tight">{t.dailyGoal}</h3>
                </div>
                {!isDailyDone ? <button onClick={startDailyQuiz} className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-2xl shadow-lg transition transform active:scale-95 uppercase tracking-widest text-sm">{t.start}</button> : <div className="flex items-center gap-2 text-indigo-600 font-black"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 24 24" fill="currentColor"><path fillRule="evenodd" d="M2.25 12c0-5.385 4.365-9.75 9.75-9.75s9.75 4.365 9.75 9.75-4.365 9.75-9.75 9.75S2.25 17.385 2.25 12Zm13.36-1.814a.75.75 0 1 0-1.22-.872l-3.236 4.53L9.53 12.22a.75.75 0 0 0-1.06 1.06l2.25 2.25a.75.75 0 0 0 1.14-.094l3.74-5.24Z" clipRule="evenodd" /></svg>{t.dailyDone}</div>}
              </div>

              <div className={`p-6 rounded-[2.5rem] border-4 shadow-xl text-left flex flex-col justify-between h-56 transition-all duration-300 transform hover:-translate-y-1 ${isSunday ? 'border-slate-100 bg-slate-900' : 'border-gray-200 bg-gray-100 grayscale opacity-60'}`}>
                 <div>
                    <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${isSunday ? 'bg-slate-700 text-white' : 'bg-gray-400 text-white'}`}>{t.examMode}</span>
                    <h3 className={`text-2xl font-black mt-4 ${isSunday ? 'text-white' : 'text-gray-400'}`}>{t[Difficulty.EXAM]}</h3>
                    <p className={`text-xs font-bold mt-1 ${isSunday ? 'text-slate-400' : 'text-gray-400'}`}>{isSunday ? t.finalResultsOnly : "अगली परीक्षा रविवार को (Next Sunday)"}</p>
                 </div>
                 <button onClick={() => isSunday && startQuiz(Difficulty.EXAM)} disabled={!isSunday} className={`w-full py-4 font-black rounded-2xl shadow-lg transition transform active:scale-95 uppercase tracking-widest text-sm ${isSunday ? 'bg-white text-slate-900 hover:bg-slate-50' : 'bg-gray-300 text-gray-500 cursor-not-allowed'}`}>
                    {isSunday ? t.start : "Locked"}
                 </button>
              </div>
            </div>

            <div className="space-y-4 max-w-sm mx-auto">
              <button onClick={() => handleNav('DIFFICULTY_SELECT')} className="w-full py-5 px-8 bg-orange-600 hover:bg-orange-700 text-white font-black text-2xl rounded-3xl shadow-2xl transform hover:scale-105 transition-all duration-200 uppercase tracking-widest">{t.start}</button>
              <div className="grid grid-cols-2 gap-4">
                <button onClick={() => handleNav('BOOKMARKS')} className="w-full py-3 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition flex items-center justify-center gap-2 text-sm">🔖 {t.bookmarks}</button>
                <button onClick={() => handleNav('HISTORY')} className="w-full py-3 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition flex items-center justify-center gap-2 text-sm">📜 {t.history}</button>
              </div>
            </div>
          </div>
        )}

        {appState === 'QUIZ' && quiz && (
          <div className="w-full pb-20">
            {loading ? <ThematicLoader /> : (
              <div className="space-y-8 animate-fade-in will-change-opacity">
                <div className="w-full bg-orange-100 h-3 rounded-full overflow-hidden border border-orange-200">
                  <div className={`h-full transition-all duration-300 ease-out ${quiz.isDailyMode ? 'bg-indigo-600' : quiz.isExamMode ? 'bg-slate-800' : 'bg-orange-600'}`} style={{ width: `${((quiz.currentIndex + 1) / quiz.totalQuestions) * 100}%` }}></div>
                </div>
                <div className="flex justify-between items-center text-sm font-black text-orange-900">
                  <span className="uppercase tracking-widest opacity-50">{quiz.isExamMode ? t.examMode : (t[quiz.difficulty] || quiz.difficulty)}</span>
                  <span className="text-lg font-mono">{formatTime(quiz.timeRemaining)}</span>
                  <span className="text-lg">{`प्रसंग ${quiz.currentIndex + 1} / ${quiz.totalQuestions}`}</span>
                </div>
                <h2 className="text-3xl md:text-4xl font-black text-gray-900 leading-tight hindi-font drop-shadow-sm">{quiz.questions[quiz.currentIndex].text}</h2>
                <div className="grid grid-cols-1 gap-4">
                  {quiz.questions[quiz.currentIndex].options.map((option, idx) => (
                    <button key={idx} onClick={() => handleAnswer(idx)} disabled={selectedAnswer !== null} className={`group p-5 text-left rounded-3xl border-4 transition-all duration-200 flex items-center transform active:scale-[0.98] ${selectedAnswer === null ? 'border-orange-50 bg-white hover:border-orange-600 hover:shadow-xl' : (idx === quiz.questions[quiz.currentIndex].correctAnswer && !quiz.isExamMode) ? 'border-green-600 bg-green-50 ring-4 ring-green-100' : (selectedAnswer === idx && !quiz.isExamMode) ? 'border-red-600 bg-red-50 ring-4 ring-red-100' : quiz.isExamMode && selectedAnswer === idx ? 'border-slate-800 bg-slate-50' : 'opacity-40 grayscale'}`}>
                      <span className={`w-10 h-10 rounded-full flex items-center justify-center font-black mr-4 text-lg border-2 transition-colors ${selectedAnswer === null ? 'bg-orange-50 border-orange-200 text-orange-600' : quiz.isExamMode && selectedAnswer === idx ? 'bg-slate-800 text-white' : (idx === quiz.questions[quiz.currentIndex].correctAnswer && !quiz.isExamMode) ? 'bg-green-600 text-white border-green-600' : 'bg-gray-200'}`}>{String.fromCharCode(65 + idx)}</span>
                      <span className="text-xl font-bold">{option}</span>
                    </button>
                  ))}
                </div>
                {showExplanation && !quiz.isExamMode && (
                  <div className={`p-8 bg-blue-50 border-4 border-blue-600 rounded-[2.5rem] animate-fade-in shadow-xl will-change-transform`}>
                    <p className="text-blue-800 text-lg leading-relaxed font-medium mb-6">{quiz.questions[quiz.currentIndex].explanation}</p>
                    <button onClick={nextQuestion} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-5 rounded-3xl transition-all shadow-xl active:scale-95 text-xl uppercase tracking-widest">{quiz.currentIndex + 1 < quiz.totalQuestions ? t.next : t.finish}</button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {appState === 'RESULT' && quiz && (
          <div className="text-center space-y-10 animate-fade-in w-full py-10 will-change-transform">
             <div className="relative inline-block"><svg className="w-64 h-64 drop-shadow-2xl"><circle cx="128" cy="128" r="110" fill="none" stroke="#fed7aa" strokeWidth="18" /><circle cx="128" cy="128" r="110" fill="none" stroke={`${quiz.isDailyMode ? '#4f46e5' : quiz.isExamMode ? '#1e293b' : '#ea580c'}`} strokeWidth="18" strokeDasharray={`${(quiz.score / quiz.totalQuestions) * 691.15} 691.15`} strokeLinecap="round" transform="rotate(-90 128 128)" className="transition-all duration-1000 ease-out will-change-[stroke-dasharray]" /></svg><div className="absolute inset-0 flex flex-col items-center justify-center"><span className={`text-6xl font-black ${quiz.isDailyMode ? 'text-indigo-600' : quiz.isExamMode ? 'text-slate-900' : 'text-orange-600'}`}>{Math.round((quiz.score / quiz.totalQuestions) * 100)}%</span></div></div>
             <div className="flex flex-col gap-4 max-w-sm mx-auto">
                <button onClick={handleShare} className="w-full py-4 bg-indigo-600 text-white font-black rounded-3xl shadow-xl transition transform hover:scale-105 active:scale-95 uppercase tracking-widest">Share Result</button>
                <button onClick={() => handleNav('LANDING')} className="w-full py-4 bg-orange-600 text-white font-black rounded-3xl shadow-xl transition transform hover:scale-105 active:scale-95 uppercase tracking-widest">मुख्य पृष्ठ (HOME)</button>
             </div>
          </div>
        )}

        {appState === 'HISTORY' && (
          <div className="w-full space-y-6 animate-fade-in will-change-opacity">
             <div className="flex justify-between items-center"><h2 className="text-3xl font-black text-orange-900">📜 {t.history}</h2><button onClick={() => handleNav('LANDING')} className="text-orange-600 font-bold p-2 active:scale-90">Close</button></div>
             <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-2 scrollbar-thin">
                {history.length === 0 ? <p className="text-center text-gray-400 py-10">No history yet.</p> : history.map(entry => (
                  <div key={entry.id} className="bg-white p-5 rounded-3xl shadow-md border-2 border-orange-50 flex justify-between items-center transform transition hover:scale-[1.01]">
                    <div><span className="text-[10px] font-black uppercase text-gray-400 tracking-tighter">{entry.difficulty}</span><h3 className="text-xl font-bold">{entry.score}/{entry.total}</h3></div>
                    <span className="text-xs text-gray-400 font-medium">{entry.date}</span>
                  </div>
                ))}
             </div>
             {history.length > 0 && <button onClick={clearHistory} className="w-full py-3 text-red-500 font-bold text-sm uppercase tracking-widest">Clear All History</button>}
          </div>
        )}

        {appState === 'BOOKMARKS' && (
          <div className="w-full space-y-6 animate-fade-in">
             <div className="flex justify-between items-center"><h2 className="text-3xl font-black text-orange-900">🔖 {t.bookmarks}</h2><button onClick={() => handleNav('LANDING')} className="text-orange-600 font-bold p-2 active:scale-90">Close</button></div>
             <input type="text" placeholder="Search saved questions..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} className="w-full p-4 rounded-2xl border-2 border-orange-100 focus:border-orange-600 focus:outline-none font-bold shadow-sm" />
             <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-2">
                {filteredBookmarks.length === 0 ? <p className="text-center text-gray-400 py-10">No bookmarks found.</p> : filteredBookmarks.map(q => (
                  <div key={q.id} className="bg-white p-6 rounded-3xl shadow-md border-2 border-orange-50 mb-4 transform transition hover:shadow-lg">
                    <h3 className="font-bold mb-2 text-lg leading-snug">{q.text}</h3>
                    <p className="text-sm text-gray-500 italic bg-orange-50/50 p-3 rounded-xl">{q.explanation}</p>
                    <button onClick={() => toggleBookmark(q)} className="text-xs text-red-500 mt-3 font-bold uppercase tracking-widest">Remove</button>
                  </div>
                ))}
             </div>
          </div>
        )}

        {appState === 'SETTINGS' && (
          <div className="w-full bg-white p-10 rounded-[3rem] shadow-xl space-y-10 border-4 border-orange-50 will-change-transform">
             <div className="flex justify-between items-center border-b border-orange-100 pb-4"><h2 className="text-3xl font-black">⚙️ {t.settings}</h2><button onClick={() => handleNav('LANDING')} className="text-orange-600 font-bold p-2">Close</button></div>
             <section className="space-y-4"><h3 className="font-black text-orange-900 uppercase tracking-widest text-sm">🔊 {t.soundEffects}</h3><div className="flex gap-4"><button onClick={() => { setSoundEnabled(true); playSound('nav'); }} className={`flex-1 py-4 rounded-2xl font-black transition-all ${soundEnabled ? 'bg-orange-600 text-white shadow-lg' : 'bg-gray-100 text-gray-400'}`}>{t.on}</button><button onClick={() => setSoundEnabled(false)} className={`flex-1 py-4 rounded-2xl font-black transition-all ${!soundEnabled ? 'bg-orange-600 text-white shadow-lg' : 'bg-gray-100 text-gray-400'}`}>{t.off}</button></div></section>
             <section className="space-y-4"><h3 className="font-black text-orange-900 uppercase tracking-widest text-sm">🌐 {t.selectLang}</h3><div className="grid grid-cols-2 gap-4">{LANGUAGES.map(lang => (<button key={lang.code} onClick={() => { setLanguage(lang.code); playSound('nav'); }} className={`p-4 rounded-2xl border-2 font-black transition-all ${language === lang.code ? 'border-orange-600 bg-orange-50 text-orange-600 shadow-md scale-[1.02]' : 'border-gray-50 text-gray-400'}`}>{lang.name}</button>))}</div></section>
             {userEmail && <div className="text-center bg-gray-50 p-4 rounded-2xl border border-gray-100"><p className="text-gray-400 text-[10px] font-black uppercase tracking-widest mb-1">Registered Account</p><p className="text-gray-600 font-bold truncate">{userEmail}</p></div>}
          </div>
        )}

        {appState === 'DIFFICULTY_SELECT' && (
          <div className="w-full max-w-md space-y-8 animate-fade-in">
             <h2 className="text-4xl font-black text-orange-900 text-center mb-8 tracking-tighter">प्रश्नोत्तरी का स्तर (Level)</h2>
             <div className="space-y-4">
                {DIFFICULTIES.filter(d => d.code !== Difficulty.CHALLENGE && d.code !== Difficulty.EXAM).map(diff => (
                  <button key={diff.code} onClick={() => startQuiz(diff.code)} className={`group w-full p-6 bg-white border-4 border-orange-50 hover:border-orange-400 rounded-3xl shadow-lg text-left transition-all transform hover:-translate-y-1 active:scale-[0.98]`}>
                     <div className="flex justify-between items-center">
                        <h3 className="text-2xl font-black text-gray-900 group-hover:text-orange-600 transition-colors">{t[diff.code]}</h3>
                        <span className="text-2xl">➔</span>
                     </div>
                     <p className="text-xs text-gray-400 font-black uppercase tracking-widest mt-1 opacity-70">{diff.count} {t.questions} | {diff.time / 60} {t.minutes}</p>
                  </button>
                ))}
             </div>
             <button onClick={() => handleNav('LANDING')} className="w-full py-4 text-gray-400 font-bold text-sm uppercase tracking-widest">Back</button>
          </div>
        )}
      </main>

      <footer className="w-full p-8 text-center text-gray-400 text-[10px] font-black uppercase tracking-[0.4em] opacity-40">
        &copy; {new Date().getFullYear()} {APP_NAME} - {AUTHOR_NAME}
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { AppState, Language, Question, QuizState, Difficulty, HistoryEntry } from './types';
import { fetchQuestions } from './services/geminiService';
import { AUTHOR_NAME, APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES, DAILY_QUIZ_COUNT } from './constants';

const BOOKMARKS_KEY = 'history_bookmarks';
const HISTORY_KEY = 'quiz_history_data';
const ACTIVE_QUIZ_KEY = 'active_quiz_session';
const DAILY_STATS_KEY = 'daily_stats_v1';
const USER_EMAIL_KEY = 'user_gmail_id';

// Add formatTime helper function to handle quiz timer display
const formatTime = (seconds: number): string => {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  if (h > 0) {
    return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  }
  return `${m}:${s.toString().padStart(2, '0')}`;
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState | null>(null);
  const [bookmarks, setBookmarks] = useState<Question[]>([]);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [showCopied, setShowCopied] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");

  // Gmail Collection
  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [emailInput, setEmailInput] = useState("");
  const [showEmailModal, setShowEmailModal] = useState(false);

  // Sunday Check
  const [isSunday, setIsSunday] = useState(false);
  const [showExamNotification, setShowExamNotification] = useState(false);

  // Daily Stats
  const [dailyStreak, setDailyStreak] = useState(0);
  const [lastDailyDate, setLastDailyDate] = useState<string | null>(null);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);

  const t = useMemo(() => TRANSLATIONS[language] || TRANSLATIONS[Language.ENGLISH], [language]);

  // Derived state to check if daily quiz is completed today
  const isDailyDone = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    return lastDailyDate === todayStr;
  }, [lastDailyDate]);

  // Derived state for searching bookmarks
  const filteredBookmarks = useMemo(() => {
    return bookmarks.filter(q => 
      q.text.toLowerCase().includes(searchQuery.toLowerCase()) || 
      q.explanation.toLowerCase().includes(searchQuery.toLowerCase())
    );
  }, [bookmarks, searchQuery]);

  // Audio optimization
  const playSound = useCallback((type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      const now = ctx.currentTime;

      if (type === 'correct') {
        osc.type = 'sine'; osc.frequency.setValueAtTime(523.25, now);
        osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
        gain.gain.setValueAtTime(0.1, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
        osc.start(now); osc.stop(now + 0.3);
      } else if (type === 'incorrect') {
        osc.type = 'sawtooth'; osc.frequency.setValueAtTime(220, now);
        osc.frequency.linearRampToValueAtTime(110, now + 0.2);
        gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
        osc.start(now); osc.stop(now + 0.3);
      } else if (type === 'nav') {
        osc.type = 'sine'; osc.frequency.setValueAtTime(800, now);
        gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
        osc.start(now); osc.stop(now + 0.1);
      }
    } catch (e) {
      console.warn("Audio Context Error", e);
    }
  }, [soundEnabled]);

  // Performance: stable nav handler
  const handleNav = useCallback((state: AppState) => {
    playSound('nav');
    setAppState(state);
    setSearchQuery("");
    if (state !== 'QUIZ') syncRef.current = false;
  }, [playSound]);

  // Sunday Check & Initialization
  useEffect(() => {
    const day = new Date().getDay();
    const sundayStatus = day === 0;
    setIsSunday(sundayStatus);
    if (sundayStatus) {
      setShowExamNotification(true);
      setTimeout(() => setShowExamNotification(false), 4000);
    }

    const savedEmail = localStorage.getItem(USER_EMAIL_KEY);
    if (savedEmail) {
      setUserEmail(savedEmail);
    } else {
      setShowEmailModal(true);
    }

    const savedBookmarks = localStorage.getItem(BOOKMARKS_KEY);
    if (savedBookmarks) {
      try { setBookmarks(JSON.parse(savedBookmarks)); } catch (e) { console.error(e); }
    }

    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) {
      try { setHistory(JSON.parse(savedHistory)); } catch (e) { console.error(e); }
    }

    const savedStats = localStorage.getItem(DAILY_STATS_KEY);
    if (savedStats) {
      try {
        const stats = JSON.parse(savedStats);
        setDailyStreak(stats.streak || 0);
        setLastDailyDate(stats.lastDate || null);
      } catch (e) { console.error(e); }
    }

    const savedActiveQuiz = localStorage.getItem(ACTIVE_QUIZ_KEY);
    if (savedActiveQuiz) {
      try { 
        const parsed = JSON.parse(savedActiveQuiz);
        if (parsed && !parsed.isComplete) setQuiz(parsed);
      } catch (e) { console.error(e); }
    }
  }, []);

  const handleEmailSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (emailInput.includes('@') && emailInput.includes('.')) {
      localStorage.setItem(USER_EMAIL_KEY, emailInput);
      setUserEmail(emailInput);
      setShowEmailModal(false);
      playSound('correct');
    }
  };

  // Batch updates for persistence
  useEffect(() => {
    const timeout = setTimeout(() => {
      localStorage.setItem(BOOKMARKS_KEY, JSON.stringify(bookmarks));
    }, 500);
    return () => clearTimeout(timeout);
  }, [bookmarks]);

  useEffect(() => {
    const timeout = setTimeout(() => {
      localStorage.setItem(HISTORY_KEY, JSON.stringify(history));
    }, 500);
    return () => clearTimeout(timeout);
  }, [history]);

  useEffect(() => {
    if (quiz) localStorage.setItem(ACTIVE_QUIZ_KEY, JSON.stringify(quiz));
  }, [quiz]);

  useEffect(() => {
    localStorage.setItem(DAILY_STATS_KEY, JSON.stringify({ streak: dailyStreak, lastDate: lastDailyDate }));
  }, [dailyStreak, lastDailyDate]);

  // Optimized Quiz Timer
  useEffect(() => {
    if (appState === 'QUIZ' && quiz && quiz.timeRemaining > 0 && !loading) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (!prev) return null;
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [appState, loading, quiz?.timeRemaining]);

  const handleTimeUp = useCallback(() => {
    if (!quiz) return;
    playSound('incorrect');
    const attempted = quiz.isChallengeMode ? quiz.currentIndex : quiz.currentIndex + 1;
    finishQuiz(attempted);
  }, [quiz, playSound]);

  const backgroundSync = useCallback(async (difficulty: Difficulty, target: number, currentLang: Language, existingCount: number, isDaily: boolean = false) => {
    if (syncRef.current) return;
    syncRef.current = true;
    setIsSyncing(true);
    let currentCount = existingCount;
    while (currentCount < target && syncRef.current) {
      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, 30, isDaily);
        if (moreQuestions.length === 0) break;
        setQuiz(prev => {
          if (!prev) return null;
          const uniqueNew = moreQuestions.filter(mq => !prev.questions.some(pq => pq.text === mq.text));
          return { ...prev, questions: [...prev.questions, ...uniqueNew] };
        });
        currentCount += moreQuestions.length;
      } catch (err) { 
        console.error("Sync error", err);
        break; 
      }
      await new Promise(r => setTimeout(r, 2000));
    }
    setIsSyncing(false);
    syncRef.current = false;
  }, []);

  const startQuiz = useCallback(async (difficulty: Difficulty, resume = false) => {
    if (difficulty === Difficulty.EXAM && !isSunday) return;
    playSound('nav');
    if (resume && quiz) {
      setAppState('QUIZ');
      if (quiz.questions.length < quiz.totalQuestions) {
        backgroundSync(quiz.difficulty, quiz.totalQuestions, language, quiz.questions.length, quiz.isDailyMode);
      }
      return;
    }
    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true);
    syncRef.current = true;
    const initialQuestions = await fetchQuestions(language, difficulty, 12);
    const newQuiz: QuizState = {
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: config.maxSkips,
      isComplete: false,
      difficulty,
      timeRemaining: config.time,
      totalQuestions: config.count,
      isChallengeMode: difficulty === Difficulty.CHALLENGE,
      isExamMode: difficulty === Difficulty.EXAM
    };
    setQuiz(newQuiz);
    setLoading(false);
    setAppState('QUIZ');
    backgroundSync(difficulty, config.count, language, 12);
  }, [isSunday, playSound, quiz, language, backgroundSync]);

  const startDailyQuiz = useCallback(async () => {
    if (isDailyDone) return;
    playSound('nav');
    setLoading(true);
    syncRef.current = true;
    const initialQuestions = await fetchQuestions(language, Difficulty.MEDIUM, 10, true);
    const newQuiz: QuizState = {
      questions: initialQuestions,
      currentIndex: 0,
      score: 0,
      skippedCount: 0,
      skipsRemaining: 10,
      isComplete: false,
      difficulty: Difficulty.MEDIUM,
      timeRemaining: 20 * 60, 
      totalQuestions: DAILY_QUIZ_COUNT,
      isDailyMode: true
    };
    setQuiz(newQuiz);
    setLoading(false);
    setAppState('QUIZ');
    backgroundSync(Difficulty.MEDIUM, DAILY_QUIZ_COUNT, language, 10, true);
  }, [isDailyDone, playSound, language, backgroundSync]);

  const finishQuiz = useCallback((attempted?: number) => {
    if (!quiz) return;
    const finalAttempted = attempted ?? (quiz.isChallengeMode ? quiz.currentIndex : quiz.currentIndex + 1);
    const newEntry: HistoryEntry = {
      id: Date.now().toString(),
      difficulty: quiz.isDailyMode ? 'DAILY' : quiz.difficulty,
      score: quiz.score,
      total: finalAttempted,
      skipped: quiz.skippedCount,
      date: new Date().toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }),
      isChallenge: quiz.isChallengeMode
    };
    setHistory(prev => [newEntry, ...prev].slice(0, 50)); 

    if (quiz.isDailyMode) {
      const todayStr = new Date().toISOString().split('T')[0];
      if (lastDailyDate !== todayStr) {
        setDailyStreak(prev => prev + 1);
        setLastDailyDate(todayStr);
      }
    }
    setAppState('RESULT');
    localStorage.removeItem(ACTIVE_QUIZ_KEY);
  }, [quiz, lastDailyDate]);

  const moveNext = useCallback(() => {
    if (!quiz) return;
    if (quiz.currentIndex + 1 < quiz.questions.length) {
      setQuiz(prev => prev ? ({ ...prev, currentIndex: prev.currentIndex + 1 }) : null);
    } else {
      setLoading(true);
      const checkBuffer = setInterval(() => {
        setQuiz(prev => {
          if (prev && prev.currentIndex + 1 < prev.questions.length) {
            clearInterval(checkBuffer);
            setLoading(false);
            return { ...prev, currentIndex: prev.currentIndex + 1 };
          }
          return prev;
        });
      }, 300);
    }
  }, [quiz]);

  const nextQuestion = useCallback(() => {
    if (!quiz) return;
    if (!quiz.isExamMode) playSound('nav');
    setSelectedAnswer(null);
    setShowExplanation(false);
    if (quiz.currentIndex + 1 < quiz.totalQuestions) moveNext();
    else finishQuiz();
  }, [quiz, playSound, moveNext, finishQuiz]);

  const handleAnswer = useCallback((index: number) => {
    if (!quiz || selectedAnswer !== null) return;
    setSelectedAnswer(index);
    if (quiz.isExamMode) {
      playSound('nav');
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
        setQuiz(prev => prev ? ({ ...prev, score: prev.score + 1 }) : null);
      }
      setTimeout(() => nextQuestion(), 250);
    } else {
      setShowExplanation(true);
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) {
        playSound('correct');
        setQuiz(prev => prev ? ({ ...prev, score: prev.score + 1 }) : null);
      } else {
        playSound('incorrect');
      }
    }
  }, [quiz, selectedAnswer, playSound, nextQuestion]);

  const handleSkip = useCallback(() => {
    if (!quiz || quiz.skipsRemaining <= 0 || selectedAnswer !== null || quiz.isExamMode) return;
    playSound('nav');
    const isLast = quiz.currentIndex + 1 >= quiz.totalQuestions;
    setQuiz(prev => prev ? ({ ...prev, skipsRemaining: prev.skipsRemaining - 1, skippedCount: prev.skippedCount + 1 }) : null);
    if (isLast) finishQuiz(quiz.totalQuestions);
    else moveNext();
  }, [quiz, selectedAnswer, playSound, finishQuiz, moveNext]);

  const toggleBookmark = useCallback((q: Question) => {
    if (quiz?.isExamMode) return;
    playSound('nav');
    setBookmarks(prev => prev.find(b => b.id === q.id) ? prev.filter(b => b.id !== q.id) : [...prev, q]);
  }, [quiz?.isExamMode, playSound]);

  const handleShare = useCallback(async () => {
    if (!quiz) return;
    playSound('nav');
    const total = quiz.isChallengeMode ? quiz.currentIndex : quiz.totalQuestions;
    const message = t.shareText(quiz.score, total, quiz.isDailyMode ? t.dailyQuiz : (t[quiz.difficulty] || quiz.difficulty));
    if (navigator.share) {
      try { await navigator.share({ title: APP_NAME, text: message, url: window.location.href }); } catch (e) { console.warn(e); }
    } else {
      try { await navigator.clipboard.writeText(message); setShowCopied(true); setTimeout(() => setShowCopied(false), 2000); } catch (e) { console.warn(e); }
    }
  }, [quiz, t, playSound]);

  const ThematicLoader = () => (
    <div className="flex flex-col items-center justify-center min-h-[400px] w-full max-w-lg mx-auto p-8 space-y-12 animate-fade-in will-change-transform">
      <div className="relative">
        <div className="w-32 h-32 text-orange-600 animate-[spin_6s_linear_infinite] drop-shadow-lg">
          <svg viewBox="0 0 100 100" className="w-full h-full" fill="currentColor">
            <circle cx="50" cy="50" r="48" fill="none" stroke="currentColor" strokeWidth="1" />
            <circle cx="50" cy="50" r="8" fill="currentColor" />
            {[...Array(24)].map((_, i) => (
              <line key={i} x1="50" y1="50" x2={50 + 40 * Math.cos((i * 15 * Math.PI) / 180)} y2={50 + 40 * Math.sin((i * 15 * Math.PI) / 180)} stroke="currentColor" strokeWidth="1.5" />
            ))}
            <circle cx="50" cy="50" r="42" fill="none" stroke="currentColor" strokeWidth="2" />
          </svg>
        </div>
      </div>
      <p className="text-3xl font-black text-orange-900 tracking-tighter text-center">इतिहास के पन्नों को खोजा जा रहा है...</p>
    </div>
  );

  const clearHistory = useCallback(() => {
    playSound('nav');
    if (window.confirm(t.clearHistory + '?')) setHistory([]);
  }, [playSound, t.clearHistory]);

  return (
