                <button onClick={() => handleNav('HISTORY')} className="w-full py-3 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl shadow-sm hover:border-orange-600 transition flex items-center justify-center gap-2 text-sm">📜 {t.history}</button>
              </div>
            </div>
          </div>
        )}

        {appState === 'QUIZ' && quiz && (
          <div className="w-full pb-20">
            {loading ? <ThematicLoader /> : (
              <div className="space-y-8 animate-fade-in will-change-opacity">
                <div className="flex justify-center items-center gap-2 mb-2 bg-orange-50 border border-orange-100 py-2 px-4 rounded-full w-fit mx-auto shadow-sm animate-pulse">
                  <span className="relative flex h-3 w-3">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-3 w-3 bg-green-500"></span>
                  </span>
                  <span className="text-[10px] font-black text-orange-900 uppercase tracking-widest">
