                {userPhone && <div className="text-center bg-gray-50 p-4 rounded-2xl border border-gray-100"><p className="text-gray-400 text-[10px] font-black uppercase tracking-widest mb-1">Phone</p><p className="text-gray-600 font-bold truncate">{userPhone}</p></div>}
