export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { AppState, Language, Question, QuizState, Difficulty, HistoryEntry } from './types';
import { fetchQuestions } from './services/geminiService';
import { APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES, DAILY_QUIZ_COUNT } from './constants';

const BOOKMARKS_KEY = 'history_bookmarks';
const HISTORY_KEY = 'quiz_history_data';
const ACTIVE_QUIZ_KEY = 'active_quiz_session';
const DAILY_STATS_KEY = 'daily_stats_v1';
const USER_EMAIL_KEY = 'user_gmail_id';
const USER_PHONE_KEY = 'user_phone_number';

const HINDI_NAMES = [
  "आदित्य शर्मा", "प्रिया पटेल", "राहुल वर्मा", "अंजली सिंह", "संदीप यादव",
  "नेहा गुप्ता", "विकास मिश्रा", "पूजा तिवारी", "अमित राज", "स्नेहा रेड्डी",
  "मनीष बिष्ट", "कविता जोशी", "रोहित मेहरा", "दीपिका पादुकोण", "ऋषभ पंत",
  "श्रेया घोषाल", "अरुण जेटली", "स्मृति ईरानी", "नितिन गडकरी", "शिवानी सिंह",
  "योगेश कुमार", "मंजू कुमारी", "सुनील छेत्री", "साइना नेहवाल"
];

const formatTime = (seconds: number): string => {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  if (h > 0) return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  return `${m}:${s.toString().padStart(2, '0')}`;
};

type ExamStatus = 'LOCKED' | 'UPCOMING' | 'LIVE' | 'CLOSED';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState | null>(null);
  const [bookmarks, setBookmarks] = useState<Question[]>([]);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [liveParticipants, setLiveParticipants] = useState(0);
  const [leaderboard, setLeaderboard] = useState<{name: string, score: number, timeTaken: number, rank: number, isUser?: boolean}[]>([]);

  // Security & Live Schedule States
  const [isTabActive, setIsTabActive] = useState(true);
  const [multiTabError, setMultiTabError] = useState(false);
  const [disqualified, setDisqualified] = useState(false);
  const [examStatus, setExamStatus] = useState<ExamStatus>('LOCKED');
  const [timeToExam, setTimeToExam] = useState(0); // Seconds until 11 AM or 12 PM

  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [userPhone, setUserPhone] = useState<string | null>(null);
  const [emailInput, setEmailInput] = useState("");
  const [phoneInput, setPhoneInput] = useState("");
  const [showEmailModal, setShowEmailModal] = useState(false);

  const [dailyStreak, setDailyStreak] = useState(0);
  const [lastDailyDate, setLastDailyDate] = useState<string | null>(null);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);
  const sessionRef = useRef(Math.random().toString(36).substring(7));

  const t = useMemo(() => TRANSLATIONS[language] || TRANSLATIONS[Language.ENGLISH], [language]);

  const isDailyDone = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    return lastDailyDate === todayStr;
  }, [lastDailyDate]);

  // --- LIVE SCHEDULE LOGIC ---
  const checkExamWindow = useCallback(() => {
    const now = new Date();
    const day = now.getDay(); // 0 is Sunday
    const hours = now.getHours();
    const minutes = now.getMinutes();
    const currentTimeInMins = hours * 60 + minutes;

    const startMins = 11 * 60; // 11:00 AM
    const endMins = 12 * 60;   // 12:00 PM

    if (day !== 0) {
      setExamStatus('LOCKED');
      return;
    }

    if (currentTimeInMins < startMins) {
      setExamStatus('UPCOMING');
      setTimeToExam((startMins - currentTimeInMins) * 60 - now.getSeconds());
    } else if (currentTimeInMins >= startMins && currentTimeInMins < endMins) {
      setExamStatus('LIVE');
      setTimeToExam((endMins - currentTimeInMins) * 60 - now.getSeconds());
    } else {
      setExamStatus('CLOSED');
    }
  }, []);

  useEffect(() => {
    checkExamWindow();
    const interval = setInterval(checkExamWindow, 1000);
    return () => clearInterval(interval);
  }, [checkExamWindow]);

  // --- ANTI-CHEAT LOGIC ---
  useEffect(() => {
    const channel = new BroadcastChannel('quiz_session_sync');
    channel.postMessage({ type: 'NEW_SESSION', id: sessionRef.current });
    channel.onmessage = (event) => {
      if (event.data.type === 'NEW_SESSION') {
        setMultiTabError(true);
        if (appState === 'QUIZ' && quiz?.isExamMode) setDisqualified(true);
      }
    };
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();
    const handleKeydown = (e: KeyboardEvent) => {
      if (e.key === 'PrintScreen' || (e.ctrlKey && ['c','u','s','p','i','j'].includes(e.key.toLowerCase()))) {
        e.preventDefault();
        alert("सुरक्षा प्रोटोकॉल: यह क्रिया वर्जित है।");
      }
    };
    window.addEventListener('contextmenu', handleContextMenu);
    window.addEventListener('keydown', handleKeydown);
    const handleVisibilityChange = () => {
      const active = document.visibilityState === 'visible';
      setIsTabActive(active);
      if (!active && appState === 'QUIZ' && quiz?.isExamMode) {
        setDisqualified(true);
        finishQuiz();
      }
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      channel.close();
      window.removeEventListener('contextmenu', handleContextMenu);
      window.removeEventListener('keydown', handleKeydown);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [appState, quiz?.isExamMode]);

  // --- REGULAR LOGIC ---
  useEffect(() => {
    if (appState === 'QUIZ') {
      const base = quiz?.isExamMode ? 1200 : 45;
      const initial = base + Math.floor(Math.random() * 50);
      setLiveParticipants(initial);
      const interval = setInterval(() => {
        setLiveParticipants(prev => Math.max(prev + (Math.random() > 0.5 ? 2 : -2), 10));
      }, 3000);
      return () => clearInterval(interval);
    }
  }, [appState, quiz?.isExamMode]);

  const playSound = useCallback((type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      const now = ctx.currentTime;
      if (type === 'correct') {
        osc.frequency.setValueAtTime(523, now); osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
        gain.gain.setValueAtTime(0.1, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
      } else if (type === 'incorrect') {
        osc.type = 'sawtooth'; osc.frequency.setValueAtTime(220, now);
        gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
      } else {
        osc.frequency.setValueAtTime(800, now); gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
      }
      osc.start(now); osc.stop(now + 0.3);
    } catch (e) {}
  }, [soundEnabled]);

  const handleNav = useCallback((state: AppState) => {
    playSound('nav');
    setAppState(state);
    if (state !== 'QUIZ') syncRef.current = false;
  }, [playSound]);

  useEffect(() => {
    const savedEmail = localStorage.getItem(USER_EMAIL_KEY);
    const savedPhone = localStorage.getItem(USER_PHONE_KEY);
    if (savedEmail && savedPhone) { setUserEmail(savedEmail); setUserPhone(savedPhone); } else { setShowEmailModal(true); }
    const savedBookmarks = localStorage.getItem(BOOKMARKS_KEY);
    if (savedBookmarks) try { setBookmarks(JSON.parse(savedBookmarks)); } catch (e) {}
    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) try { setHistory(JSON.parse(savedHistory)); } catch (e) {}
    const savedStats = localStorage.getItem(DAILY_STATS_KEY);
    if (savedStats) try { const stats = JSON.parse(savedStats); setDailyStreak(stats.streak || 0); setLastDailyDate(stats.lastDate || null); } catch (e) {}
  }, []);

  const handleUserSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (emailInput.includes('@') && phoneInput.length >= 10) {
      localStorage.setItem(USER_EMAIL_KEY, emailInput);
      localStorage.setItem(USER_PHONE_KEY, phoneInput);
      setUserEmail(emailInput); setUserPhone(phoneInput);
      setShowEmailModal(false); playSound('correct');
    }
  };

  useEffect(() => { localStorage.setItem(BOOKMARKS_KEY, JSON.stringify(bookmarks)); }, [bookmarks]);
  useEffect(() => { localStorage.setItem(HISTORY_KEY, JSON.stringify(history)); }, [history]);

  useEffect(() => {
    if (appState === 'QUIZ' && quiz && quiz.timeRemaining > 0 && !loading && !disqualified) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (!prev) return null;
          // Forced exit at 12:00 PM logic for Exam Mode
          if (prev.isExamMode && examStatus === 'CLOSED') {
             clearInterval(timerRef.current!);
             finishQuiz();
             return null;
          }
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [appState, loading, quiz?.timeRemaining, disqualified, examStatus]);

  const generateLeaderboard = useCallback((userScore: number, totalQuestions: number, userTimeSeconds: number) => {
    const participants = [];
    const shuffledNames = [...HINDI_NAMES].sort(() => 0.5 - Math.random());
    for (let i = 0; i < 25; i++) {
      let score = totalQuestions - Math.floor(Math.random() * (totalQuestions * 0.3));
      participants.push({ name: shuffledNames[i] || `प्रतियोगी ${i}`, score, timeTaken: score * 15 + Math.random() * 60 });
    }
    if (!disqualified) participants.push({ name: userEmail?.split('@')[0] || "आप", score: userScore, timeTaken: userTimeSeconds, isUser: true });
    const sorted = participants.sort((a, b) => b.score !== a.score ? b.score - a.score : a.timeTaken - b.timeTaken).slice(0, 20);
    setLeaderboard(sorted.map((p, idx) => ({ ...p, rank: idx + 1 })));
  }, [userEmail, disqualified]);

  const finishQuiz = useCallback((attempted?: number) => {
    setQuiz(prev => {
        if (!prev) return null;
        const finalAttempted = attempted ?? (prev.currentIndex + 1);
        const difficultyConfig = DIFFICULTIES.find(d => d.code === prev.difficulty);
        const totalTimeAllowed = prev.isDailyMode ? 1200 : (difficultyConfig?.time || 0);
        const userTimeTaken = totalTimeAllowed - prev.timeRemaining;
        const newEntry: HistoryEntry = {
          id: Date.now().toString(),
          difficulty: prev.isDailyMode ? 'DAILY' : prev.difficulty,
          score: disqualified ? 0 : prev.score,
          total: finalAttempted,
          skipped: prev.skippedCount,
          date: new Date().toLocaleString(),
          isChallenge: prev.isChallengeMode
        };
        setHistory(h => [newEntry, ...h].slice(0, 50)); 
        generateLeaderboard(disqualified ? 0 : prev.score, finalAttempted, userTimeTaken);
        setAppState('RESULT');
        return null;
    });
  }, [disqualified, generateLeaderboard]);

  const handleTimeUp = useCallback(() => { playSound('incorrect'); finishQuiz(); }, [playSound, finishQuiz]);

  const backgroundSync = useCallback(async (difficulty: Difficulty, target: number, currentLang: Language, existingCount: number, isDaily: boolean = false) => {
    if (syncRef.current) return; syncRef.current = true;
    let currentCount = existingCount;
    while (currentCount < target && syncRef.current) {
      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, 30, isDaily);
        if (moreQuestions.length === 0) break;
        setQuiz(prev => {
          if (!prev) return null;
          const uniqueNew = moreQuestions.filter(mq => !prev.questions.some(pq => pq.text === mq.text));
          return { ...prev, questions: [...prev.questions, ...uniqueNew] };
        });
        currentCount += moreQuestions.length;
      } catch (err) { break; }
      await new Promise(r => setTimeout(r, 2000));
    }
    syncRef.current = false;
  }, []);

  const startQuiz = useCallback(async (difficulty: Difficulty) => {
    if (difficulty === Difficulty.EXAM && examStatus !== 'LIVE') return;
    playSound('nav'); setDisqualified(false);
    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true); syncRef.current = true;
    const initialQuestions = await fetchQuestions(language, difficulty, 15);

    // For live exam, ensure they don't get more time than remains until 12:00 PM
    let timeLimit = config.time;
    if (difficulty === Difficulty.EXAM) {
      const now = new Date();
      const endWindow = new Date(); endWindow.setHours(12, 0, 0, 0);
      const remainingWindowSecs = Math.floor((endWindow.getTime() - now.getTime()) / 1000);
      timeLimit = Math.min(config.time, remainingWindowSecs);
    }

    setQuiz({
      questions: initialQuestions, currentIndex: 0, score: 0, skippedCount: 0, skipsRemaining: config.maxSkips,
      isComplete: false, difficulty, timeRemaining: timeLimit, totalQuestions: config.count,
      isChallengeMode: difficulty === Difficulty.CHALLENGE, isExamMode: difficulty === Difficulty.EXAM
    });
    setLoading(false); setAppState('QUIZ');
    backgroundSync(difficulty, config.count, language, 15);
  }, [examStatus, playSound, language, backgroundSync]);

  const startDailyQuiz = useCallback(async () => {
    if (isDailyDone) return; playSound('nav'); setLoading(true); syncRef.current = true;
    const initialQuestions = await fetchQuestions(language, Difficulty.MEDIUM, 10, true);
    setQuiz({
      questions: initialQuestions, currentIndex: 0, score: 0, skippedCount: 0, skipsRemaining: 10,
      isComplete: false, difficulty: Difficulty.MEDIUM, timeRemaining: 1200, totalQuestions: DAILY_QUIZ_COUNT, isDailyMode: true
    });
    setLoading(false); setAppState('QUIZ');
    backgroundSync(Difficulty.MEDIUM, DAILY_QUIZ_COUNT, language, 10, true);
  }, [isDailyDone, playSound, language, backgroundSync]);

  const handleAnswer = useCallback((index: number) => {
    if (!quiz || selectedAnswer !== null || disqualified) return;
    setSelectedAnswer(index);
    if (quiz.isExamMode) {
      playSound('nav');
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) setQuiz(p => p ? ({ ...p, score: p.score + 1 }) : null);
      setTimeout(() => { setSelectedAnswer(null); if (quiz.currentIndex + 1 < quiz.totalQuestions) setQuiz(p => p ? ({ ...p, currentIndex: p.currentIndex + 1 }) : null); else finishQuiz(); }, 300);
    } else {
      setShowExplanation(true);
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) { playSound('correct'); setQuiz(p => p ? ({ ...p, score: p.score + 1 }) : null); } else playSound('incorrect');
    }
  }, [quiz, selectedAnswer, disqualified, playSound, finishQuiz]);

  const toggleBookmark = useCallback((q: Question) => {
    if (quiz?.isExamMode) return; playSound('nav');
    setBookmarks(prev => prev.find(b => b.id === q.id) ? prev.filter(b => b.id !== q.id) : [...prev, q]);
  }, [quiz?.isExamMode, playSound]);

  return (
    <div className={`min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800 transition-all duration-300 select-none ${!isTabActive ? 'blur-2xl grayscale' : ''}`}>

      {multiTabError && (
        <div className="fixed inset-0 z-[200] bg-orange-950 flex flex-col items-center justify-center p-8 text-center text-white">
           <div className="text-8xl mb-6">🚫</div>
           <h2 className="text-4xl font-black mb-4">एकाधिक टैब का पता चला</h2>
           <p className="text-xl max-w-md opacity-80">सुरक्षा कारणों से यह ऐप केवल एक टैब में उपयोग करें।</p>
        </div>
      )}

      {showEmailModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className="bg-white rounded-[3rem] p-8 max-w-md w-full shadow-2xl border-4 border-orange-100 text-center animate-fade-in">
             <div className="w-20 h-20 bg-orange-100 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl">🎓</div>
             <h2 className="text-3xl font-black text-orange-900 mb-2">स्वागत है</h2>
             <p className="text-gray-500 font-medium mb-8 leading-tight">ऐप शुरू करने के लिए अपना Gmail और मोबाइल नंबर दर्ज करें।</p>
             <form onSubmit={handleUserSubmit} className="space-y-4">
                <input type="email" required placeholder="Gmail ID..." value={emailInput} onChange={(e) => setEmailInput(e.target.value)} className="w-full py-4 px-6 rounded-2xl border-2 border-orange-100 focus:border-orange-600 focus:outline-none text-lg font-bold shadow-inner" />
                <input type="tel" required placeholder="Mobile Number..." value={phoneInput} onChange={(e) => setPhoneInput(e.target.value)} className="w-full py-4 px-6 rounded-2xl border-2 border-orange-100 focus:border-orange-600 focus:outline-none text-lg font-bold shadow-inner" />
                <button type="submit" className="w-full py-4 bg-orange-600 hover:bg-orange-700 text-white font-black rounded-2xl shadow-xl transition-transform active:scale-95 uppercase tracking-widest">प्रवेश करें</button>
             </form>
          </div>
        </div>
      )}

      <header className={`w-full p-4 flex justify-between items-center text-white shadow-md z-30 sticky top-0 transition-colors duration-300 ${quiz?.isExamMode ? 'bg-slate-800' : 'bg-orange-600'}`}>
        <span className="font-bold text-lg cursor-pointer flex items-center gap-2" onClick={() => handleNav('LANDING')}>
          <span className="bg-white text-orange-600 w-8 h-8 rounded-full flex items-center justify-center font-black">इ</span>
        </span>
        <div className="flex gap-2 items-center">
          {dailyStreak > 0 && <div className="flex items-center gap-1 bg-white/20 px-3 py-1 rounded-full text-[10px] font-black">🔥 {dailyStreak}</div>}
          <button onClick={() => handleNav('BOOKMARKS')} className="bg-white/20 p-1.5 rounded-full"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg></button>
          <button onClick={() => handleNav('SETTINGS')} className="p-1.5 hover:bg-white/10 rounded-full"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /></svg></button>
        </div>
      </header>

      <main className="flex-1 w-full max-w-2xl px-4 py-8 flex flex-col items-center justify-center">
        {appState === 'LANDING' && (
          <div className="text-center animate-fade-in py-10 w-full">
            <h1 className="text-7xl md:text-9xl font-black text-orange-600 mb-2 hindi-font tracking-tighter">{INTRO_MAIN}</h1>
            <p className="text-xl md:text-3xl text-orange-800 font-bold mb-12 italic opacity-80">"{INTRO_SUB}"</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-2xl mx-auto mb-12">
              <div className="p-6 rounded-[2.5rem] border-4 shadow-xl text-left bg-white border-orange-100 flex flex-col justify-between h-56">
                <div>
                  <span className="text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full bg-orange-100 text-orange-600">{t.dailyQuiz}</span>
                  <h3 className="text-2xl font-black text-gray-900 mt-4 leading-tight">{t.dailyGoal}</h3>
                </div>
                {!isDailyDone ? <button onClick={startDailyQuiz} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-lg transition active:scale-95 uppercase tracking-widest text-sm">{t.start}</button> : <div className="text-indigo-600 font-black">आज का लक्ष्य पूर्ण! ✅</div>}
              </div>

              <div className={`p-6 rounded-[2.5rem] border-4 shadow-xl text-left flex flex-col justify-between h-56 transition-all ${examStatus === 'LIVE' ? 'border-indigo-400 bg-indigo-900' : 'border-slate-100 bg-slate-900'}`}>
                 <div>
                    <div className="flex justify-between items-start">
                       <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${examStatus === 'LIVE' ? 'bg-red-600 text-white animate-pulse' : 'bg-slate-700 text-white'}`}>
                          {examStatus === 'LIVE' ? 'LIVE NOW' : 'LIVE EXAM'}
                       </span>
                    </div>
                    <h3 className="text-2xl font-black mt-4 text-white">रविवार 11:00 AM</h3>
                    <p className="text-xs font-bold mt-1 text-slate-400">
                      {examStatus === 'UPCOMING' ? `शुरू होगा: ${formatTime(timeToExam)}` : 
                       examStatus === 'LIVE' ? `समय शेष: ${formatTime(timeToExam)}` : 
                       'प्रत्येक रविवार 11 से 12 बजे'}
                    </p>
                 </div>
                 <button onClick={() => startQuiz(Difficulty.EXAM)} disabled={examStatus !== 'LIVE'} className={`w-full py-4 font-black rounded-2xl shadow-lg transition uppercase tracking-widest text-sm ${examStatus === 'LIVE' ? 'bg-white text-slate-900 active:scale-95' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}>
                    {examStatus === 'LIVE' ? 'अभी शामिल हों' : 'Locked'}
                 </button>
              </div>
            </div>

            <div className="space-y-4 max-w-sm mx-auto">
              <button onClick={() => handleNav('DIFFICULTY_SELECT')} className="w-full py-5 px-8 bg-orange-600 hover:bg-orange-700 text-white font-black text-2xl rounded-3xl shadow-2xl transform hover:scale-105 transition-all uppercase tracking-widest">{t.start}</button>
              <div className="grid grid-cols-2 gap-4">
                <button onClick={() => handleNav('BOOKMARKS')} className="w-full py-3 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl">🔖 {t.bookmarks}</button>
                <button onClick={() => handleNav('HISTORY')} className="w-full py-3 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl">📜 {t.history}</button>
              </div>
            </div>
          </div>
        )}

        {appState === 'QUIZ' && quiz && (
          <div className="w-full pb-20 animate-fade-in">
            {loading ? <div className="text-center py-20 font-black text-orange-600 animate-pulse">इतिहास के पन्नों को खोजा जा रहा है...</div> : (
              <div className="space-y-8">
                <div className="flex justify-between items-center text-orange-900 font-black text-[10px] uppercase tracking-widest">
                  <span className="flex items-center gap-1"><span className="w-2 h-2 bg-green-500 rounded-full animate-ping"></span> Live: {liveParticipants.toLocaleString()}</span>
                  {quiz.isExamMode && <span className="text-red-600 bg-red-50 px-3 py-1 rounded-full border border-red-100">🚫 एंटी-चीट सक्रिय</span>}
                </div>
                <div className="w-full bg-orange-100 h-3 rounded-full overflow-hidden border border-orange-200">
                  <div className={`h-full transition-all duration-300 ${quiz.isExamMode ? 'bg-slate-800' : 'bg-orange-600'}`} style={{ width: `${((quiz.currentIndex + 1) / quiz.totalQuestions) * 100}%` }}></div>
                </div>
                <div className="flex justify-between items-center text-sm font-black text-orange-900">
                  <span className="opacity-50">{quiz.isExamMode ? 'LIVE EXAM' : t[quiz.difficulty]}</span>
                  <span className={`text-lg font-mono ${quiz.timeRemaining < 60 ? 'text-red-600 animate-pulse' : ''}`}>{formatTime(quiz.timeRemaining)}</span>
                  <span className="text-lg">{`${quiz.currentIndex + 1} / ${quiz.totalQuestions}`}</span>
                </div>
                <h2 className="text-3xl font-black text-gray-900 leading-tight hindi-font">{quiz.questions[quiz.currentIndex].text}</h2>
                <div className="grid grid-cols-1 gap-4">
                  {quiz.questions[quiz.currentIndex].options.map((option, idx) => (
                    <button key={idx} onClick={() => handleAnswer(idx)} disabled={selectedAnswer !== null} className={`p-5 text-left rounded-3xl border-4 transition-all flex items-center ${selectedAnswer === null ? 'border-orange-50 bg-white hover:border-orange-600' : (idx === quiz.questions[quiz.currentIndex].correctAnswer && !quiz.isExamMode) ? 'border-green-600 bg-green-50' : (selectedAnswer === idx && !quiz.isExamMode) ? 'border-red-600 bg-red-50' : quiz.isExamMode && selectedAnswer === idx ? 'border-slate-800 bg-slate-50' : 'opacity-40 grayscale'}`}>
                      <span className={`w-10 h-10 rounded-full flex items-center justify-center font-black mr-4 text-lg ${selectedAnswer === null ? 'bg-orange-50 text-orange-600' : (idx === quiz.questions[quiz.currentIndex].correctAnswer && !quiz.isExamMode) ? 'bg-green-600 text-white' : 'bg-gray-200'}`}>{String.fromCharCode(65 + idx)}</span>
                      <span className="text-xl font-bold">{option}</span>
                    </button>
                  ))}
                </div>
                {showExplanation && !quiz.isExamMode && (
                  <div className="p-8 bg-blue-50 border-4 border-blue-600 rounded-[2.5rem] shadow-xl">
                    <p className="text-blue-800 text-lg mb-6">{quiz.questions[quiz.currentIndex].explanation}</p>
                    <button onClick={() => { setShowExplanation(false); setSelectedAnswer(null); if (quiz.currentIndex + 1 < quiz.totalQuestions) setQuiz(p => p ? ({ ...p, currentIndex: p.currentIndex + 1 }) : null); else finishQuiz(); }} className="w-full bg-blue-600 text-white font-black py-5 rounded-3xl uppercase tracking-widest">{t.next}</button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {appState === 'RESULT' && (
          <div className="text-center space-y-10 animate-fade-in w-full py-10">
             {disqualified ? (
                 <div className="bg-red-50 border-4 border-red-600 p-8 rounded-[3rem] shadow-2xl">
                     <div className="text-8xl mb-4">⛔</div>
                     <h2 className="text-4xl font-black text-red-700 mb-2">अयोग्य घोषित</h2>
                     <p className="text-red-900 font-bold opacity-80">परीक्षा के नियमों का उल्लंघन हुआ है।</p>
                 </div>
             ) : (
                <div className="w-full bg-white rounded-[3rem] p-6 shadow-2xl border-4 border-orange-50">
                   <h3 className="text-3xl font-black text-orange-900 mb-6">🏆 लीडरबोर्ड (Rank List)</h3>
                   <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2">
                      {leaderboard.map((p) => (
                        <div key={p.rank} className={`flex items-center justify-between p-4 rounded-2xl border-2 ${p.isUser ? 'bg-orange-600 text-white scale-105' : 'bg-white'}`}>
                           <div className="flex items-center gap-4">
                              <span className="font-black text-lg">{p.rank}</span>
                              <div className="text-left">
                                 <p className="font-black">{p.name}</p>
                                 <p className="text-[10px] opacity-70">समय: {formatTime(p.timeTaken)}</p>
                              </div>
                           </div>
                           <span className="font-black text-xl">{p.score}</span>
                        </div>
                      ))}
                   </div>
                </div>
             )}
             <button onClick={() => handleNav('LANDING')} className="w-full py-4 bg-orange-600 text-white font-black rounded-3xl shadow-xl uppercase">मुख्य पृष्ठ</button>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { AppState, Language, Question, QuizState, Difficulty, HistoryEntry } from './types';
import { fetchQuestions } from './services/geminiService';
import { APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES, DAILY_QUIZ_COUNT } from './constants';

const BOOKMARKS_KEY = 'history_bookmarks';
const HISTORY_KEY = 'quiz_history_data';
const ACTIVE_QUIZ_KEY = 'active_quiz_session';
const DAILY_STATS_KEY = 'daily_stats_v1';
const USER_EMAIL_KEY = 'user_gmail_id';
const USER_PHONE_KEY = 'user_phone_number';

const HINDI_NAMES = [
  "आदित्य शर्मा", "प्रिया पटेल", "राहुल वर्मा", "अंजली सिंह", "संदीप यादव",
  "नेहा गुप्ता", "विकास मिश्रा", "पूजा तिवारी", "अमित राज", "स्नेहा रेड्डी",
  "मनीष बिष्ट", "कविता जोशी", "रोहित मेहरा", "दीपिका पादुकोण", "ऋषभ पंत",
  "श्रेया घोषाल", "अरुण जेटली", "स्मृति ईरानी", "नितिन गडकरी", "शिवानी सिंह",
  "योगेश कुमार", "मंजू कुमारी", "सुनील छेत्री", "साइना नेहवाल"
];

const formatTime = (seconds: number): string => {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  if (h > 0) return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  return `${m}:${s.toString().padStart(2, '0')}`;
};

type ExamStatus = 'LOCKED' | 'UPCOMING' | 'LIVE' | 'CLOSED';

interface LeaderboardEntry {
  name: string;
  score: number;
  timeTaken: number;
  rank: number;
  isUser?: boolean;
  isRisingStar?: boolean;
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState | null>(null);
  const [bookmarks, setBookmarks] = useState<Question[]>([]);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [liveParticipants, setLiveParticipants] = useState(0);
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>([]);
  const [isRisingStar, setIsRisingStar] = useState(false);

  // Security & Live Schedule States
  const [isTabActive, setIsTabActive] = useState(true);
  const [multiTabError, setMultiTabError] = useState(false);
  const [disqualified, setDisqualified] = useState(false);
  const [examStatus, setExamStatus] = useState<ExamStatus>('LOCKED');
  const [timeToExam, setTimeToExam] = useState(0); // Seconds until 11 AM or 12 PM

  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [userPhone, setUserPhone] = useState<string | null>(null);
  const [emailInput, setEmailInput] = useState("");
  const [phoneInput, setPhoneInput] = useState("");
  const [showEmailModal, setShowEmailModal] = useState(false);

  const [dailyStreak, setDailyStreak] = useState(0);
  const [lastDailyDate, setLastDailyDate] = useState<string | null>(null);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);
  const sessionRef = useRef(Math.random().toString(36).substring(7));

  const t = useMemo(() => TRANSLATIONS[language] || TRANSLATIONS[Language.ENGLISH], [language]);

  const isDailyDone = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    return lastDailyDate === todayStr;
  }, [lastDailyDate]);

  // --- LIVE SCHEDULE LOGIC ---
  const checkExamWindow = useCallback(() => {
    const now = new Date();
    const day = now.getDay(); // 0 is Sunday
    const hours = now.getHours();
    const minutes = now.getMinutes();
    const currentTimeInMins = hours * 60 + minutes;

    const startMins = 11 * 60; // 11:00 AM
    const endMins = 12 * 60;   // 12:00 PM

    if (day !== 0) {
      setExamStatus('LOCKED');
      return;
    }

    if (currentTimeInMins < startMins) {
      setExamStatus('UPCOMING');
      setTimeToExam((startMins - currentTimeInMins) * 60 - now.getSeconds());
    } else if (currentTimeInMins >= startMins && currentTimeInMins < endMins) {
      setExamStatus('LIVE');
      setTimeToExam((endMins - currentTimeInMins) * 60 - now.getSeconds());
    } else {
      setExamStatus('CLOSED');
    }
  }, []);

  useEffect(() => {
    checkExamWindow();
    const interval = setInterval(checkExamWindow, 1000);
    return () => clearInterval(interval);
  }, [checkExamWindow]);

  // --- ANTI-CHEAT LOGIC ---
  useEffect(() => {
    const channel = new BroadcastChannel('quiz_session_sync');
    channel.postMessage({ type: 'NEW_SESSION', id: sessionRef.current });
    channel.onmessage = (event) => {
      if (event.data.type === 'NEW_SESSION') {
        setMultiTabError(true);
        if (appState === 'QUIZ' && quiz?.isExamMode) setDisqualified(true);
      }
    };
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();
    const handleKeydown = (e: KeyboardEvent) => {
      if (e.key === 'PrintScreen' || (e.ctrlKey && ['c','u','s','p','i','j'].includes(e.key.toLowerCase()))) {
        e.preventDefault();
        alert("सुरक्षा प्रोटोकॉल: यह क्रिया वर्जित है।");
      }
    };
    window.addEventListener('contextmenu', handleContextMenu);
    window.addEventListener('keydown', handleKeydown);
    const handleVisibilityChange = () => {
      const active = document.visibilityState === 'visible';
      setIsTabActive(active);
      if (!active && appState === 'QUIZ' && quiz?.isExamMode) {
        setDisqualified(true);
        finishQuiz();
      }
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      channel.close();
      window.removeEventListener('contextmenu', handleContextMenu);
      window.removeEventListener('keydown', handleKeydown);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [appState, quiz?.isExamMode]);

  // --- REGULAR LOGIC ---
  useEffect(() => {
    if (appState === 'QUIZ') {
      const base = quiz?.isExamMode ? 1200 : 45;
      const initial = base + Math.floor(Math.random() * 50);
      setLiveParticipants(initial);
      const interval = setInterval(() => {
        setLiveParticipants(prev => Math.max(prev + (Math.random() > 0.5 ? 2 : -2), 10));
      }, 3000);
      return () => clearInterval(interval);
    }
  }, [appState, quiz?.isExamMode]);

  const playSound = useCallback((type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      const now = ctx.currentTime;
      if (type === 'correct') {
        osc.frequency.setValueAtTime(523, now); osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
        gain.gain.setValueAtTime(0.1, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
      } else if (type === 'incorrect') {
        osc.type = 'sawtooth'; osc.frequency.setValueAtTime(220, now);
        gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
      } else {
        osc.frequency.setValueAtTime(800, now); gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
      }
      osc.start(now); osc.stop(now + 0.3);
    } catch (e) {}
  }, [soundEnabled]);

  const handleNav = useCallback((state: AppState) => {
    playSound('nav');
    setAppState(state);
    if (state !== 'QUIZ') syncRef.current = false;
  }, [playSound]);

  useEffect(() => {
    const savedEmail = localStorage.getItem(USER_EMAIL_KEY);
    const savedPhone = localStorage.getItem(USER_PHONE_KEY);
    if (savedEmail && savedPhone) { setUserEmail(savedEmail); setUserPhone(savedPhone); } else { setShowEmailModal(true); }
    const savedBookmarks = localStorage.getItem(BOOKMARKS_KEY);
    if (savedBookmarks) try { setBookmarks(JSON.parse(savedBookmarks)); } catch (e) {}
    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) try { setHistory(JSON.parse(savedHistory)); } catch (e) {}
    const savedStats = localStorage.getItem(DAILY_STATS_KEY);
    if (savedStats) try { const stats = JSON.parse(savedStats); setDailyStreak(stats.streak || 0); setLastDailyDate(stats.lastDate || null); } catch (e) {}
  }, []);

  const handleUserSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (emailInput.includes('@') && phoneInput.length >= 10) {
      localStorage.setItem(USER_EMAIL_KEY, emailInput);
      localStorage.setItem(USER_PHONE_KEY, phoneInput);
      setUserEmail(emailInput); setUserPhone(phoneInput);
      setShowEmailModal(false); playSound('correct');
    }
  };

  useEffect(() => { localStorage.setItem(BOOKMARKS_KEY, JSON.stringify(bookmarks)); }, [bookmarks]);
  useEffect(() => { localStorage.setItem(HISTORY_KEY, JSON.stringify(history)); }, [history]);

  useEffect(() => {
    if (appState === 'QUIZ' && quiz && quiz.timeRemaining > 0 && !loading && !disqualified) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (!prev) return null;
          // Forced exit at 12:00 PM logic for Exam Mode
          if (prev.isExamMode && examStatus === 'CLOSED') {
             clearInterval(timerRef.current!);
             finishQuiz();
             return null;
          }
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [appState, loading, quiz?.timeRemaining, disqualified, examStatus]);

  const generateLeaderboard = useCallback((userScore: number, totalQuestions: number, userTimeSeconds: number, userIsRisingStar: boolean) => {
    const participants: LeaderboardEntry[] = [];
    const shuffledNames = [...HINDI_NAMES].sort(() => 0.5 - Math.random());
    for (let i = 0; i < 25; i++) {
      let score = totalQuestions - Math.floor(Math.random() * (totalQuestions * 0.3));
      // Randomly assign Rising Star to 2 other participants to make it feel natural
      const isSimulatedRisingStar = Math.random() > 0.85;
      participants.push({ 
        name: shuffledNames[i] || `प्रतियोगी ${i}`, 
        score, 
        timeTaken: score * 15 + Math.random() * 60,
        rank: 0,
        isRisingStar: isSimulatedRisingStar 
      });
    }
    if (!disqualified) participants.push({ 
      name: userEmail?.split('@')[0] || "आप", 
      score: userScore, 
      timeTaken: userTimeSeconds, 
      isUser: true, 
      rank: 0,
      isRisingStar: userIsRisingStar 
    });

    const sorted = participants.sort((a, b) => b.score !== a.score ? b.score - a.score : a.timeTaken - b.timeTaken).slice(0, 20);
    setLeaderboard(sorted.map((p, idx) => ({ ...p, rank: idx + 1 })));
  }, [userEmail, disqualified]);

  const calculateRisingStarStatus = useCallback((currentScore: number, currentTotal: number) => {
    if (history.length < 2) return false;

    // Calculate historical average accuracy
    const totalScore = history.reduce((sum, entry) => sum + entry.score, 0);
    const totalQuestions = history.reduce((sum, entry) => sum + entry.total, 0);
    const avgAccuracy = totalScore / totalQuestions;

    const currentAccuracy = currentScore / currentTotal;

    // "Rising Star" if current accuracy is 30% better than historical average
    // or if historical average was low (<50%) and current is high (>80%)
    return (currentAccuracy > avgAccuracy * 1.3) || (avgAccuracy < 0.5 && currentAccuracy > 0.8);
  }, [history]);

  const finishQuiz = useCallback((attempted?: number) => {
    setQuiz(prev => {
        if (!prev) return null;
        const finalAttempted = attempted ?? (prev.currentIndex + 1);
        const difficultyConfig = DIFFICULTIES.find(d => d.code === prev.difficulty);
        const totalTimeAllowed = prev.isDailyMode ? 1200 : (difficultyConfig?.time || 0);
        const userTimeTaken = totalTimeAllowed - prev.timeRemaining;

        const userRisingStar = calculateRisingStarStatus(prev.score, finalAttempted);
        setIsRisingStar(userRisingStar);

        const newEntry: HistoryEntry = {
          id: Date.now().toString(),
          difficulty: prev.isDailyMode ? 'DAILY' : prev.difficulty,
          score: disqualified ? 0 : prev.score,
          total: finalAttempted,
          skipped: prev.skippedCount,
          date: new Date().toLocaleString(),
          isChallenge: prev.isChallengeMode
        };

        setHistory(h => [newEntry, ...h].slice(0, 50)); 
        generateLeaderboard(disqualified ? 0 : prev.score, finalAttempted, userTimeTaken, userRisingStar);
        setAppState('RESULT');
        return null;
    });
  }, [disqualified, generateLeaderboard, calculateRisingStarStatus]);

  const handleTimeUp = useCallback(() => { playSound('incorrect'); finishQuiz(); }, [playSound, finishQuiz]);

  const backgroundSync = useCallback(async (difficulty: Difficulty, target: number, currentLang: Language, existingCount: number, isDaily: boolean = false) => {
    if (syncRef.current) return; syncRef.current = true;
    let currentCount = existingCount;
    while (currentCount < target && syncRef.current) {
      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, 30, isDaily);
        if (moreQuestions.length === 0) break;
        setQuiz(prev => {
          if (!prev) return null;
          const uniqueNew = moreQuestions.filter(mq => !prev.questions.some(pq => pq.text === mq.text));
          return { ...prev, questions: [...prev.questions, ...uniqueNew] };
        });
        currentCount += moreQuestions.length;
      } catch (err) { break; }
      await new Promise(r => setTimeout(r, 2000));
    }
    syncRef.current = false;
  }, []);

  const startQuiz = useCallback(async (difficulty: Difficulty) => {
    if (difficulty === Difficulty.EXAM && examStatus !== 'LIVE') return;
    playSound('nav'); setDisqualified(false); setIsRisingStar(false);
    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true); syncRef.current = true;
    const initialQuestions = await fetchQuestions(language, difficulty, 15);

    // For live exam, ensure they don't get more time than remains until 12:00 PM
    let timeLimit = config.time;
    if (difficulty === Difficulty.EXAM) {
      const now = new Date();
      const endWindow = new Date(); endWindow.setHours(12, 0, 0, 0);
      const remainingWindowSecs = Math.floor((endWindow.getTime() - now.getTime()) / 1000);
      timeLimit = Math.min(config.time, remainingWindowSecs);
    }

    setQuiz({
      questions: initialQuestions, currentIndex: 0, score: 0, skippedCount: 0, skipsRemaining: config.maxSkips,
      isComplete: false, difficulty, timeRemaining: timeLimit, totalQuestions: config.count,
      isChallengeMode: difficulty === Difficulty.CHALLENGE, isExamMode: difficulty === Difficulty.EXAM
    });
    setLoading(false); setAppState('QUIZ');
    backgroundSync(difficulty, config.count, language, 15);
  }, [examStatus, playSound, language, backgroundSync]);

  const startDailyQuiz = useCallback(async () => {
    if (isDailyDone) return; playSound('nav'); setLoading(true); syncRef.current = true; setIsRisingStar(false);
    const initialQuestions = await fetchQuestions(language, Difficulty.MEDIUM, 10, true);
    setQuiz({
      questions: initialQuestions, currentIndex: 0, score: 0, skippedCount: 0, skipsRemaining: 10,
      isComplete: false, difficulty: Difficulty.MEDIUM, timeRemaining: 1200, totalQuestions: DAILY_QUIZ_COUNT, isDailyMode: true
    });
    setLoading(false); setAppState('QUIZ');
    backgroundSync(Difficulty.MEDIUM, DAILY_QUIZ_COUNT, language, 10, true);
  }, [isDailyDone, playSound, language, backgroundSync]);

  const handleAnswer = useCallback((index: number) => {
    if (!quiz || selectedAnswer !== null || disqualified) return;
    setSelectedAnswer(index);
    if (quiz.isExamMode) {
      playSound('nav');
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) setQuiz(p => p ? ({ ...p, score: p.score + 1 }) : null);
      setTimeout(() => { setSelectedAnswer(null); if (quiz.currentIndex + 1 < quiz.totalQuestions) setQuiz(p => p ? ({ ...p, currentIndex: p.currentIndex + 1 }) : null); else finishQuiz(); }, 300);
    } else {
      setShowExplanation(true);
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) { playSound('correct'); setQuiz(p => p ? ({ ...p, score: p.score + 1 }) : null); } else playSound('incorrect');
    }
  }, [quiz, selectedAnswer, disqualified, playSound, finishQuiz]);

  const toggleBookmark = useCallback((q: Question) => {
    if (quiz?.isExamMode) return; playSound('nav');
    setBookmarks(prev => prev.find(b => b.id === q.id) ? prev.filter(b => b.id !== q.id) : [...prev, q]);
  }, [quiz?.isExamMode, playSound]);

  return (
    <div className={`min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800 transition-all duration-300 select-none ${!isTabActive ? 'blur-2xl grayscale' : ''}`}>

      {multiTabError && (
        <div className="fixed inset-0 z-[200] bg-orange-950 flex flex-col items-center justify-center p-8 text-center text-white">
           <div className="text-8xl mb-6">🚫</div>
           <h2 className="text-4xl font-black mb-4">एकाधिक टैब का पता चला</h2>
           <p className="text-xl max-w-md opacity-80">सुरक्षा कारणों से यह ऐप केवल एक टैब में उपयोग करें।</p>
        </div>
      )}

      {showEmailModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className="bg-white rounded-[3rem] p-8 max-w-md w-full shadow-2xl border-4 border-orange-100 text-center animate-fade-in">
             <div className="w-20 h-20 bg-orange-100 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl">🎓</div>
             <h2 className="text-3xl font-black text-orange-900 mb-2">स्वागत है</h2>
             <p className="text-gray-500 font-medium mb-8 leading-tight">ऐप शुरू करने के लिए अपना Gmail और मोबाइल नंबर दर्ज करें।</p>
             <form onSubmit={handleUserSubmit} className="space-y-4">
                <input type="email" required placeholder="Gmail ID..." value={emailInput} onChange={(e) => setEmailInput(e.target.value)} className="w-full py-4 px-6 rounded-2xl border-2 border-orange-100 focus:border-orange-600 focus:outline-none text-lg font-bold shadow-inner" />
                <input type="tel" required placeholder="Mobile Number..." value={phoneInput} onChange={(e) => setPhoneInput(e.target.value)} className="w-full py-4 px-6 rounded-2xl border-2 border-orange-100 focus:border-orange-600 focus:outline-none text-lg font-bold shadow-inner" />
                <button type="submit" className="w-full py-4 bg-orange-600 hover:bg-orange-700 text-white font-black rounded-2xl shadow-xl transition-transform active:scale-95 uppercase tracking-widest">प्रवेश करें</button>
             </form>
          </div>
        </div>
      )}

      <header className={`w-full p-4 flex justify-between items-center text-white shadow-md z-30 sticky top-0 transition-colors duration-300 ${quiz?.isExamMode ? 'bg-slate-800' : 'bg-orange-600'}`}>
        <span className="font-bold text-lg cursor-pointer flex items-center gap-2" onClick={() => handleNav('LANDING')}>
          <span className="bg-white text-orange-600 w-8 h-8 rounded-full flex items-center justify-center font-black">इ</span>
        </span>
        <div className="flex gap-2 items-center">
          {dailyStreak > 0 && <div className="flex items-center gap-1 bg-white/20 px-3 py-1 rounded-full text-[10px] font-black">🔥 {dailyStreak}</div>}
          <button onClick={() => handleNav('BOOKMARKS')} className="bg-white/20 p-1.5 rounded-full"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="currentColor" viewBox="0 0 24 24"><path d="M17 3H7c-1.1 0-2 .9-2 2v16l7-3 7 3V5c0-1.1-.9-2-2-2z"/></svg></button>
          <button onClick={() => handleNav('SETTINGS')} className="p-1.5 hover:bg-white/10 rounded-full"><svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /></svg></button>
        </div>
      </header>

      <main className="flex-1 w-full max-w-2xl px-4 py-8 flex flex-col items-center justify-center">
        {appState === 'LANDING' && (
          <div className="text-center animate-fade-in py-10 w-full">
            <h1 className="text-7xl md:text-9xl font-black text-orange-600 mb-2 hindi-font tracking-tighter">{INTRO_MAIN}</h1>
            <p className="text-xl md:text-3xl text-orange-800 font-bold mb-12 italic opacity-80">"{INTRO_SUB}"</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-2xl mx-auto mb-12">
              <div className="p-6 rounded-[2.5rem] border-4 shadow-xl text-left bg-white border-orange-100 flex flex-col justify-between h-56">
                <div>
                  <span className="text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full bg-orange-100 text-orange-600">{t.dailyQuiz}</span>
                  <h3 className="text-2xl font-black text-gray-900 mt-4 leading-tight">{t.dailyGoal}</h3>
                </div>
                {!isDailyDone ? <button onClick={startDailyQuiz} className="w-full py-4 bg-indigo-600 text-white font-black rounded-2xl shadow-lg transition active:scale-95 uppercase tracking-widest text-sm">{t.start}</button> : <div className="text-indigo-600 font-black">आज का लक्ष्य पूर्ण! ✅</div>}
              </div>

              <div className={`p-6 rounded-[2.5rem] border-4 shadow-xl text-left flex flex-col justify-between h-56 transition-all ${examStatus === 'LIVE' ? 'border-indigo-400 bg-indigo-900' : 'border-slate-100 bg-slate-900'}`}>
                 <div>
                    <div className="flex justify-between items-start">
                       <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${examStatus === 'LIVE' ? 'bg-red-600 text-white animate-pulse' : 'bg-slate-700 text-white'}`}>
                          {examStatus === 'LIVE' ? 'LIVE NOW' : 'LIVE EXAM'}
                       </span>
                    </div>
                    <h3 className="text-2xl font-black mt-4 text-white">रविवार 11:00 AM</h3>
                    <p className="text-xs font-bold mt-1 text-slate-400">
                      {examStatus === 'UPCOMING' ? `शुरू होगा: ${formatTime(timeToExam)}` : 
                       examStatus === 'LIVE' ? `समय शेष: ${formatTime(timeToExam)}` : 
                       'प्रत्येक रविवार 11 से 12 बजे'}
                    </p>
                 </div>
                 <button onClick={() => startQuiz(Difficulty.EXAM)} disabled={examStatus !== 'LIVE'} className={`w-full py-4 font-black rounded-2xl shadow-lg transition uppercase tracking-widest text-sm ${examStatus === 'LIVE' ? 'bg-white text-slate-900 active:scale-95' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}>
                    {examStatus === 'LIVE' ? 'अभी शामिल हों' : 'Locked'}
                 </button>
              </div>
            </div>

            <div className="space-y-4 max-w-sm mx-auto">
              <button onClick={() => handleNav('DIFFICULTY_SELECT')} className="w-full py-5 px-8 bg-orange-600 hover:bg-orange-700 text-white font-black text-2xl rounded-3xl shadow-2xl transform hover:scale-105 transition-all uppercase tracking-widest">{t.start}</button>
              <div className="grid grid-cols-2 gap-4">
                <button onClick={() => handleNav('BOOKMARKS')} className="w-full py-3 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl">🔖 {t.bookmarks}</button>
                <button onClick={() => handleNav('HISTORY')} className="w-full py-3 bg-white border-4 border-orange-100 text-orange-800 font-bold rounded-2xl">📜 {t.history}</button>
              </div>
            </div>
          </div>
        )}

        {appState === 'QUIZ' && quiz && (
          <div className="w-full pb-20 animate-fade-in">
            {loading ? <div className="text-center py-20 font-black text-orange-600 animate-pulse">इतिहास के पन्नों को खोजा जा रहा है...</div> : (
              <div className="space-y-8">
                <div className="flex justify-between items-center text-orange-900 font-black text-[10px] uppercase tracking-widest">
                  <span className="flex items-center gap-1"><span className="w-2 h-2 bg-green-500 rounded-full animate-ping"></span> Live: {liveParticipants.toLocaleString()}</span>
                  {quiz.isExamMode && <span className="text-red-600 bg-red-50 px-3 py-1 rounded-full border border-red-100">🚫 एंटी-चीट सक्रिय</span>}
                </div>
                <div className="w-full bg-orange-100 h-3 rounded-full overflow-hidden border border-orange-200">
                  <div className={`h-full transition-all duration-300 ${quiz.isExamMode ? 'bg-slate-800' : 'bg-orange-600'}`} style={{ width: `${((quiz.currentIndex + 1) / quiz.totalQuestions) * 100}%` }}></div>
                </div>
                <div className="flex justify-between items-center text-sm font-black text-orange-900">
                  <span className="opacity-50">{quiz.isExamMode ? 'LIVE EXAM' : t[quiz.difficulty]}</span>
                  <span className={`text-lg font-mono ${quiz.timeRemaining < 60 ? 'text-red-600 animate-pulse' : ''}`}>{formatTime(quiz.timeRemaining)}</span>
                  <span className="text-lg">{`${quiz.currentIndex + 1} / ${quiz.totalQuestions}`}</span>
                </div>
                <h2 className="text-3xl font-black text-gray-900 leading-tight hindi-font">{quiz.questions[quiz.currentIndex].text}</h2>
                <div className="grid grid-cols-1 gap-4">
                  {quiz.questions[quiz.currentIndex].options.map((option, idx) => (
                    <button key={idx} onClick={() => handleAnswer(idx)} disabled={selectedAnswer !== null} className={`p-5 text-left rounded-3xl border-4 transition-all flex items-center ${selectedAnswer === null ? 'border-orange-50 bg-white hover:border-orange-600' : (idx === quiz.questions[quiz.currentIndex].correctAnswer && !quiz.isExamMode) ? 'border-green-600 bg-green-50' : (selectedAnswer === idx && !quiz.isExamMode) ? 'border-red-600 bg-red-50' : quiz.isExamMode && selectedAnswer === idx ? 'border-slate-800 bg-slate-50' : 'opacity-40 grayscale'}`}>
                      <span className={`w-10 h-10 rounded-full flex items-center justify-center font-black mr-4 text-lg ${selectedAnswer === null ? 'bg-orange-50 text-orange-600' : (idx === quiz.questions[quiz.currentIndex].correctAnswer && !quiz.isExamMode) ? 'bg-green-600 text-white' : 'bg-gray-200'}`}>{String.fromCharCode(65 + idx)}</span>
                      <span className="text-xl font-bold">{option}</span>
                    </button>
                  ))}
                </div>
                {showExplanation && !quiz.isExamMode && (
                  <div className="p-8 bg-blue-50 border-4 border-blue-600 rounded-[2.5rem] shadow-xl">
                    <p className="text-blue-800 text-lg mb-6">{quiz.questions[quiz.currentIndex].explanation}</p>
                    <button onClick={() => { setShowExplanation(false); setSelectedAnswer(null); if (quiz.currentIndex + 1 < quiz.totalQuestions) setQuiz(p => p ? ({ ...p, currentIndex: p.currentIndex + 1 }) : null); else finishQuiz(); }} className="w-full bg-blue-600 text-white font-black py-5 rounded-3xl uppercase tracking-widest">{t.next}</button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {appState === 'RESULT' && (
          <div className="text-center space-y-10 animate-fade-in w-full py-10">
             {disqualified ? (
                 <div className="bg-red-50 border-4 border-red-600 p-8 rounded-[3rem] shadow-2xl">
                     <div className="text-8xl mb-4">⛔</div>
                     <h2 className="text-4xl font-black text-red-700 mb-2">अयोग्य घोषित</h2>
                     <p className="text-red-900 font-bold opacity-80">परीक्षा के नियमों का उल्लंघन हुआ है।</p>
                 </div>
             ) : (
                <div className="space-y-8">
                   {isRisingStar && (
                      <div className="bg-gradient-to-r from-yellow-400 via-orange-500 to-yellow-400 p-1 rounded-[3rem] animate-pulse shadow-2xl">
                         <div className="bg-white p-6 rounded-[2.8rem] flex flex-col items-center">
                            <span className="text-6xl mb-2">🌟</span>
                            <h2 className="text-4xl font-black text-orange-600 tracking-tighter">राइजिंग स्टार (Rising Star)</h2>
                            <p className="text-gray-500 font-bold mt-1 leading-tight">आपने पिछले प्रदर्शन की तुलना में बेहतरीन सुधार दिखाया है!</p>
                         </div>
                      </div>
                   )}

                   <div className="w-full bg-white rounded-[3rem] p-6 shadow-2xl border-4 border-orange-50">
                      <h3 className="text-3xl font-black text-orange-900 mb-6">🏆 लीडरबोर्ड (Rank List)</h3>
                      <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 scrollbar-thin">
                         {leaderboard.map((p) => (
                           <div key={`${p.name}-${p.rank}`} className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all duration-300 ${p.isUser ? 'bg-orange-600 text-white scale-[1.03] shadow-lg ring-4 ring-orange-100' : 'bg-white border-orange-50'}`}>
                              <div className="flex items-center gap-4">
                                 <span className={`font-black text-lg w-8 h-8 rounded-full flex items-center justify-center ${p.rank <= 3 ? 'bg-yellow-400 text-yellow-900' : p.isUser ? 'bg-white/20' : 'bg-gray-100'}`}>{p.rank}</span>
                                 <div className="text-left">
                                    <div className="flex items-center gap-2">
                                       <p className="font-black truncate max-w-[120px]">{p.name}</p>
                                       {p.isRisingStar && <span className="bg-orange-100 text-orange-600 text-[8px] font-black px-1.5 py-0.5 rounded-full border border-orange-200 flex items-center gap-1 animate-bounce">🌟 STAR</span>}
                                    </div>
                                    <p className={`text-[9px] font-bold ${p.isUser ? 'opacity-80' : 'text-gray-400'}`}>समय: {formatTime(Math.round(p.timeTaken))}</p>
                                 </div>
                              </div>
                              <span className="font-black text-xl">{p.score}</span>
                           </div>
                         ))}
                      </div>
                   </div>
                </div>
             )}
             <div className="flex flex-col gap-4 max-w-sm mx-auto">
                <button onClick={() => handleNav('LANDING')} className="w-full py-5 bg-orange-600 text-white font-black rounded-[2rem] shadow-xl uppercase text-xl hover:bg-orange-700 active:scale-95 transition-all">मुख्य पृष्ठ (Home)</button>
             </div>
          </div>
        )}
      </main>

      <footer className="w-full p-8 text-center text-gray-400 text-[10px] font-black uppercase tracking-[0.4em] opacity-40">
        &copy; {new Date().getFullYear()} {APP_NAME}
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { AppState, Language, Question, QuizState, Difficulty, HistoryEntry } from './types';
import { fetchQuestions } from './services/geminiService';
import { APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES, DAILY_QUIZ_COUNT } from './constants';

const BOOKMARKS_KEY = 'history_bookmarks';
const HISTORY_KEY = 'quiz_history_data';
const ACTIVE_QUIZ_KEY = 'active_quiz_session';
const DAILY_STATS_KEY = 'daily_stats_v1';
const USER_EMAIL_KEY = 'user_gmail_id';
const USER_PHONE_KEY = 'user_phone_number';

const HINDI_NAMES = [
  "आदित्य शर्मा", "प्रिया पटेल", "राहुल वर्मा", "अंजली सिंह", "संदीप यादव",
  "नेहा गुप्ता", "विकास मिश्रा", "पूजा तिवारी", "अमित राज", "स्नेहा रेड्डी",
  "मनीष बिष्ट", "कविता जोशी", "रोहित मेहरा", "दीपिका पादुकोण", "ऋषभ पंत",
  "श्रेया घोषाल", "अरुण जेटली", "स्मृति ईरानी", "नितिन गडकरी", "शिवानी सिंह",
  "योगेश कुमार", "मंजू कुमारी", "सुनील छेत्री", "साइना नेहवाल"
];

const formatTime = (seconds: number): string => {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  if (h > 0) return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  return `${m}:${s.toString().padStart(2, '0')}`;
};

type ExamStatus = 'LOCKED' | 'UPCOMING' | 'LIVE' | 'CLOSED';

interface LeaderboardEntry {
  name: string;
  score: number;
  timeTaken: number;
  rank: number;
  isUser?: boolean;
  isRisingStar?: boolean;
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState | null>(null);
  const [bookmarks, setBookmarks] = useState<Question[]>([]);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [searchQuery, setSearchQuery] = useState("");
  const [liveParticipants, setLiveParticipants] = useState(0);
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>([]);
  const [isRisingStar, setIsRisingStar] = useState(false);

  // Security & Live Schedule States
  const [isTabActive, setIsTabActive] = useState(true);
  const [multiTabError, setMultiTabError] = useState(false);
  const [disqualified, setDisqualified] = useState(false);
  const [examStatus, setExamStatus] = useState<ExamStatus>('LOCKED');
  const [timeToExam, setTimeToExam] = useState(0); // Seconds until 11 AM or 12 PM

  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [userPhone, setUserPhone] = useState<string | null>(null);
  const [emailInput, setEmailInput] = useState("");
  const [phoneInput, setPhoneInput] = useState("");
  const [showEmailModal, setShowEmailModal] = useState(false);

  const [dailyStreak, setDailyStreak] = useState(0);
  const [lastDailyDate, setLastDailyDate] = useState<string | null>(null);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const syncRef = useRef<boolean>(false);
  const sessionRef = useRef(Math.random().toString(36).substring(7));

  const t = useMemo(() => TRANSLATIONS[language] || TRANSLATIONS[Language.ENGLISH], [language]);

  const isDailyDone = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    return lastDailyDate === todayStr;
  }, [lastDailyDate]);

  // --- LIVE SCHEDULE LOGIC ---
  const checkExamWindow = useCallback(() => {
    const now = new Date();
    const day = now.getDay(); // 0 is Sunday
    const hours = now.getHours();
    const minutes = now.getMinutes();
    const currentTimeInMins = hours * 60 + minutes;

    const startMins = 11 * 60; // 11:00 AM
    const endMins = 12 * 60;   // 12:00 PM

    if (day !== 0) {
      setExamStatus('LOCKED');
      return;
    }

    if (currentTimeInMins < startMins) {
      setExamStatus('UPCOMING');
      setTimeToExam((startMins - currentTimeInMins) * 60 - now.getSeconds());
    } else if (currentTimeInMins >= startMins && currentTimeInMins < endMins) {
      setExamStatus('LIVE');
      setTimeToExam((endMins - currentTimeInMins) * 60 - now.getSeconds());
    } else {
      setExamStatus('CLOSED');
    }
  }, []);

  useEffect(() => {
    checkExamWindow();
    const interval = setInterval(checkExamWindow, 1000);
    return () => clearInterval(interval);
  }, [checkExamWindow]);

  // --- ANTI-CHEAT LOGIC ---
  useEffect(() => {
    const channel = new BroadcastChannel('quiz_session_sync');
    channel.postMessage({ type: 'NEW_SESSION', id: sessionRef.current });
    channel.onmessage = (event) => {
      if (event.data.type === 'NEW_SESSION') {
        setMultiTabError(true);
        if (appState === 'QUIZ' && quiz?.isExamMode) setDisqualified(true);
      }
    };
    const handleContextMenu = (e: MouseEvent) => e.preventDefault();
    const handleKeydown = (e: KeyboardEvent) => {
      if (e.key === 'PrintScreen' || (e.ctrlKey && ['c','u','s','p','i','j'].includes(e.key.toLowerCase()))) {
        e.preventDefault();
        alert("सुरक्षा प्रोटोकॉल: यह क्रिया वर्जित है।");
      }
    };
    window.addEventListener('contextmenu', handleContextMenu);
    window.addEventListener('keydown', handleKeydown);
    const handleVisibilityChange = () => {
      const active = document.visibilityState === 'visible';
      setIsTabActive(active);
      if (!active && appState === 'QUIZ' && quiz?.isExamMode) {
        setDisqualified(true);
        finishQuiz();
      }
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      channel.close();
      window.removeEventListener('contextmenu', handleContextMenu);
      window.removeEventListener('keydown', handleKeydown);
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [appState, quiz?.isExamMode]);

  // --- REGULAR LOGIC ---
  useEffect(() => {
    if (appState === 'QUIZ') {
      const base = quiz?.isExamMode ? 1200 : 45;
      const initial = base + Math.floor(Math.random() * 50);
      setLiveParticipants(initial);
      const interval = setInterval(() => {
        setLiveParticipants(prev => Math.max(prev + (Math.random() > 0.5 ? 2 : -2), 10));
      }, 3000);
      return () => clearInterval(interval);
    }
  }, [appState, quiz?.isExamMode]);

  const playSound = useCallback((type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      const now = ctx.currentTime;
      if (type === 'correct') {
        osc.frequency.setValueAtTime(523, now); osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
        gain.gain.setValueAtTime(0.1, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
      } else if (type === 'incorrect') {
        osc.type = 'sawtooth'; osc.frequency.setValueAtTime(220, now);
        gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
      } else {
        osc.frequency.setValueAtTime(800, now); gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
      }
      osc.start(now); osc.stop(now + 0.3);
    } catch (e) {}
  }, [soundEnabled]);

  const handleNav = useCallback((state: AppState) => {
    playSound('nav');
    setAppState(state);
    if (state !== 'QUIZ') syncRef.current = false;
  }, [playSound]);

  useEffect(() => {
    const savedEmail = localStorage.getItem(USER_EMAIL_KEY);
    const savedPhone = localStorage.getItem(USER_PHONE_KEY);
    if (savedEmail && savedPhone) { setUserEmail(savedEmail); setUserPhone(savedPhone); } else { setShowEmailModal(true); }
    const savedBookmarks = localStorage.getItem(BOOKMARKS_KEY);
    if (savedBookmarks) try { setBookmarks(JSON.parse(savedBookmarks)); } catch (e) {}
    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) try { setHistory(JSON.parse(savedHistory)); } catch (e) {}
    const savedStats = localStorage.getItem(DAILY_STATS_KEY);
    if (savedStats) try { const stats = JSON.parse(savedStats); setDailyStreak(stats.streak || 0); setLastDailyDate(stats.lastDate || null); } catch (e) {}
  }, []);

  const handleUserSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (emailInput.includes('@') && phoneInput.length >= 10) {
      localStorage.setItem(USER_EMAIL_KEY, emailInput);
      localStorage.setItem(USER_PHONE_KEY, phoneInput);
      setUserEmail(emailInput); setUserPhone(phoneInput);
      setShowEmailModal(false); playSound('correct');
    }
  };

  useEffect(() => { localStorage.setItem(BOOKMARKS_KEY, JSON.stringify(bookmarks)); }, [bookmarks]);
  useEffect(() => { localStorage.setItem(HISTORY_KEY, JSON.stringify(history)); }, [history]);

  useEffect(() => {
    if (appState === 'QUIZ' && quiz && quiz.timeRemaining > 0 && !loading && !disqualified) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (!prev) return null;
          // Forced exit at 12:00 PM logic for Exam Mode
          if (prev.isExamMode && examStatus === 'CLOSED') {
             clearInterval(timerRef.current!);
             finishQuiz();
             return null;
          }
          if (prev.timeRemaining <= 1) {
            clearInterval(timerRef.current!);
            handleTimeUp();
            return { ...prev, timeRemaining: 0 };
          }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [appState, loading, quiz?.timeRemaining, disqualified, examStatus]);

  const generateLeaderboard = useCallback((userScore: number, totalQuestions: number, userTimeSeconds: number, userIsRisingStar: boolean) => {
    const participants: LeaderboardEntry[] = [];
    const shuffledNames = [...HINDI_NAMES].sort(() => 0.5 - Math.random());
    for (let i = 0; i < 25; i++) {
      let score = totalQuestions - Math.floor(Math.random() * (totalQuestions * 0.3));
      const isSimulatedRisingStar = Math.random() > 0.85;
      participants.push({ 
        name: shuffledNames[i] || `प्रतियोगी ${i}`, 
        score, 
        timeTaken: score * 15 + Math.random() * 60,
        rank: 0,
        isRisingStar: isSimulatedRisingStar 
      });
    }
    if (!disqualified) participants.push({ 
      name: userEmail?.split('@')[0] || "आप", 
      score: userScore, 
      timeTaken: userTimeSeconds, 
      isUser: true, 
      rank: 0,
      isRisingStar: userIsRisingStar 
    });

    const sorted = participants.sort((a, b) => b.score !== a.score ? b.score - a.score : a.timeTaken - b.timeTaken).slice(0, 20);
    setLeaderboard(sorted.map((p, idx) => ({ ...p, rank: idx + 1 })));
  }, [userEmail, disqualified]);

  const calculateRisingStarStatus = useCallback((currentScore: number, currentTotal: number) => {
    if (history.length < 2) return false;
    const totalScore = history.reduce((sum, entry) => sum + entry.score, 0);
    const totalQuestions = history.reduce((sum, entry) => sum + entry.total, 0);
    const avgAccuracy = totalScore / totalQuestions;
    const currentAccuracy = currentScore / currentTotal;
    return (currentAccuracy > avgAccuracy * 1.3) || (avgAccuracy < 0.5 && currentAccuracy > 0.8);
  }, [history]);

  const finishQuiz = useCallback((attempted?: number) => {
    setQuiz(prev => {
        if (!prev) return null;
        const finalAttempted = attempted ?? (prev.currentIndex + 1);
        const difficultyConfig = DIFFICULTIES.find(d => d.code === prev.difficulty);
        const totalTimeAllowed = prev.isDailyMode ? 1200 : (difficultyConfig?.time || 0);
        const userTimeTaken = totalTimeAllowed - prev.timeRemaining;
        const userRisingStar = calculateRisingStarStatus(prev.score, finalAttempted);
        setIsRisingStar(userRisingStar);

        const newEntry: HistoryEntry = {
          id: Date.now().toString(),
          difficulty: prev.isDailyMode ? 'DAILY' : prev.difficulty,
          score: disqualified ? 0 : prev.score,
          total: finalAttempted,
          skipped: prev.skippedCount,
          date: new Date().toLocaleString(),
          isChallenge: prev.isChallengeMode
        };
        setHistory(h => [newEntry, ...h].slice(0, 50)); 
        generateLeaderboard(disqualified ? 0 : prev.score, finalAttempted, userTimeTaken, userRisingStar);
        setAppState('RESULT');
        return null;
    });
  }, [disqualified, generateLeaderboard, calculateRisingStarStatus]);

  const handleTimeUp = useCallback(() => { playSound('incorrect'); finishQuiz(); }, [playSound, finishQuiz]);

  const backgroundSync = useCallback(async (difficulty: Difficulty, target: number, currentLang: Language, existingCount: number, isDaily: boolean = false) => {
    if (syncRef.current) return; syncRef.current = true;
    let currentCount = existingCount;
    while (currentCount < target && syncRef.current) {
      try {
        const moreQuestions = await fetchQuestions(currentLang, difficulty, 30, isDaily);
        if (moreQuestions.length === 0) break;
        setQuiz(prev => {
          if (!prev) return null;
          const uniqueNew = moreQuestions.filter(mq => !prev.questions.some(pq => pq.text === mq.text));
          return { ...prev, questions: [...prev.questions, ...uniqueNew] };
        });
        currentCount += moreQuestions.length;
      } catch (err) { break; }
      await new Promise(r => setTimeout(r, 2000));
    }
    syncRef.current = false;
  }, []);

  const startQuiz = useCallback(async (difficulty: Difficulty) => {
    if (difficulty === Difficulty.EXAM && examStatus !== 'LIVE') return;
    playSound('nav'); setDisqualified(false); setIsRisingStar(false);
    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true); syncRef.current = true;
    const initialQuestions = await fetchQuestions(language, difficulty, 15);
    let timeLimit = config.time;
    if (difficulty === Difficulty.EXAM) {
      const now = new Date();
      const endWindow = new Date(); endWindow.setHours(12, 0, 0, 0);
      const remainingWindowSecs = Math.floor((endWindow.getTime() - now.getTime()) / 1000);
      timeLimit = Math.min(config.time, remainingWindowSecs);
    }
    setQuiz({
      questions: initialQuestions, currentIndex: 0, score: 0, skippedCount: 0, skipsRemaining: config.maxSkips,
      isComplete: false, difficulty, timeRemaining: timeLimit, totalQuestions: config.count,
      isChallengeMode: difficulty === Difficulty.CHALLENGE, isExamMode: difficulty === Difficulty.EXAM
    });
    setLoading(false); setAppState('QUIZ');
    backgroundSync(difficulty, config.count, language, 15);
  }, [examStatus, playSound, language, backgroundSync]);

  const startDailyQuiz = useCallback(async () => {
    if (isDailyDone) return; playSound('nav'); setLoading(true); syncRef.current = true; setIsRisingStar(false);
    const initialQuestions = await fetchQuestions(language, Difficulty.MEDIUM, 10, true);
    setQuiz({
      questions: initialQuestions, currentIndex: 0, score: 0, skippedCount: 0, skipsRemaining: 10,
      isComplete: false, difficulty: Difficulty.MEDIUM, timeRemaining: 1200, totalQuestions: DAILY_QUIZ_COUNT, isDailyMode: true
    });
    setLoading(false); setAppState('QUIZ');
    backgroundSync(Difficulty.MEDIUM, DAILY_QUIZ_COUNT, language, 10, true);
  }, [isDailyDone, playSound, language, backgroundSync]);

  const handleAnswer = useCallback((index: number) => {
    if (!quiz || selectedAnswer !== null || disqualified) return;
    setSelectedAnswer(index);
    if (quiz.isExamMode) {
      playSound('nav');
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) setQuiz(p => p ? ({ ...p, score: p.score + 1 }) : null);
      setTimeout(() => { setSelectedAnswer(null); if (quiz.currentIndex + 1 < quiz.totalQuestions) setQuiz(p => p ? ({ ...p, currentIndex: p.currentIndex + 1 }) : null); else finishQuiz(); }, 300);
    } else {
      setShowExplanation(true);
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) { playSound('correct'); setQuiz(p => p ? ({ ...p, score: p.score + 1 }) : null); } else playSound('incorrect');
    }
  }, [quiz, selectedAnswer, disqualified, playSound, finishQuiz]);

  const toggleBookmark = useCallback((q: Question) => {
    if (quiz?.isExamMode) return; playSound('nav');
    setBookmarks(prev => prev.find(b => b.id === q.id) ? prev.filter(b => b.id !== q.id) : [...prev, q]);
  }, [quiz?.isExamMode, playSound]);

  return (
    <div className={`min-h-screen flex flex-col items-center bg-[#fffaf0] text-gray-800 transition-all duration-300 select-none ${!isTabActive ? 'blur-2xl grayscale' : ''}`}>

      {multiTabError && (
        <div className="fixed inset-0 z-[200] bg-orange-950 flex flex-col items-center justify-center p-8 text-center text-white">
           <div className="text-8xl mb-6">🚫</div>
           <h2 className="text-4xl font-black mb-4">एकाधिक टैब का पता चला</h2>
           <p className="text-xl max-w-md opacity-80">सुरक्षा कारणों से यह ऐप केवल एक टैब में उपयोग करें।</p>
        </div>
      )}

      {showEmailModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className="bg-white rounded-[3rem] p-8 max-w-md w-full shadow-2xl border-4 border-orange-100 text-center animate-fade-in">
             <div className="w-20 h-20 bg-orange-100 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl">🎓</div>
             <h2 className="text-3xl font-black text-orange-900 mb-2">स्वागत है</h2>
             <p className="text-gray-500 font-medium mb-8 leading-tight">ऐप शुरू करने के लिए अपना Gmail और मोबाइल नंबर दर्ज करें।</p>
             <form onSubmit={handleUserSubmit} className="space-y-4">
                <input type="email" required placeholder="Gmail ID..." value={emailInput} onChange={(e) => setEmailInput(e.target.value)} className="w-full py-4 px-6 rounded-2xl border-2 border-orange-100 focus:border-orange-600 focus:outline-none text-lg font-bold shadow-inner" />
                <input type="tel" required placeholder="Mobile Number..." value={phoneInput} onChange={(e) => setPhoneInput(e.target.value)} className="w-full py-4 px-6 rounded-2xl border-2 border-orange-100 focus:border-orange-600 focus:outline-none text-lg font-bold shadow-inner" />
                <button type="submit" className="w-full py-4 bg-orange-600 hover:bg-orange-700 text-white font-black rounded-2xl shadow-xl transition-transform active:scale-95 uppercase tracking-widest">प्रवेश करें</button>
             </form>
          </div>
        </div>
      )}

      <header className={`w-full p-4 flex justify-between items-center text-white shadow-md z-30 sticky top-0 transition-colors duration-300 ${quiz?.isExamMode ? 'bg-slate-800' : 'bg-orange-600'}`}>
        <span className="font-bold text-lg cursor-pointer flex items-center gap-2" onClick={() => handleNav('LANDING')}>
