                   <p className="font-bold mb-3">{t.selectLang}</p>
                   <div className="grid grid-cols-2 gap-2">
                      {LANGUAGES.map(l => (
                        <button key={l.code} onClick={() => { setLanguage(l.code); handleNav('LANDING'); }} className={`p-2 text-xs font-bold rounded-xl border-2 ${language === l.code ? 'border-orange-600 bg-orange-50' : 'border-gray-50'}`}>{l.name}</button>
                      ))}
                   </div>
                </div>
             </div>
             <button onClick={() => handleNav('LANDING')} className="mt-12 w-full py-4 bg-orange-600 text-white font-black rounded-2xl uppercase">सुरक्षित करें</button>
          </div>
        )}

        {appState === 'RESULT' && (
          <div className="text-center space-y-10 animate-fade-in w-full py-10">
             {disqualified ? (
                 <div className="bg-red-50 border-4 border-red-600 p-8 rounded-[3rem] shadow-2xl">
                     <div className="text-8xl mb-4">⛔</div>
                     <h2 className="text-4xl font-black text-red-700 mb-2">अयोग्य घोषित</h2>
                     <p className="text-red-900 font-bold opacity-80">परीक्षा के नियमों का उल्लंघन हुआ है।</p>
