                            <span className="text-6xl mb-2">🌟</span>
                            <h2 className="text-4xl font-black text-orange-600 tracking-tighter">राइजिंग स्टार (Rising Star)</h2>
                            <p className="text-gray-500 font-bold mt-1 leading-tight">आपने पिछले प्रदर्शन की तुलना में बेहतरीन सुधार दिखाया है!</p>
                         </div>
                      </div>
                   )}

                   <div className="w-full bg-white rounded-[3rem] p-6 shadow-2xl border-4 border-orange-50">
                      <h3 className="text-3xl font-black text-orange-900 mb-6">🏆 लीडरबोर्ड (Rank List)</h3>
                      <div className="space-y-3 max-h-[400px] overflow-y-auto pr-2 scrollbar-thin">
                         {leaderboard.map((p) => (
                           <div key={`${p.name}-${p.rank}`} className={`flex items-center justify-between p-4 rounded-2xl border-2 transition-all duration-300 ${p.isUser ? 'bg-orange-600 text-white scale-[1.03] shadow-lg ring-4 ring-orange-100' : 'bg-white border-orange-50'}`}>
                              <div className="flex items-center gap-4">
                                 <span className={`font-black text-lg w-8 h-8 rounded-full flex items-center justify-center ${p.rank <= 3 ? 'bg-yellow-400 text-yellow-900' : p.isUser ? 'bg-white/20' : 'bg-gray-100'}`}>{p.rank}</span>
