                                    <div className="flex items-center gap-2">
                                       <p className="font-black truncate max-w-[120px]">{p.name}</p>
                                       {p.isRisingStar && <span className="bg-orange-100 text-orange-600 text-[8px] font-black px-1.5 py-0.5 rounded-full border border-orange-200 flex items-center gap-1 animate-bounce">🌟 STAR</span>}
                                    </div>
                                    <p className={`text-[9px] font-bold ${p.isUser ? 'opacity-80' : 'text-gray-400'}`}>समय: {formatTime(Math.round(p.timeTaken))}</p>
                                 </div>
                              </div>
                              <span className="font-black text-xl">{p.score}</span>
                           </div>
                         ))}
                      </div>
                   </div>
                </div>
             )}
             <div className="flex flex-col gap-4 max-w-sm mx-auto">
                <button onClick={() => handleNav('LANDING')} className="w-full py-5 bg-orange-600 text-white font-black rounded-[2rem] shadow-xl uppercase text-xl hover:bg-orange-700 active:scale-95 transition-all">मुख्य पृष्ठ (Home)</button>
             </div>
          </div>
        )}
      </main>

      <footer className="w-full p-8 text-center text-gray-400 text-[10px] font-black uppercase tracking-[0.4em] opacity-40">
        &copy; {new Date().getFullYear()} {APP_NAME}
      </footer>
    </div>
  );
};

