                 <button onClick={() => examStatus === 'LIVE' && startQuiz(Difficulty.EXAM)} disabled={examStatus !== 'LIVE'} className={`w-full py-4 font-black rounded-2xl ${examStatus === 'LIVE' ? 'bg-white text-slate-900' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}`}>
