                </div>
                <div className={`p-6 rounded-3xl border-2 flex justify-between items-center ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-orange-50'}`}>
                   <span className="font-bold">Sound Effects</span>
                   <button onClick={() => setSoundEnabled(!soundEnabled)} className={`px-4 py-1 rounded-full font-black text-xs ${soundEnabled ? 'bg-orange-600 text-white' : 'bg-gray-200 text-gray-500'}`}>{soundEnabled ? 'ON' : 'OFF'}</button>
                </div>
                <div className={`p-6 rounded-3xl border-2 ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-orange-50'}`}>
                   <p className="font-bold mb-4">भाषा चुनें (8 भाषाएँ)</p>
                   <div className="grid grid-cols-2 gap-2">
                      {LANGUAGES.map(lang => (
                        <button key={lang.code} onClick={() => { setLanguage(lang.code); handleNav('LANDING'); }} className={`py-2 px-3 rounded-xl border-2 font-bold text-xs ${language === lang.code ? 'border-orange-600 bg-orange-50 text-orange-900' : 'border-transparent bg-gray-100 text-gray-600'}`}>
