                    <span className={`w-10 h-10 rounded-full flex items-center justify-center font-black mr-4 ${darkMode ? 'bg-slate-800' : 'bg-gray-100'}`}>{String.fromCharCode(65 + idx)}</span>
                    <span className="text-xl font-bold">{option}</span>
                  </button>
                ))}
              </div>
              {showExplanation && !quiz.isExamMode && (
                <div className={`p-8 border-4 border-blue-600 rounded-[2.5rem] shadow-xl ${darkMode ? 'bg-slate-900' : 'bg-blue-50'}`}>
                  <p className={`text-lg mb-6 ${darkMode ? 'text-blue-200' : 'text-blue-800'}`}>{quiz.questions[quiz.currentIndex].explanation}</p>
                  <button onClick={() => { window.speechSynthesis.cancel(); setShowExplanation(false); setSelectedAnswer(null); if (quiz.currentIndex + 1 < quiz.questions.length) setQuiz(p => p ? ({ ...p, currentIndex: p.currentIndex + 1 }) : null); else finishQuiz(); }} className="w-full bg-blue-600 text-white font-black py-5 rounded-3xl uppercase">अगला प्रश्न</button>
                </div>
              )}
            </div>
          </div>
        )}

        {appState === 'RESULT' && (
          <div className="text-center space-y-8 animate-fade-in w-full py-6">
             <div className={`${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-orange-50'} rounded-[3rem] p-8 shadow-2xl border-4`}>
                <h2 className="text-4xl font-black text-orange-600 mb-2">आपका परिणाम</h2>
                <div className={`flex flex-col items-center justify-center p-4 rounded-3xl mb-4 ${darkMode ? 'bg-slate-800' : 'bg-orange-50'}`}>
                   <p className="text-sm font-bold opacity-50">Gmail: {userEmail}</p>
                   <div className="text-6xl font-black mt-2">{leaderboard.find(p=>p.isUser)?.score || 0}</div>
                   <p className="text-xs font-black uppercase tracking-widest mt-1">अंक प्राप्त</p>
                </div>
             </div>

             <div className={`${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-orange-50'} rounded-[3rem] p-6 shadow-2xl border-4`}>
                <h3 className="text-3xl font-black mb-6">🏆 टॉपर्स सूची (Rank List)</h3>
                <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2 scrollbar-thin">
                   {leaderboard.map((p) => (
                     <div key={p.rank} className={`p-5 rounded-3xl border-2 transition-all duration-300 ${p.isUser ? 'bg-orange-600 text-white shadow-xl ring-4 ring-orange-100' : darkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-orange-50'}`}>
                        <div className="flex justify-between items-center mb-2">
                           <div className="flex items-center gap-3">
                              <span className={`w-8 h-8 rounded-full flex items-center justify-center font-black ${p.rank <= 3 ? 'bg-yellow-400 text-yellow-900' : 'bg-gray-100 text-gray-400'}`}>{p.rank}</span>
                              <div className="text-left">
                                 <p className="font-black text-lg flex items-center gap-2">
                                    {p.name} {p.isRisingStar && <span className="text-sm animate-bounce">🌟</span>}
                                 </p>
                                 <p className={`text-[10px] font-bold ${p.isUser ? 'text-white/80' : 'text-gray-400'}`}>ID: {p.email.split('@')[0]}</p>
                              </div>
                           </div>
                           <div className="text-right">
                              <span className="font-black text-2xl">{p.score}</span>
                              <p className={`text-[9px] font-bold opacity-60`}>समय: {formatTime(Math.round(p.timeTaken))}</p>
                           </div>
                        </div>
                        <div className="flex gap-2 mt-3">
                           <a href={`tel:${p.phone}`} className={`flex-1 py-2 rounded-xl font-black text-[10px] text-center uppercase tracking-widest ${p.isUser ? 'bg-white/20 text-white' : 'bg-green-50 text-green-600'}`}>📞 Call</a>
                           <a href={`mailto:${p.email}?subject=भारतीय इतिहास ऐप - पुरस्कार विजेता!`} className={`flex-1 py-2 rounded-xl font-black text-[10px] text-center uppercase tracking-widest ${p.isUser ? 'bg-white/20 text-white' : 'bg-blue-50 text-blue-600'}`}>✉️ Email</a>
                        </div>
                     </div>
                   ))}
                </div>
             </div>

             <button onClick={() => handleNav('LANDING')} className="w-full py-5 bg-orange-600 text-white font-black rounded-[2rem] shadow-xl uppercase text-xl active:scale-95 transition-all">मुख्य पृष्ठ (Home)</button>
          </div>
        )}
      </main>

      <footer className="w-full p-8 text-center text-gray-400 text-[10px] font-black uppercase tracking-[0.4em] opacity-40">
        &copy; {new Date().getFullYear()} {APP_NAME}
      </footer>
    </div>
  );
};

export default App;

export enum Language {
  HINDI = 'HINDI',
  ENGLISH = 'ENGLISH',
  SANSKRIT = 'SANSKRIT',
  TAMIL = 'TAMIL',
  TELUGU = 'TELUGU',
  MARATHI = 'MARATHI',
  BENGALI = 'BENGALI',
  GUJARATI = 'GUJARATI'
}

export enum Difficulty {
  EASY = 'EASY',
  MEDIUM = 'MEDIUM',
  HARD = 'HARD',
  CHALLENGE = 'CHALLENGE',
  EXAM = 'EXAM'
}

export interface Question {
  id: string;
  text: string;
  options: string[];
  correctAnswer: number;
  explanation: string;
  era: 'Ancient' | 'Medieval' | 'Modern';
  sources?: { title: string; uri: string }[];
}

export interface HistoryEntry {
  id: string;
  difficulty: Difficulty | 'DAILY';
  score: number;
  total: number;
  skipped: number;
  date: string;
  isChallenge?: boolean;
}

export type AppState = 'LANDING' | 'DIFFICULTY_SELECT' | 'QUIZ' | 'SETTINGS' | 'RESULT' | 'BOOKMARKS' | 'HISTORY' | 'COUNTDOWN' | 'LIBRARY';

export interface QuizState {
  questions: Question[];
  currentIndex: number;
  score: number;
  skippedCount: number;
  skipsRemaining: number;
  isComplete: boolean;
  difficulty: Difficulty;
  timeRemaining: number;
  totalQuestions: number;
  isChallengeMode?: boolean;
  isDailyMode?: boolean;
  isExamMode?: boolean;
}

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { AppState, Language, Question, QuizState, Difficulty, HistoryEntry } from './types';
import { fetchQuestions } from './services/geminiService';
import { APP_NAME, INTRO_MAIN, INTRO_SUB, TRANSLATIONS, LANGUAGES, DIFFICULTIES, DAILY_QUIZ_COUNT } from './constants';

const BOOKMARKS_KEY = 'history_bookmarks';
const HISTORY_KEY = 'quiz_history_data';
const USER_EMAIL_KEY = 'user_gmail_id';
const USER_PHONE_KEY = 'user_phone_number';
const DARK_MODE_KEY = 'app_dark_mode';
const VOICE_ENABLED_KEY = 'app_voice_enabled';

const HINDI_NAMES = [
  "आदित्य शर्मा", "प्रिया पटेल", "राहुल वर्मा", "अंजली सिंह", "संदीप यादव",
  "नेहा गुप्ता", "विकास मिश्रा", "पूजा तिवारी", "अमित राज", "स्नेहा रेड्डी",
  "मनीष बिष्ट", "कविता जोशी", "रोहित मेहरा", "दीपिका पादुकोण", "ऋषभ पंत",
  "श्रेया घोषाल", "अरुण जेटली", "स्मृति ईरानी", "नितิน गडकरी", "शिवानी सिंह"
];

const formatTime = (seconds: number): string => {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = seconds % 60;
  if (h > 0) return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  return `${m}:${s.toString().padStart(2, '0')}`;
};

type ExamStatus = 'LOCKED' | 'UPCOMING' | 'LIVE' | 'CLOSED';

interface LeaderboardEntry {
  name: string;
  email: string;
  phone: string;
  score: number;
  timeTaken: number;
  rank: number;
  isUser?: boolean;
  isRisingStar?: boolean;
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>('LANDING');
  const [language, setLanguage] = useState<Language>(Language.HINDI);
  const [quiz, setQuiz] = useState<QuizState | null>(null);
  const [libraryQuestions, setLibraryQuestions] = useState<Question[]>([]);
  const [bookmarks, setBookmarks] = useState<Question[]>([]);
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showExplanation, setShowExplanation] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [voiceEnabled, setVoiceEnabled] = useState(false);
  const [darkMode, setDarkMode] = useState(false);
  const [leaderboard, setLeaderboard] = useState<LeaderboardEntry[]>([]);
  const [isRisingStar, setIsRisingStar] = useState(false);

  // Security & Live Schedule States
  const [isTabActive, setIsTabActive] = useState(true);
  const [multiTabError, setMultiTabError] = useState(false);
  const [disqualified, setDisqualified] = useState(false);
  const [examStatus, setExamStatus] = useState<ExamStatus>('LOCKED');
  const [timeToExam, setTimeToExam] = useState(0);

  const [userEmail, setUserEmail] = useState<string | null>(null);
  const [userPhone, setUserPhone] = useState<string | null>(null);
  const [emailInput, setEmailInput] = useState("");
  const [phoneInput, setPhoneInput] = useState("");
  const [showEmailModal, setShowEmailModal] = useState(false);

  const audioCtxRef = useRef<AudioContext | null>(null);
  const timerRef = useRef<number | null>(null);
  const sessionRef = useRef(Math.random().toString(36).substring(7));

  const speakText = useCallback((text: string) => {
    if (!('speechSynthesis' in window)) return;
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    const langMap: Record<string, string> = {
      'HINDI': 'hi-IN', 'ENGLISH': 'en-US', 'SANSKRIT': 'hi-IN', 
      'TAMIL': 'ta-IN', 'TELUGU': 'te-IN', 'MARATHI': 'mr-IN', 
      'BENGALI': 'bn-IN', 'GUJARATI': 'gu-IN'
    };
    utterance.lang = langMap[language] || 'hi-IN';
    window.speechSynthesis.speak(utterance);
  }, [language]);

  const checkExamWindow = useCallback(() => {
    const now = new Date();
    const day = now.getDay();
    const currentTimeInMins = now.getHours() * 60 + now.getMinutes();
    const startMins = 11 * 60;
    const endMins = 12 * 60;
    if (day !== 0) { setExamStatus('LOCKED'); return; }
    if (currentTimeInMins < startMins) {
      setExamStatus('UPCOMING');
      setTimeToExam((startMins - currentTimeInMins) * 60 - now.getSeconds());
    } else if (currentTimeInMins >= startMins && currentTimeInMins < endMins) {
      setExamStatus('LIVE');
      setTimeToExam((endMins - currentTimeInMins) * 60 - now.getSeconds());
    } else {
      setExamStatus('CLOSED');
    }
  }, []);

  useEffect(() => {
    checkExamWindow();
    const interval = setInterval(checkExamWindow, 1000);
    return () => clearInterval(interval);
  }, [checkExamWindow]);

  useEffect(() => {
    const channel = new BroadcastChannel('quiz_session_sync');
    channel.postMessage({ type: 'NEW_SESSION', id: sessionRef.current });
    channel.onmessage = (event) => {
      if (event.data.type === 'NEW_SESSION') setMultiTabError(true);
    };
    const handleVisibilityChange = () => {
      const active = document.visibilityState === 'visible';
      setIsTabActive(active);
      if (!active && appState === 'QUIZ' && quiz?.isExamMode) {
        setDisqualified(true);
        finishQuiz();
      }
    };
    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => {
      channel.close();
      document.removeEventListener('visibilitychange', handleVisibilityChange);
    };
  }, [appState, quiz?.isExamMode]);

  const playSound = useCallback((type: 'correct' | 'incorrect' | 'nav') => {
    if (!soundEnabled) return;
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      const now = ctx.currentTime;
      if (type === 'correct') {
        osc.frequency.setValueAtTime(523, now); osc.frequency.exponentialRampToValueAtTime(880, now + 0.1);
        gain.gain.setValueAtTime(0.1, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
      } else if (type === 'incorrect') {
        osc.type = 'sawtooth'; osc.frequency.setValueAtTime(220, now);
        gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
      } else {
        osc.frequency.setValueAtTime(800, now); gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
      }
      osc.start(now); osc.stop(now + 0.3);
    } catch (e) {}
  }, [soundEnabled]);

  const handleNav = useCallback((state: AppState) => {
    playSound('nav'); setAppState(state);
    if (state !== 'QUIZ' && state !== 'LIBRARY') {
      window.speechSynthesis.cancel();
    }
    if (state === 'LIBRARY' && libraryQuestions.length === 0) {
      loadLibrary();
    }
  }, [playSound, libraryQuestions.length]);

  const loadLibrary = async () => {
    setLoading(true);
    const qs = await fetchQuestions(language, Difficulty.MEDIUM, 20);
    setLibraryQuestions(qs);
    setLoading(false);
  };

  const loadMoreLibrary = async () => {
    const qs = await fetchQuestions(language, Difficulty.HARD, 10);
    setLibraryQuestions(prev => [...prev, ...qs]);
  };

  useEffect(() => {
    const savedEmail = localStorage.getItem(USER_EMAIL_KEY);
    const savedPhone = localStorage.getItem(USER_PHONE_KEY);
    if (savedEmail && savedPhone) { setUserEmail(savedEmail); setUserPhone(savedPhone); } else { setShowEmailModal(true); }
    const savedBookmarks = localStorage.getItem(BOOKMARKS_KEY);
    if (savedBookmarks) try { setBookmarks(JSON.parse(savedBookmarks)); } catch (e) {}
    const savedHistory = localStorage.getItem(HISTORY_KEY);
    if (savedHistory) try { setHistory(JSON.parse(savedHistory)); } catch (e) {}
    const savedDarkMode = localStorage.getItem(DARK_MODE_KEY);
    if (savedDarkMode) setDarkMode(savedDarkMode === 'true');
    const savedVoice = localStorage.getItem(VOICE_ENABLED_KEY);
    if (savedVoice) setVoiceEnabled(savedVoice === 'true');
  }, []);

  useEffect(() => {
    localStorage.setItem(DARK_MODE_KEY, darkMode.toString());
    localStorage.setItem(VOICE_ENABLED_KEY, voiceEnabled.toString());
  }, [darkMode, voiceEnabled]);

  const handleUserSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (emailInput.includes('@') && phoneInput.length >= 10) {
      localStorage.setItem(USER_EMAIL_KEY, emailInput);
      localStorage.setItem(USER_PHONE_KEY, phoneInput);
      setUserEmail(emailInput); setUserPhone(phoneInput);
      setShowEmailModal(false); playSound('correct');
    }
  };

  useEffect(() => {
    if (appState === 'QUIZ' && quiz && quiz.timeRemaining > 0 && !loading && !disqualified) {
      timerRef.current = window.setInterval(() => {
        setQuiz(prev => {
          if (!prev) return null;
          if (prev.isExamMode && examStatus === 'CLOSED') { clearInterval(timerRef.current!); finishQuiz(); return null; }
          if (prev.timeRemaining <= 1) { clearInterval(timerRef.current!); finishQuiz(); return { ...prev, timeRemaining: 0 }; }
          return { ...prev, timeRemaining: prev.timeRemaining - 1 };
        });
      }, 1000);
    } else { if (timerRef.current) clearInterval(timerRef.current); }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [appState, loading, quiz?.timeRemaining, disqualified, examStatus]);

  useEffect(() => {
    if (appState === 'QUIZ' && quiz && voiceEnabled && !loading) {
      const q = quiz.questions[quiz.currentIndex];
      if (q) speakText(q.text);
    }
  }, [appState, quiz?.currentIndex, voiceEnabled, loading, speakText]);

  const generateLeaderboard = useCallback((userScore: number, totalQuestions: number, userTimeSeconds: number, userIsRisingStar: boolean) => {
    const participants: LeaderboardEntry[] = [];
    HINDI_NAMES.forEach((name, i) => {
      let score = totalQuestions - Math.floor(Math.random() * (totalQuestions * 0.4));
      participants.push({ 
        name, email: `student${i}@gmail.com`, phone: `9876543${i}10`,
        score, timeTaken: score * 12 + Math.random() * 120, rank: 0,
        isRisingStar: Math.random() > 0.8
      });
    });
    if (!disqualified) participants.push({ 
      name: userEmail?.split('@')[0] || "आप", email: userEmail || "", phone: userPhone || "",
      score: userScore, timeTaken: userTimeSeconds, isUser: true, rank: 0, isRisingStar: userIsRisingStar 
    });
    const sorted = participants.sort((a, b) => b.score !== a.score ? b.score - a.score : a.timeTaken - b.timeTaken).slice(0, 15);
    setLeaderboard(sorted.map((p, idx) => ({ ...p, rank: idx + 1 })));
  }, [userEmail, userPhone, disqualified]);

  const finishQuiz = useCallback((attempted?: number) => {
    window.speechSynthesis.cancel();
    setQuiz(prev => {
        if (!prev) return null;
        const finalAttempted = attempted ?? (prev.currentIndex + 1);
        const config = DIFFICULTIES.find(d => d.code === prev.difficulty);
        const userTimeTaken = (config?.time || 0) - prev.timeRemaining;
        generateLeaderboard(disqualified ? 0 : prev.score, finalAttempted, userTimeTaken, false);
        setAppState('RESULT');
        return null;
    });
  }, [disqualified, generateLeaderboard]);

  const startQuiz = useCallback(async (difficulty: Difficulty) => {
    if (difficulty === Difficulty.EXAM && examStatus !== 'LIVE') return;
    playSound('nav'); setDisqualified(false); setIsRisingStar(false);
    const config = DIFFICULTIES.find(d => d.code === difficulty) || DIFFICULTIES[1];
    setLoading(true);
    const initialQuestions = await fetchQuestions(language, difficulty, 10);
    setQuiz({
      questions: initialQuestions, currentIndex: 0, score: 0, skippedCount: 0, skipsRemaining: config.maxSkips,
      isComplete: false, difficulty, timeRemaining: config.time, totalQuestions: config.count,
      isExamMode: difficulty === Difficulty.EXAM
    });
    setLoading(false); setAppState('QUIZ');
  }, [examStatus, playSound, language]);

  const handleAnswer = useCallback((index: number) => {
    if (!quiz || selectedAnswer !== null || disqualified) return;
    setSelectedAnswer(index);
    if (quiz.isExamMode) {
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) setQuiz(p => p ? ({ ...p, score: p.score + 1 }) : null);
      setTimeout(() => { setSelectedAnswer(null); if (quiz.currentIndex + 1 < quiz.totalQuestions) setQuiz(p => p ? ({ ...p, currentIndex: p.currentIndex + 1 }) : null); else finishQuiz(); }, 200);
    } else {
      setShowExplanation(true);
      if (voiceEnabled) speakText(quiz.questions[quiz.currentIndex].explanation);
      if (index === quiz.questions[quiz.currentIndex].correctAnswer) { playSound('correct'); setQuiz(p => p ? ({ ...p, score: p.score + 1 }) : null); } else playSound('incorrect');
    }
  }, [quiz, selectedAnswer, disqualified, playSound, finishQuiz, voiceEnabled, speakText]);

  return (
    <div className={`min-h-screen flex flex-col items-center transition-all duration-300 select-none ${darkMode ? 'bg-slate-950 text-slate-100' : 'bg-[#fffaf0] text-gray-800'} ${!isTabActive ? 'blur-2xl' : ''}`}>

      {multiTabError && (
        <div className="fixed inset-0 z-[200] bg-orange-950 flex flex-col items-center justify-center p-8 text-center text-white">
           <h2 className="text-4xl font-black mb-4">सुरक्षा अलर्ट</h2>
           <p className="text-xl opacity-80">कृपया केवल एक टैब में ऐप चलाएं।</p>
        </div>
      )}

      {showEmailModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/70 backdrop-blur-sm p-4">
          <div className={`${darkMode ? 'bg-slate-900 border-slate-700' : 'bg-white border-orange-100'} rounded-[3rem] p-8 max-w-md w-full shadow-2xl border-4 text-center animate-fade-in`}>
             <div className="w-20 h-20 bg-orange-100 rounded-full flex items-center justify-center mx-auto mb-6 text-4xl">🎓</div>
             <h2 className={`text-3xl font-black mb-2 ${darkMode ? 'text-white' : 'text-orange-900'}`}>रजिस्ट्रेशन</h2>
             <form onSubmit={handleUserSubmit} className="space-y-4">
                <input type="email" required placeholder="Gmail ID..." value={emailInput} onChange={(e) => setEmailInput(e.target.value)} className={`w-full py-4 px-6 rounded-2xl border-2 focus:border-orange-600 focus:outline-none text-lg font-bold shadow-inner ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-orange-100'}`} />
                <input type="tel" required placeholder="Mobile Number..." value={phoneInput} onChange={(e) => setPhoneInput(e.target.value)} className={`w-full py-4 px-6 rounded-2xl border-2 focus:border-orange-600 focus:outline-none text-lg font-bold shadow-inner ${darkMode ? 'bg-slate-800 border-slate-700 text-white' : 'bg-white border-orange-100'}`} />
                <button type="submit" className="w-full py-4 bg-orange-600 hover:bg-orange-700 text-white font-black rounded-2xl shadow-xl transition-transform active:scale-95 uppercase tracking-widest">प्रवेश करें</button>
             </form>
          </div>
        </div>
      )}

      <header className={`w-full p-4 flex justify-between items-center text-white shadow-md z-30 sticky top-0 ${quiz?.isExamMode ? 'bg-slate-800' : 'bg-orange-600'}`}>
        <span className="font-bold text-lg cursor-pointer" onClick={() => handleNav('LANDING')}>
          <span className="bg-white text-orange-600 w-8 h-8 rounded-full flex items-center justify-center font-black">इ</span>
        </span>
        <div className="flex gap-2 items-center">
          <button onClick={() => handleNav('LIBRARY')} className="bg-white/20 p-2 rounded-full">📚</button>
          <button onClick={() => handleNav('SETTINGS')} className="bg-white/20 p-2 rounded-full">⚙️</button>
        </div>
      </header>

      <main className="flex-1 w-full max-w-2xl px-4 py-8 flex flex-col items-center">
        {appState === 'LANDING' && (
          <div className="text-center animate-fade-in py-10 w-full">
            <h1 className={`text-7xl md:text-9xl font-black mb-2 hindi-font tracking-tighter ${darkMode ? 'text-orange-500' : 'text-orange-600'}`}>{INTRO_MAIN}</h1>
            <p className={`text-xl md:text-3xl font-bold mb-12 italic opacity-80 ${darkMode ? 'text-slate-400' : 'text-orange-800'}`}>"{INTRO_SUB}"</p>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-12">
              <div className={`p-6 rounded-[2.5rem] border-4 shadow-xl text-left flex flex-col justify-between h-56 transition-all ${examStatus === 'LIVE' ? 'border-indigo-400 bg-indigo-900' : darkMode ? 'bg-slate-900 border-slate-800' : 'bg-slate-900 border-slate-100'}`}>
                 <div>
                    <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${examStatus === 'LIVE' ? 'bg-red-600 text-white animate-pulse' : 'bg-slate-700 text-white'}`}>LIVE NOW</span>
                    <h3 className="text-2xl font-black mt-4 text-white">2000+ प्रश्न बैंक</h3>
                    <p className="text-xs font-bold mt-1 text-slate-400 italic">भारत का संपूर्ण इतिहास एक जगह</p>
                 </div>
                 <button onClick={() => handleNav('LIBRARY')} className="w-full py-4 bg-white text-slate-900 font-black rounded-2xl uppercase">खोलें (Library)</button>
              </div>

              <div className="p-6 rounded-[2.5rem] border-4 shadow-xl text-left bg-orange-600 border-orange-700 text-white flex flex-col justify-between h-56 cursor-pointer transform hover:scale-105 transition-all" onClick={() => startQuiz(Difficulty.HARD)}>
                 <div>
                    <span className="text-[10px] font-black uppercase px-3 py-1 rounded-full bg-white/20">नॉन-स्टॉप</span>
                    <h3 className="text-2xl font-black mt-4">🔥 मैराथन क्विज़</h3>
                    <p className="text-xs opacity-70">1000+ कठिन प्रश्न - अपनी सीमा जानें</p>
                 </div>
                 <button className="w-full py-4 bg-white text-orange-600 font-black rounded-2xl uppercase text-sm">शुरू करें</button>
              </div>
            </div>

            <button onClick={() => handleNav('DIFFICULTY_SELECT')} className="w-full py-5 px-8 bg-orange-600 text-white font-black text-2xl rounded-3xl shadow-2xl transform hover:scale-105 transition-all uppercase">टेस्ट शुरू करें (Quiz)</button>
          </div>
        )}

        {appState === 'LIBRARY' && (
          <div className="w-full animate-fade-in space-y-6">
            <div className="flex justify-between items-center">
               <h2 className="text-3xl font-black">📚 प्रश्न लाइब्रेरी (2000+)</h2>
               <button onClick={() => handleNav('LANDING')} className="p-2 bg-orange-600 text-white rounded-xl">✖</button>
            </div>
            {loading ? (
              <div className="text-center py-20 animate-pulse text-2xl font-black">प्रश्न लोड हो रहे हैं...</div>
            ) : (
              <div className="space-y-4">
                {libraryQuestions.map((q, i) => (
                  <div key={i} className={`p-6 rounded-3xl border-2 transition-all ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-orange-50'}`}>
                    <div className="flex justify-between mb-4">
                      <span className="text-[10px] font-black uppercase bg-orange-100 text-orange-600 px-3 py-1 rounded-full">{q.era} India</span>
                      <button onClick={() => speakText(q.text)} className="text-xl">🔊</button>
                    </div>
                    <p className="text-xl font-black mb-4">{i + 1}. {q.text}</p>
                    <div className="grid grid-cols-1 gap-2 mb-4">
                       {q.options.map((opt, idx) => (
                         <div key={idx} className={`p-3 rounded-xl border font-bold ${idx === q.correctAnswer ? 'bg-green-100 border-green-300 text-green-900' : 'bg-gray-50 border-gray-100 opacity-60'}`}>
                           {opt} {idx === q.correctAnswer && "✓"}
                         </div>
                       ))}
                    </div>
                    <p className="text-xs italic opacity-70 border-t pt-4 mt-4">{q.explanation}</p>
                  </div>
                ))}
                <button onClick={loadMoreLibrary} className="w-full py-6 bg-orange-600 text-white font-black rounded-3xl text-xl shadow-xl uppercase">और प्रश्न लोड करें (Load More)</button>
              </div>
            )}
          </div>
        )}

        {appState === 'SETTINGS' && (
          <div className="w-full animate-fade-in py-10 max-w-sm">
             <h2 className="text-3xl font-black mb-8 text-center">सेटिंग्स</h2>
             <div className="space-y-4">
                <div className={`p-6 rounded-3xl border-2 flex justify-between items-center ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-orange-50'}`}>
                   <span className="font-bold">Dark Mode</span>
                   <button onClick={() => setDarkMode(!darkMode)} className={`w-14 h-8 rounded-full relative transition-colors ${darkMode ? 'bg-orange-600' : 'bg-gray-300'}`}>
                      <div className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-all ${darkMode ? 'left-7' : 'left-1'}`}></div>
                   </button>
                </div>
                <div className={`p-6 rounded-3xl border-2 flex justify-between items-center ${darkMode ? 'bg-slate-900 border-slate-800' : 'bg-white border-orange-50'}`}>
                   <span className="font-bold">Voice (आवाज)</span>
                   <button onClick={() => { setVoiceEnabled(!voiceEnabled); if(voiceEnabled) window.speechSynthesis.cancel(); }} className={`w-14 h-8 rounded-full relative transition-colors ${voiceEnabled ? 'bg-blue-600' : 'bg-gray-300'}`}>
                      <div className={`absolute top-1 w-6 h-6 bg-white rounded-full transition-all ${voiceEnabled ? 'left-7' : 'left-1'}`}></div>
                   </button>
                </div>
             </div>
             <button onClick={() => handleNav('LANDING')} className="mt-8 w-full py-4 bg-orange-600 text-white font-black rounded-2xl uppercase">सुरक्षित करें</button>
          </div>
        )}

        {/* Existing Quiz & Result Logic Maintained... */}
        {appState === 'QUIZ' && quiz && (
           <div className="w-full pb-20 animate-fade-in">
             <div className="space-y-8">
               <div className={`flex justify-between items-center text-sm font-black ${darkMode ? 'text-slate-400' : 'text-orange-900'}`}>
                 <span className="opacity-50">{quiz.currentIndex + 1} / {quiz.totalQuestions}</span>
                 <span className={`text-xl font-mono ${quiz.timeRemaining < 60 ? 'text-red-600 animate-pulse' : ''}`}>{formatTime(quiz.timeRemaining)}</span>
                 <button onClick={() => speakText(quiz.questions[quiz.currentIndex].text)} className="w-10 h-10 rounded-full flex items-center justify-center bg-gray-100/10">🔊</button>
               </div>
               <h2 className={`text-3xl font-black leading-tight hindi-font ${darkMode ? 'text-white' : 'text-gray-900'}`}>{quiz.questions[quiz.currentIndex].text}</h2>
               <div className="grid grid-cols-1 gap-4">
                 {quiz.questions[quiz.currentIndex].options.map((option, idx) => (
                   <button key={idx} onClick={() => handleAnswer(idx)} disabled={selectedAnswer !== null} className={`p-5 text-left rounded-3xl border-4 transition-all flex items-center ${selectedAnswer === null ? (darkMode ? 'bg-slate-900 border-slate-800 hover:border-orange-600' : 'border-orange-50 bg-white hover:border-orange-600') : (idx === quiz.questions[quiz.currentIndex].correctAnswer) ? 'border-green-600 bg-green-50 text-green-900' : (selectedAnswer === idx) ? 'border-red-600 bg-red-50 text-red-900' : 'opacity-40'}`}>
                     <span className={`w-10 h-10 rounded-full flex items-center justify-center font-black mr-4 ${darkMode ? 'bg-slate-800' : 'bg-gray-100'}`}>{String.fromCharCode(65 + idx)}</span>
                     <span className="text-xl font-bold">{option}</span>
                   </button>
                 ))}
               </div>
               {showExplanation && (
                 <div className={`p-8 border-4 border-blue-600 rounded-[2.5rem] shadow-xl ${darkMode ? 'bg-slate-900' : 'bg-blue-50'}`}>
                   <p className={`text-lg mb-6 ${darkMode ? 'text-blue-200' : 'text-blue-800'}`}>{quiz.questions[quiz.currentIndex].explanation}</p>
                   <button onClick={() => { window.speechSynthesis.cancel(); setShowExplanation(false); setSelectedAnswer(null); if (quiz.currentIndex + 1 < quiz.questions.length) setQuiz(p => p ? ({ ...p, currentIndex: p.currentIndex + 1 }) : null); else finishQuiz(); }} className="w-full bg-blue-600 text-white font-black py-5 rounded-3xl uppercase">अगला प्रश्न</button>
                 </div>
               )}
             </div>
           </div>
        )}
      </main>

      <footer className="w-full p-8 text-center text-gray-400 text-[10px] font-black uppercase tracking-[0.4em] opacity-40">
        &copy; {new Date().getFullYear()} {APP_NAME}
      </footer>
    </div>
  );
};

export default App;

