                          <a href={`mailto:${p.email}?subject=इतिहास ऐप - बधाई!`} className={`flex-1 py-2 rounded-xl font-black text-[10px] text-center uppercase tracking-widest ${p.isUser ? 'bg-white/20 text-white' : 'bg-blue-50 text-blue-600 border border-blue-200'}`}>✉️ Email</a>
