                        {t.verify}
                     </button>
                     <button onClick={() => { window.speechSynthesis.cancel(); setShowExplanation(false); setSelectedAnswer(null); if (quiz.currentIndex + 1 < quiz.questions.length) setQuiz(p => p ? ({ ...p, currentIndex: p.currentIndex + 1 }) : null); else finishQuiz(); }} className="flex-[2] bg-blue-600 text-white font-black py-5 rounded-3xl uppercase text-xl shadow-lg">{t.next}</button>
                   </div>
                 </div>
               )}
             </div>
           </div>
        )}

        {appState === 'DIFFICULTY_SELECT' && (
          <div className="w-full animate-fade-in py-6">
            <h2 className={`text-4xl font-black mb-8 text-center ${darkMode ? 'text-white' : 'text-orange-900'}`}>{t.selectDifficulty}</h2>
            <div className="grid grid-cols-1 gap-4">
              {DIFFICULTIES.slice(0, 3).map(diff => (
